            'title' => 'Informe paciente',
            'payment_mode' => 'free',
            'payment_status' => 'paid',
            'visibility' => 'internal',
            'implemented' => true
        ],
        'clinical_summary' => [
            'report_type' => 'clinical',
            'title' => 'Informe clínico',
            'payment_mode' => 'paid',
            'payment_status' => 'pending',
            'visibility' => 'internal',
            'implemented' => true
        ],
        'evolution_report' => [
            'report_type' => 'evolution',
