function appointment_patient_knowledge_problem_payload($mysqli, $patient_id)
{
    $patient_id = (int) $patient_id;
    if ($patient_id <= 0 || !app_feature_enabled_from_db($mysqli, 'knowledgeBase.enabled', false)) {
        return [
            'enabled' => false,
            'status' => 'disabled'
        ];
    }

    $allowed_sectors = allowed_knowledge_sector_keys($mysqli);
    if (!$allowed_sectors) {
        return [
            'enabled' => false,
            'status' => 'no_sector_data'
        ];
    }

    $tenant_id = current_tenant_id();
    $stmt = $mysqli->prepare("
        SELECT pp.initial_consultation_reason,
               pd.id AS diagnosis_id, pd.source_type, pd.manual_label, pd.selected_objective,
               kp.id, kp.sector_key, kp.name, kp.alias AS short_name, ka.name AS area, kp.population AS category, kp.risk_level, kp.population AS target_population
        FROM patient_profiles pp
        LEFT JOIN patient_diagnoses pd
          ON pd.tenant_id = pp.tenant_id
         AND pd.patient_id = pp.user_id
         AND pd.status = 'active'
        LEFT JOIN knowledge_problems kp
          ON kp.id = COALESCE(pd.knowledge_problem_id, pp.knowledge_problem_id)
         AND kp.sector_key IN (" . knowledge_sector_in_sql($mysqli, $allowed_sectors) . ")
        LEFT JOIN knowledge_areas ka
          ON ka.id = kp.area_id
         AND ka.sector_key = kp.sector_key
        WHERE pp.tenant_id = ?
          AND pp.user_id = ?
        ORDER BY pd.is_primary DESC, pd.sort_order ASC, pd.id ASC
        LIMIT 1
    ");
    $stmt->bind_param("ii", $tenant_id, $patient_id);
    $stmt->execute();
    $problem = $stmt->get_result()->fetch_assoc();
    $diagnosis_name = trim((string) ($problem['name'] ?? ''));
    if ($diagnosis_name === '') {
        $diagnosis_name = trim((string) ($problem['manual_label'] ?? ''));
    }
    if ($diagnosis_name === '') {
        $consultation_reason = trim((string) ($problem['initial_consultation_reason'] ?? ''));
        return [
            'enabled' => true,
            'status' => $consultation_reason !== '' ? 'consultation_reason' : 'pending',
            'sector_key' => current_knowledge_sector_key($mysqli),
            'id' => 0,
            'name' => '',
            'short_name' => '',
            'consultation_reason' => $consultation_reason,
            'area' => '',
            'category' => '',
            'risk_level' => '',
            'target_population' => ''
        ];
    }

    return [
        'enabled' => true,
        'status' => 'assigned',
        'sector_key' => $problem['sector_key'] ?? current_knowledge_sector_key($mysqli),
        'id' => (int) ($problem['id'] ?? 0),
        'diagnosis_id' => (int) ($problem['diagnosis_id'] ?? 0),
        'source_type' => $problem['source_type'] ?? (!empty($problem['id']) ? 'knowledge' : 'manual'),
        'name' => $diagnosis_name,
        'short_name' => $problem['short_name'] ?: $diagnosis_name,
        'selected_objective' => trim((string) ($problem['selected_objective'] ?? '')),
        'consultation_reason' => trim((string) ($problem['initial_consultation_reason'] ?? '')),
        'area' => $problem['area'] ?? '',
        'category' => $problem['category'] ?? '',
        'risk_level' => $problem['risk_level'] ?? '',
        'target_population' => $problem['target_population'] ?? ''
    ];
}

function admin_can_access_patient($mysqli, $patient_id)
{
    global $is_superadmin, $is_patient_delivery_request;
    $tenant_id = current_tenant_id();
    $patient_id = (int) $patient_id;
    if ($patient_id <= 0) {
        return false;
    }
    if ($is_patient_delivery_request) {
        return $patient_id === (int) ($_SESSION['user_id'] ?? 0);
    }
    $professional_id = current_professional_id_for_user($mysqli, (int) ($_SESSION['user_id'] ?? 0));
    if ($is_superadmin) {
        $stmt = $mysqli->prepare("SELECT id FROM users WHERE tenant_id = ? AND id = ? AND role = 'patient' LIMIT 1");
        $stmt->bind_param("ii", $tenant_id, $patient_id);
        $stmt->execute();
        return (bool) $stmt->get_result()->fetch_assoc();
    }

    if ($professional_id <= 0) {
        return false;
    }

    $stmt = $mysqli->prepare("
        SELECT u.id
        FROM users u
        LEFT JOIN patient_professionals ppf ON ppf.patient_id = u.id AND ppf.tenant_id = u.tenant_id AND ppf.is_primary = 1
        LEFT JOIN patient_profiles pp ON pp.user_id = u.id AND pp.tenant_id = u.tenant_id
        WHERE u.tenant_id = ?
          AND u.id = ?
          AND u.role = 'patient'
          AND COALESCE(ppf.professional_id, pp.professional_id) = ?
        LIMIT 1
    ");
    $stmt->bind_param("iii", $tenant_id, $patient_id, $professional_id);
    $stmt->execute();
    return (bool) $stmt->get_result()->fetch_assoc();
}

$patient_delivery_context = null;
$patient_delivery_type = '';
if ($is_patient_delivery_request || $has_delivery_context) {
    $patient_delivery_type = str_contains($action, 'docx') ? 'document' : 'drawing';
    $delivery_patient_id = $is_patient_delivery_request ? (int)$_SESSION['user_id'] : (int)($_GET['patient_id']??0);
    $patient_delivery_context = patient_delivery_request_context($mysqli, $tenant_id, $delivery_patient_id, $patient_delivery_type, $is_patient_delivery_request);
    if (!$patient_delivery_context) {
        echo json_encode(['success' => false, 'error' => 'Esta entrega no está disponible.']);
        exit;
    }
    $requested_document_id = (int) ($_GET['document_id'] ?? 0);
    $allowed_document_id = (int) ($patient_delivery_context['document_id'] ?? 0);
    if ($requested_document_id > 0 && $requested_document_id !== $allowed_document_id) {
        echo json_encode(['success' => false, 'error' => 'No autorizado para acceder a este documento.']);
        exit;
    }
    $_GET['patient_id'] = (int) $patient_delivery_context['patient_id'];
    $_GET['appointment_id'] = (int) ($patient_delivery_context['appointment_id'] ?? 0);
    $_GET['document_id'] = $allowed_document_id;
    $_GET['visible_to_patient'] = 1;
    if (trim((string) ($_GET['title'] ?? '')) === '') $_GET['title'] = (string) ($patient_delivery_context['title'] ?? 'Entrega');
}

function knowledge_priority_to_work_plan($priority)
{
    $priority = strtolower(trim((string) $priority));
    if ($priority === 'alta') {
        return 1;
    }
    if ($priority === 'baja') {
        return 3;
    }
    return 2;
}

function import_knowledge_recommendation_task($mysqli, $patient_id, $recommendation_id, $appointment_id = 0, $patient_diagnosis_id = 0)
{
    $tenant_id = current_tenant_id();
    $sector_sql = knowledge_sector_in_sql($mysqli, allowed_knowledge_sector_keys($mysqli));
    $stmt = $mysqli->prepare("
        SELECT r.id, r.problem_id, r.priority, r.clinical_note,
               t.title, t.description, t.objective, t.estimated_duration,
               te.name AS technique_name
        FROM knowledge_recommendations r
        INNER JOIN knowledge_tasks t ON t.id = r.task_id
        INNER JOIN knowledge_techniques te ON te.id = r.technique_id
        WHERE r.id = ? AND r.sector_key IN ($sector_sql)
        LIMIT 1
    ");
    $stmt->bind_param("i", $recommendation_id);
    $stmt->execute();
    $rec = $stmt->get_result()->fetch_assoc();
    if (!$rec) {
        return 0;
    }
    if ($patient_diagnosis_id <= 0 && !empty($rec['problem_id']) && table_exists($mysqli, 'patient_diagnoses')) {
        $stmt = $mysqli->prepare("
            SELECT id
            FROM patient_diagnoses
            WHERE tenant_id = ? AND patient_id = ? AND knowledge_problem_id = ? AND status = 'active'
            ORDER BY is_primary DESC, id ASC
            LIMIT 1
        ");
        $problem_id = (int) $rec['problem_id'];
        $stmt->bind_param('iii', $tenant_id, $patient_id, $problem_id);
        $stmt->execute();
        $patient_diagnosis_id = (int) ($stmt->get_result()->fetch_assoc()['id'] ?? 0);
    }

    $description_parts = [];
    if (!empty($rec['description'])) {
        $description_parts[] = $rec['description'];
    }
    if (!empty($rec['objective'])) {
        $description_parts[] = 'Objetivo: ' . $rec['objective'];
    }
    if (!empty($rec['technique_name'])) {
        $description_parts[] = 'Tecnica: ' . $rec['technique_name'];
    }
    if (!empty($rec['estimated_duration'])) {
        $description_parts[] = 'Duracion estimada: ' . $rec['estimated_duration'];
    }
    if (!empty($rec['clinical_note'])) {
        $description_parts[] = 'Nota clinica: ' . $rec['clinical_note'];
    }

    $title = $rec['title'];
    $description = implode("\n\n", $description_parts);
    $priority = knowledge_priority_to_work_plan($rec['priority'] ?? '');
    $status = 'pending';
    $visible_to_patient = 0;
    $session_user_id = (int) ($_SESSION['user_id'] ?? 0);
    $professional_id = current_professional_id_for_user($mysqli, $session_user_id);
    if ($professional_id <= 0) {
        $professional_id = null;
    }
    $settings_res = $mysqli->query("SELECT patient_tasks_visible_default FROM payment_settings WHERE tenant_id = $tenant_id");
    if ($settings_res && ($settings_row = $settings_res->fetch_assoc())) {
        $visible_to_patient = (int) ($settings_row['patient_tasks_visible_default'] ?? 0) === 1 ? 1 : 0;
    }
    $appointment_id_db = null;
    if ((int) $appointment_id > 0) {
        $appointment_manage_result = admin_can_manage_appointment_payment($mysqli, (int) $appointment_id);
        if (!$appointment_manage_result[0] || (int) ($appointment_manage_result[1]['user_id'] ?? 0) !== (int) $patient_id) {
            return -1;
        }
        $appointment_id_db = (int) $appointment_id;
        if (!empty($appointment_manage_result[1]['professional_id'])) {
            $professional_id = (int) $appointment_manage_result[1]['professional_id'];
        }
    }
    $completed_at = null;
    $completed_by = null;

    $stmt = $mysqli->prepare("
        INSERT INTO patient_work_plan_tasks (tenant_id, patient_id, patient_diagnosis_id, appointment_id, professional_id, title, description, status, priority, visible_to_patient, created_by, completed_at, completed_by)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    ");
    $patient_diagnosis_id_db = $patient_diagnosis_id > 0 ? $patient_diagnosis_id : null;
    $stmt->bind_param("iiiiisssiiisi", $tenant_id, $patient_id, $patient_diagnosis_id_db, $appointment_id_db, $professional_id, $title, $description, $status, $priority, $visible_to_patient, $session_user_id, $completed_at, $completed_by);
    $stmt->execute();
    return (int) $mysqli->insert_id;
}

function global_search_like_term($term)
{
    return '%' . str_replace(['\\', '%', '_'], ['\\\\', '\\%', '\\_'], $term) . '%';
}

function global_search_push(&$results, $type, $title, $subtitle = '', $meta = '', $icon = 'bi-search', $action = null)
{
    $results[] = [
        'type' => $type,
        'title' => $title,
        'subtitle' => $subtitle,
        'meta' => $meta,
        'icon' => $icon,
        'action' => $action
    ];
}

function professional_photo_with_dashboard_fallback($row, $dashboard_photo)
{
    $photo = $row['public_photo_path'] ?? ($row['professional_photo_path'] ?? '');
    return $photo ?: '';
}

function sync_patient_legacy_contact($mysqli, $tenant_id, $patient_id)
{
    $stmt = $mysqli->prepare("
        SELECT name, nif, phone, relationship
        FROM patient_contacts
        WHERE tenant_id = ? AND patient_id = ? AND is_active = 1
          AND (is_legal_guardian = 1 OR is_emergency_contact = 1)
        ORDER BY is_legal_guardian DESC, is_emergency_contact DESC, id ASC
        LIMIT 1
    ");
    $stmt->bind_param('ii', $tenant_id, $patient_id);
    $stmt->execute();
    $contact = $stmt->get_result()->fetch_assoc();
    $stmt->close();

    $name = $contact['name'] ?? null;
    $nif = $contact['nif'] ?? null;
    $phone = $contact['phone'] ?? null;
    $relationship = $contact['relationship'] ?? null;
    $stmt = $mysqli->prepare("
        UPDATE patient_profiles
        SET emergency_contact_name = ?, emergency_contact_nif = ?,
            emergency_contact_phone = ?, emergency_contact_relation = ?
        WHERE tenant_id = ? AND user_id = ?
    ");
    $stmt->bind_param('ssssii', $name, $nif, $phone, $relationship, $tenant_id, $patient_id);
    $stmt->execute();
    $stmt->close();
}

function admin_ensure_password_reset_table($mysqli)
{
    if (function_exists('app_auto_schema_migrations_enabled') && !app_auto_schema_migrations_enabled()) {
        return;
    }

    $tenant_id = current_tenant_id();
    $mysqli->query("
        CREATE TABLE IF NOT EXISTS password_resets (
            id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
            tenant_id INT UNSIGNED NOT NULL DEFAULT 1,
            user_id INT UNSIGNED NOT NULL,
            token_hash CHAR(64) NOT NULL UNIQUE,
            expires_at DATETIME NOT NULL,
            used_at DATETIME DEFAULT NULL,
            created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
            INDEX idx_password_resets_user (user_id),
            INDEX idx_password_resets_expires (expires_at)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
    ");
    if (!column_exists($mysqli, 'password_resets', 'tenant_id')) {
        $mysqli->query("ALTER TABLE password_resets ADD tenant_id INT UNSIGNED NOT NULL DEFAULT $tenant_id AFTER id");
    }
}

function send_professional_password_setup_email($mysqli, $user_id, $name, $email)
{
    $token = bin2hex(random_bytes(32));
    $token_hash = hash('sha256', $token);
    $tenant_id = current_tenant_id();

    $stmt = $mysqli->prepare("UPDATE password_resets SET used_at = NOW() WHERE tenant_id = ? AND user_id = ? AND used_at IS NULL");
    $stmt->bind_param("ii", $tenant_id, $user_id);
    $stmt->execute();

    $stmt = $mysqli->prepare("INSERT INTO password_resets (tenant_id, user_id, token_hash, expires_at) VALUES (?, ?, ?, DATE_ADD(NOW(), INTERVAL 24 HOUR))");
    $stmt->bind_param("iis", $tenant_id, $user_id, $token_hash);
    $stmt->execute();

    $password_link = app_public_base_url() . 'reset_password.php?t=' . urlencode($token);
    $reset_link = urlme_shorten_url(
        $password_link,
        'Crear contraseña acceso SimplyGest Praxis',
        date('Y-m-d H:i:s', strtotime('+24 hours'))
    ) ?: $password_link;

    return send_app_email(
        $email,
        'Crea tu contraseña de acceso',
        '<p>Hola ' . htmlspecialchars($name) . ',</p>' .
        '<p>Se ha creado tu acceso como miembro del equipo en ' . htmlspecialchars(get_app_name($mysqli)) . '.</p>' .
        '<p>Para entrar en la web, crea tu contraseña desde este enlace:</p>' .
        '<p><a href="' . htmlspecialchars($reset_link) . '">Crear contraseña de acceso</a></p>' .
        '<p>Este enlace caduca en 24 horas.</p>',
        null,
        $mysqli
    );
}

