        throw new \Exception('Formato de imagen no válido. Usa JPG, PNG, WEBP o GIF.');
    }

    $extensions = [
        'image/jpeg' => 'jpg',
        'image/png' => 'png',
        'image/webp' => 'webp',
        'image/gif' => 'gif'
    ];
    $upload_dir = app_tenant_public_upload_dir('settings');
    if (!app_ensure_dir($upload_dir)) {
