            'skinfold_thigh_mm' => $row['skinfold_thigh_mm'] ?? '',
            'photo_path' => $row['photo_path'] ?? '',
            'document_path' => $row['document_path'] ?? '',
            'document_name' => $row['document_name'] ?? '',
            'professional_id' => (int) ($row['professional_id'] ?? 0),
            'professional_name' => $row['professional_name'] ?? '',
            'professional_photo_path' => $professional_photo_path,
            'created_by_admin' => (int) ($row['created_by_admin'] ?? 0),
            'has_portal_access' => patient_has_portal_access($row) ? 1 : 0,
            'pending_required_legal_documents' => (int) ($row['pending_required_legal_documents'] ?? 0)
        ];
    }
    echo json_encode([
        'success' => true,
        'patients' => $patients,
        'professionals' => $is_superadmin ? active_professionals_payload($mysqli) : [],
        'current_professional_id' => current_professional_id_for_user($mysqli, (int) ($_SESSION['user_id'] ?? 0))
    ]);
} elseif ($action === 'waiting_list_patients') {
    ensure_patient_management_tables($mysqli);
    $professional_id = $is_superadmin ? 0 : admin_requested_professional_filter($mysqli);
    $professional_where = $professional_id > 0
        ? " AND COALESCE(ppf.professional_id, pp.professional_id) = " . (int) $professional_id
        : ($professional_id < 0 ? " AND 1 = 0" : "");
    $res = $mysqli->query("
        SELECT u.id, u.name
        FROM users u
        LEFT JOIN patient_profiles pp ON pp.user_id = u.id AND pp.tenant_id = u.tenant_id
        LEFT JOIN patient_professionals ppf ON ppf.patient_id = u.id AND ppf.tenant_id = u.tenant_id AND ppf.is_primary = 1
        WHERE u.tenant_id = $tenant_id
          AND u.role = 'patient'
          AND COALESCE(pp.waiting_list, 0) = 1
          AND COALESCE(pp.patient_status, 'active') <> 'retention_blocked'
          $professional_where
        ORDER BY u.name ASC
    ");
    $patients = [];
    while ($row = $res->fetch_assoc()) {
        $patients[] = [
            'id' => (int) $row['id'],
            'name' => $row['name'] ?? ''
        ];
    }
    echo json_encode([
        'success' => true,
        'count' => count($patients),
        'patients' => $patients
    ]);
} elseif ($action === 'global_search') {
    ensure_patient_management_tables($mysqli);
    ensure_patient_evolution_tables($mysqli);
    ensure_patient_work_plan_tables($mysqli);
    ensure_cabinet_schema($mysqli);
    $query = trim((string) ($_GET['q'] ?? ''));
    if (strlen($query) < 2) {
        echo json_encode(['success' => true, 'query' => $query, 'results' => []]);
        exit;
    }
    $like = global_search_like_term($query);
    $phone_search_enabled = ($is_superadmin || !empty($member_permissions['view_patient_phone'])) ? 1 : 0;
    $professional_id = $is_superadmin ? 0 : current_professional_id_for_user($mysqli, (int) ($_SESSION['user_id'] ?? 0));
    $professional_join = "
        LEFT JOIN patient_profiles pp ON pp.user_id = u.id AND pp.tenant_id = u.tenant_id
        LEFT JOIN patient_professionals ppf ON ppf.patient_id = u.id AND ppf.tenant_id = u.tenant_id AND ppf.is_primary = 1
        LEFT JOIN professionals p ON p.id = COALESCE(ppf.professional_id, pp.professional_id) AND p.tenant_id = u.tenant_id
    ";
    $professional_where = !$is_superadmin ? " AND COALESCE(ppf.professional_id, pp.professional_id) = ?" : "";
    $results = [
        'patients' => [],
        'professionals' => [],
        'appointments' => [],
        'files' => [],
        'tasks' => []
    ];

    if (!$is_superadmin && $professional_id <= 0) {
        echo json_encode(['success' => true, 'query' => $query, 'results' => $results]);
        exit;
    }

    $sql = "
        SELECT u.id, u.name, u.email, u.phone, pp.patient_type, p.display_name AS professional_name
        FROM users u
        $professional_join
        WHERE u.tenant_id = ?
          AND u.role = 'patient'
          AND COALESCE(pp.patient_status, 'active') <> 'retention_blocked'
          AND (u.name LIKE ? ESCAPE '\\\\' OR u.email LIKE ? ESCAPE '\\\\'
               OR ($phone_search_enabled = 1 AND u.phone LIKE ? ESCAPE '\\\\')
               OR pp.patient_type LIKE ? ESCAPE '\\\\')
          $professional_where
        ORDER BY u.name ASC
        LIMIT 12
    ";
    $stmt = $mysqli->prepare($sql);
    if ($is_superadmin) {
        $stmt->bind_param("issss", $tenant_id, $like, $like, $like, $like);
    } else {
        $stmt->bind_param("issssi", $tenant_id, $like, $like, $like, $like, $professional_id);
    }
    $stmt->execute();
    $res = $stmt->get_result();
    while ($row = $res->fetch_assoc()) {
        $row['phone'] = member_patient_phone($row['phone'] ?? '');
        global_search_push(
            $results['patients'],
            'patients',
            $row['name'] ?? 'Paciente',
            trim(($row['email'] ?? '') . (($row['email'] ?? '') && ($row['phone'] ?? '') ? ' · ' : '') . ($row['phone'] ?? '')),
            trim(($row['patient_type'] ?? '') . (($row['patient_type'] ?? '') && ($row['professional_name'] ?? '') ? ' · ' : '') . ($row['professional_name'] ?? '')),
            'bi-person',
            ['kind' => 'patient', 'id' => (int) $row['id']]
        );
    }

    if ($is_superadmin) {
        $stmt = $mysqli->prepare("
            SELECT p.id, p.display_name, p.public_email, p.public_phone, u.email AS login_email
            FROM professionals p
            LEFT JOIN users u ON u.id = p.user_id AND u.tenant_id = p.tenant_id
            WHERE p.tenant_id = ?
              AND (p.display_name LIKE ? ESCAPE '\\\\'
               OR p.public_email LIKE ? ESCAPE '\\\\'
               OR p.public_phone LIKE ? ESCAPE '\\\\'
               OR u.email LIKE ? ESCAPE '\\\\')
            ORDER BY p.display_name ASC
            LIMIT 8
        ");
        $stmt->bind_param("issss", $tenant_id, $like, $like, $like, $like);
        $stmt->execute();
        $res = $stmt->get_result();
        while ($row = $res->fetch_assoc()) {
            global_search_push(
                $results['professionals'],
                'professionals',
                $row['display_name'] ?? 'Profesional',
                trim(($row['public_email'] ?: $row['login_email'] ?: '') . (($row['public_phone'] ?? '') ? ' · ' . $row['public_phone'] : '')),
                '',
                'bi-person-badge',
                ['kind' => 'professional', 'id' => (int) $row['id']]
            );
        }
    }

    $appointment_professional_where = !$is_superadmin ? " AND a.professional_id = ?" : "";
    $sql = "
        SELECT a.id, a.appointment_date, a.appointment_time, a.status, a.consultation_type,
               COALESCE(a.duration_minutes, so.duration_minutes, 60) AS duration_minutes,
               s.name AS service_name,
               u.id AS patient_id, u.name AS patient_name, u.email AS patient_email, u.phone AS patient_phone,
               p.display_name AS professional_name
        FROM appointments a
        JOIN users u ON u.id = a.user_id AND u.tenant_id = a.tenant_id
        LEFT JOIN appointment_service_options so ON so.id = a.service_option_id AND so.tenant_id = a.tenant_id
        LEFT JOIN appointment_services s ON s.id = so.service_id AND s.tenant_id = a.tenant_id
        LEFT JOIN professionals p ON p.id = a.professional_id AND p.tenant_id = a.tenant_id
        WHERE a.tenant_id = ?
          AND (u.name LIKE ? ESCAPE '\\\\' OR u.email LIKE ? ESCAPE '\\\\'
               OR ($phone_search_enabled = 1 AND u.phone LIKE ? ESCAPE '\\\\')
               OR p.display_name LIKE ? ESCAPE '\\\\' OR s.name LIKE ? ESCAPE '\\\\'
               OR a.appointment_date LIKE ? ESCAPE '\\\\')
          $appointment_professional_where
        ORDER BY a.appointment_date DESC, a.appointment_time DESC
        LIMIT 12
    ";
    $stmt = $mysqli->prepare($sql);
    if ($is_superadmin) {
        $stmt->bind_param("issssss", $tenant_id, $like, $like, $like, $like, $like, $like);
    } else {
        $stmt->bind_param("issssssi", $tenant_id, $like, $like, $like, $like, $like, $like, $professional_id);
    }
    $stmt->execute();
    $res = $stmt->get_result();
    while ($row = $res->fetch_assoc()) {
        $date_label = trim(report_datetime(trim(($row['appointment_date'] ?? '') . ' ' . ($row['appointment_time'] ?? ''))));
        global_search_push(
            $results['appointments'],
            'appointments',
            ($row['patient_name'] ?? 'Cita') . ' · ' . $date_label,
            appointment_service_option_label($row) . ' · ' . (($row['consultation_type'] ?? 'presencial') === 'online' ? 'Online' : 'Presencial'),
            trim(($row['professional_name'] ?? '') . (($row['status'] ?? '') ? ' · ' . ($row['status'] ?? '') : '')),
            'bi-calendar-check',
            ['kind' => 'appointment', 'id' => (int) $row['id'], 'patient_id' => (int) $row['patient_id']]
        );
    }

    $file_professional_where = !$is_superadmin ? " AND COALESCE(ppf.professional_id, pp.professional_id) = ?" : "";
    $sql = "
        SELECT f.id, f.original_name, f.uploaded_at, n.title AS note_title, u.id AS patient_id, u.name AS patient_name
        FROM patient_evolution_files f
        JOIN patient_evolution_notes n ON n.id = f.evolution_note_id AND n.tenant_id = f.tenant_id
        JOIN users u ON u.id = f.patient_id AND u.tenant_id = f.tenant_id
        LEFT JOIN patient_profiles pp ON pp.user_id = u.id AND pp.tenant_id = u.tenant_id
        LEFT JOIN patient_professionals ppf ON ppf.patient_id = u.id AND ppf.tenant_id = u.tenant_id AND ppf.is_primary = 1
        WHERE (f.original_name LIKE ? ESCAPE '\\\\' OR n.title LIKE ? ESCAPE '\\\\' OR u.name LIKE ? ESCAPE '\\\\')
          AND f.tenant_id = ?
          $file_professional_where
        ORDER BY f.uploaded_at DESC, f.id DESC
        LIMIT 12
    ";
    $stmt = $mysqli->prepare($sql);
    if ($is_superadmin) {
        $stmt->bind_param("sssi", $like, $like, $like, $tenant_id);
    } else {
        $stmt->bind_param("sssii", $like, $like, $like, $tenant_id, $professional_id);
    }
    $stmt->execute();
    $res = $stmt->get_result();
    while ($row = $res->fetch_assoc()) {
        global_search_push(
            $results['files'],
            'files',
            $row['original_name'] ?? 'Archivo',
            ($row['patient_name'] ?? '') . (($row['note_title'] ?? '') ? ' · ' . $row['note_title'] : ''),
            report_datetime($row['uploaded_at'] ?? ''),
            'bi-paperclip',
            ['kind' => 'file', 'id' => (int) $row['id'], 'patient_id' => (int) $row['patient_id']]
        );
    }

    $task_professional_where = !$is_superadmin ? " AND COALESCE(ppf.professional_id, pp.professional_id) = ?" : "";
    $sql = "
        SELECT t.id, t.title, t.description, t.status, t.completed_at, u.id AS patient_id, u.name AS patient_name
        FROM patient_work_plan_tasks t
        JOIN users u ON u.id = t.patient_id AND u.tenant_id = t.tenant_id
        LEFT JOIN patient_profiles pp ON pp.user_id = u.id AND pp.tenant_id = u.tenant_id
        LEFT JOIN patient_professionals ppf ON ppf.patient_id = u.id AND ppf.tenant_id = u.tenant_id AND ppf.is_primary = 1
        WHERE (t.title LIKE ? ESCAPE '\\\\' OR t.description LIKE ? ESCAPE '\\\\' OR u.name LIKE ? ESCAPE '\\\\')
          AND t.tenant_id = ?
          $task_professional_where
        ORDER BY t.updated_at DESC, t.id DESC
        LIMIT 12
    ";
    $stmt = $mysqli->prepare($sql);
    if ($is_superadmin) {
        $stmt->bind_param("sssi", $like, $like, $like, $tenant_id);
    } else {
        $stmt->bind_param("sssii", $like, $like, $like, $tenant_id, $professional_id);
    }
    $stmt->execute();
    $res = $stmt->get_result();
    while ($row = $res->fetch_assoc()) {
        global_search_push(
            $results['tasks'],
            'tasks',
            $row['title'] ?? 'Tarea',
            $row['patient_name'] ?? '',
            ($row['status'] ?? '') === 'completed' ? 'Completada' : 'Pendiente',
            'bi-list-check',
            ['kind' => 'patient', 'id' => (int) $row['patient_id']]
        );
    }

    echo json_encode(['success' => true, 'query' => $query, 'results' => $results]);
} elseif ($action === 'time_tracking_status') {
    $tracking_settings = time_tracking_settings_values($mysqli);
    if (empty($tracking_settings['enabled'])) {
        echo json_encode(['success' => true, 'enabled' => false, 'settings' => $tracking_settings]);
        exit;
    }
    $status = time_tracking_current_status($mysqli, $tenant_id, (int) $_SESSION['user_id']);
    echo json_encode(['success' => true, 'enabled' => true, 'status' => $status, 'settings' => $tracking_settings]);
} elseif ($action === 'time_tracking_register') {
    if (!time_tracking_enabled($mysqli)) {
        echo json_encode(['success' => false, 'error' => 'El control horario no está habilitado.']);
        exit;
    }
    $event_type = trim((string) ($_POST['event_type'] ?? ''));
    try {
        $mysqli->begin_transaction();
        $entry = time_tracking_register_event($mysqli, $tenant_id, (int) $_SESSION['user_id'], $event_type);
        app_log($mysqli, [
            'action' => 'time_tracking_' . $event_type,
            'status' => 'ok',
            'target_type' => 'user',
            'target_id' => (int) $_SESSION['user_id'],
            'title' => time_tracking_event_label($event_type),
            'message' => 'Registro de control horario realizado.',
            'metadata' => ['entry_id' => $entry['id'], 'local_datetime' => $entry['local_datetime']]
        ]);
        $mysqli->commit();
        echo json_encode([
            'success' => true,
            'message' => time_tracking_event_label($event_type) . ' registrada correctamente.',
            'entry' => $entry,
            'status' => time_tracking_current_status($mysqli, $tenant_id, (int) $_SESSION['user_id']),
            'logout' => $event_type === 'clock_out' && !empty(time_tracking_settings_values($mysqli)['logout_on_clock_out'])
        ]);
    } catch (Throwable $e) {
        $mysqli->rollback();
        echo json_encode(['success' => false, 'error' => $e->getMessage()]);
    }
} elseif ($action === 'time_tracking_settings') {
    $tracking_settings = time_tracking_settings_values($mysqli);
    echo json_encode([
        'success' => true,
        'plan_enabled' => true,
        'settings' => $tracking_settings
    ]);
} elseif ($action === 'save_time_tracking_settings') {
    $enabled = !empty($_POST['enabled']) ? 1 : 0;
    $notify_missing_clock_in = !empty($_POST['notify_missing_clock_in']) ? 1 : 0;
    $require_clock_in = !empty($_POST['require_clock_in']) ? 1 : 0;
    $logout_on_clock_out = !empty($_POST['logout_on_clock_out']) ? 1 : 0;
    $stmt = $mysqli->prepare("
        UPDATE payment_settings
        SET time_tracking_enabled = ?,
            time_tracking_notify_missing_clock_in = ?,
            time_tracking_require_clock_in = ?,
            time_tracking_logout_on_clock_out = ?
        WHERE tenant_id = ?
    ");
    $stmt->bind_param('iiiii', $enabled, $notify_missing_clock_in, $require_clock_in, $logout_on_clock_out, $tenant_id);
    $stmt->execute();
    app_log($mysqli, [
        'action' => 'time_tracking_settings_updated',
        'status' => 'ok',
        'target_type' => 'tenant',
        'target_id' => $tenant_id,
        'title' => 'Configuración de control horario',
        'message' => $enabled ? 'Control horario activado.' : 'Control horario desactivado.'
    ]);
    echo json_encode([
        'success' => true,
        'settings' => [
            'enabled' => $enabled,
            'notify_missing_clock_in' => $notify_missing_clock_in,
            'require_clock_in' => $require_clock_in,
            'logout_on_clock_out' => $logout_on_clock_out
        ],
        'message' => 'Configuración guardada.'
    ]);
} elseif ($action === 'time_tracking_entries') {
    $date_to = trim((string) ($_GET['date_to'] ?? ''));
    $date_from = trim((string) ($_GET['date_from'] ?? ''));
    if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date_to)) $date_to = date('Y-m-d');
    if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date_from)) $date_from = date('Y-m-d', strtotime('-30 days'));
    if ($date_from > $date_to) [$date_from, $date_to] = [$date_to, $date_from];
    $stmt = $mysqli->prepare("
        SELECT e.id, e.user_id, u.name AS user_name, e.event_type, e.local_datetime,
               e.timezone_name, e.source, e.created_at
        FROM time_tracking_entries e
        JOIN users u ON u.id = e.user_id AND u.tenant_id = e.tenant_id
        WHERE e.tenant_id = ? AND e.voided_at IS NULL
          AND e.local_datetime BETWEEN ? AND ?
        ORDER BY e.local_datetime DESC, e.id DESC
        LIMIT 1000
    ");
    $from_time = $date_from . ' 00:00:00';
    $to_time = $date_to . ' 23:59:59';
    $stmt->bind_param('iss', $tenant_id, $from_time, $to_time);
    $stmt->execute();
    $entries = $stmt->get_result()->fetch_all(MYSQLI_ASSOC);
    echo json_encode(['success' => true, 'entries' => $entries, 'date_from' => $date_from, 'date_to' => $date_to]);
} elseif ($action === 'time_tracking_report' || $action === 'time_tracking_export') {
    $date_to = trim((string) ($_GET['date_to'] ?? ''));
    $date_from = trim((string) ($_GET['date_from'] ?? ''));
    if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date_to)) $date_to = date('Y-m-d');
    if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date_from)) $date_from = date('Y-m-d', strtotime('-30 days'));
    if ($date_from > $date_to) [$date_from, $date_to] = [$date_to, $date_from];
    $requested_user_id = max(0, (int) ($_GET['user_id'] ?? 0));
    if (!$is_superadmin) {
        $requested_user_id = (int) $_SESSION['user_id'];
    }
    $report_type = trim((string) ($_GET['report_type'] ?? 'entries'));
    $report_data = time_tracking_report_data($mysqli, $tenant_id, $requested_user_id, $date_from, $date_to);
    $report = time_tracking_build_report($report_data, $report_type);

    if ($action === 'time_tracking_report') {
        echo json_encode([
            'success' => true,
            'report' => $report,
            'members' => $is_superadmin ? $report_data['members'] : [],
            'selected_user_id' => $requested_user_id,
            'date_from' => $date_from,
            'date_to' => $date_to
        ]);
        exit;
    }

    $format = strtolower(trim((string) ($_GET['format'] ?? 'xlsx')));
    $base_filename = 'control-horario-' . $report['type'] . '-' . $date_from . '-' . $date_to;
    if ($format === 'json') {
        $export_rows = [];
        foreach ($report['rows'] as $row) {
            $export_rows[] = array_combine($report['headers'], $row);
        }
        export_output_json($base_filename, [
            'report' => $report['title'],
            'date_from' => $date_from,
            'date_to' => $date_to,
            'rows' => $export_rows
        ]);
    }
    if ($format === 'pdf') {
        $branding = function_exists('get_public_branding_settings') ? get_public_branding_settings($mysqli) : [];
        $app_name = trim((string) ($branding['app_name'] ?? 'SimplyGest Praxis'));
        $primary_color = trim((string) ($branding['primary_color'] ?? '#6f5aa8'));
        if (!preg_match('/^#[0-9a-fA-F]{6}$/', $primary_color)) $primary_color = '#6f5aa8';
        $html = '<!doctype html><html lang="es"><head><meta charset="utf-8"><style>'
            . 'body{font-family:Arial,sans-serif;color:#263238;font-size:10pt}'
            . 'h1{font-size:18pt;margin:0 0 4px;color:' . htmlspecialchars($primary_color, ENT_QUOTES, 'UTF-8') . '}'
            . '.meta{color:#66737d;margin-bottom:18px}.line{height:3px;background:' . htmlspecialchars($primary_color, ENT_QUOTES, 'UTF-8') . ';margin:8px 0 18px}'
            . 'table{width:100%;border-collapse:collapse}th{background:#f1f3f7;text-align:left;color:#4f5965}'
            . 'th,td{padding:8px;border-bottom:1px solid #dfe4ea;vertical-align:top}'
            . '</style></head><body><div><strong>' . htmlspecialchars($app_name, ENT_QUOTES, 'UTF-8') . '</strong></div>'
            . '<div class="line"></div><h1>' . htmlspecialchars($report['title'], ENT_QUOTES, 'UTF-8') . '</h1>'
            . '<div class="meta">Periodo: ' . htmlspecialchars($date_from, ENT_QUOTES, 'UTF-8') . ' - ' . htmlspecialchars($date_to, ENT_QUOTES, 'UTF-8') . '</div>'
            . '<table><thead><tr>';
        foreach ($report['headers'] as $header) {
            $html .= '<th>' . htmlspecialchars((string) $header, ENT_QUOTES, 'UTF-8') . '</th>';
        }
        $html .= '</tr></thead><tbody>';
        foreach ($report['rows'] as $row) {
            $html .= '<tr>';
            foreach ($row as $value) {
                $html .= '<td>' . htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8') . '</td>';
            }
            $html .= '</tr>';
        }
        $html .= '</tbody></table></body></html>';
        pdf_output_html($html, $base_filename . '.pdf', ['title' => $report['title'], 'author' => $app_name]);
    }
    export_output_xlsx($base_filename, $report['headers'], $report['rows'], 'Control horario');
} elseif ($action === 'export_app_logs') {
    $format = strtolower((string) ($_GET['format'] ?? 'xlsx'));
    $date_to = trim((string) ($_GET['date_to'] ?? ''));
    $date_from = trim((string) ($_GET['date_from'] ?? ''));
    if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date_to)) $date_to = date('Y-m-d');
    if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date_from)) $date_from = date('Y-m-d', strtotime('-30 days'));
    if ($date_from > $date_to) [$date_from, $date_to] = [$date_to, $date_from];
    $stmt = $mysqli->prepare("
        SELECT l.id, l.created_at, u.name AS user_name, l.action, l.channel, l.status,
               l.target_type, l.target_id, l.title, l.message
        FROM app_logs l
        LEFT JOIN users u ON u.id = l.user_id AND u.tenant_id = l.tenant_id
        WHERE l.tenant_id = ? AND l.created_at BETWEEN ? AND ?
        ORDER BY l.created_at DESC, l.id DESC
    ");
    $from_time = $date_from . ' 00:00:00';
    $to_time = $date_to . ' 23:59:59';
    $stmt->bind_param("iss", $tenant_id, $from_time, $to_time);
    $stmt->execute();
    $records = $stmt->get_result()->fetch_all(MYSQLI_ASSOC);
    if ($format === 'json') {
        export_output_json('log-' . $date_from . '-' . $date_to, ['exported_at' => date(DATE_ATOM), 'logs' => $records]);
    }
    $headers = $records ? array_keys($records[0]) : ['id', 'created_at', 'action'];
    $rows = array_map(function ($row) use ($headers) {
        return array_map(function ($key) use ($row) { return $row[$key] ?? ''; }, $headers);
    }, $records);
    export_output_xlsx('log-' . $date_from . '-' . $date_to, $headers, $rows, 'Log');
} elseif ($action === 'list_incidents') {
    ensure_invoice_schema($mysqli);
    ensure_appointment_payment_columns($mysqli);
    ensure_app_logs_table($mysqli);
    $incidents = [];
    $add_incident = static function (string $type, string $level, string $title, string $description, string $advice, int $count = 1, string $action = '') use (&$incidents): void {
        $incidents[] = compact('type', 'level', 'title', 'description', 'advice', 'count', 'action');
    };

    if (!app_email_is_configured($mysqli)) {
        $add_incident('email_not_configured', 'danger', "Correo electr\u{00F3}nico no configurado", 'Praxis no puede enviar recordatorios, invitaciones, facturas ni documentos por email.', "Configura un proveedor de correo en Configuraci\u{00F3}n > Comunicaciones y realiza un env\u{00ED}o de prueba.", 1, 'communication_settings');
    }

    $settings_res = $mysqli->query("SELECT online_payment_enabled, environment, billing_enabled, billing_provider, billing_country, billing_province, legal_owner_name, legal_nif, legal_address, legal_city, legal_postal_code, verifactu_enabled FROM payment_settings WHERE tenant_id = $tenant_id LIMIT 1");
    $settings = $settings_res ? ($settings_res->fetch_assoc() ?: []) : [];
    if ((int) ($settings['online_payment_enabled'] ?? 0) === 1 && (string) ($settings['environment'] ?? 'sandbox') === 'sandbox') {
        $add_incident('online_payments_sandbox', 'danger', 'Pagos online en modo de prueba', "Los cobros realizados por los clientes son simulaciones y no ingresar\u{00E1}n dinero.", "Cuando termines las pruebas, configura las credenciales de producci\u{00F3}n y cambia el entorno desde Configuraci\u{00F3}n > Pagos.", 1, 'payment_settings');
    }
    if ((int) ($settings['billing_enabled'] ?? 0) === 1) {
        $missing_fiscal = [];
        foreach (['legal_owner_name' => 'nombre fiscal', 'legal_nif' => 'NIF', 'legal_address' => 'domicilio', 'legal_city' => 'municipio', 'legal_postal_code' => "c\u{00F3}digo postal"] as $field => $label) {
            if (trim((string) ($settings[$field] ?? '')) === '') $missing_fiscal[] = $label;
        }
        if (strtoupper(trim((string) ($settings['billing_country'] ?? 'ES'))) === 'ES' && trim((string) ($settings['billing_province'] ?? '')) === '') $missing_fiscal[] = 'provincia';
        if ($missing_fiscal) $add_incident('billing_fiscal_data_incomplete', 'danger', "Informaci\u{00F3}n fiscal incompleta", 'Falta completar: ' . implode(', ', $missing_fiscal) . '.', 'Completa los datos legales y fiscales antes de emitir nuevas facturas para evitar rechazos o documentos incompletos.', count($missing_fiscal), 'billing_settings');
    }
    $provider = (string) ($settings['billing_provider'] ?? 'none');
    if ((int) ($settings['billing_enabled'] ?? 0) === 1 && $provider === 'praxis' && (int) ($settings['verifactu_enabled'] ?? 0) === 1) {
        $res = $mysqli->query("SELECT COUNT(*) total FROM verifactu_records WHERE tenant_id = $tenant_id AND status = 'error'");
        $count = (int) ($res ? ($res->fetch_assoc()['total'] ?? 0) : 0);
        if ($count > 0) $add_incident('verifactu_failed', 'danger', 'Registros VeriFactu fallidos', 'Hay facturas que AEAT no ha aceptado o que no se han podido enviar.', "Abre Facturaci\u{00F3}n, revisa el error de cada factura y corrige los datos fiscales o la configuraci\u{00F3}n antes de reintentarlo.", $count, 'billing_invoices');
    }
    if ((int) ($settings['billing_enabled'] ?? 0) === 1 && $provider === 'simplygest_cloud') {
        $res = $mysqli->query("SELECT COUNT(*) total FROM movim WHERE tenant_id = $tenant_id AND tipo_movim = 'factura' AND billing_provider = 'simplygest_cloud' AND (external_invoice_id IS NULL OR external_invoice_id = '')");
        $count = (int) ($res ? ($res->fetch_assoc()['total'] ?? 0) : 0);
        if ($count > 0) $add_incident('cloud_invoices_pending', 'danger', 'Facturas sin enviar a SimplyGest Cloud', "Estas facturas no tienen confirmaci\u{00F3}n ni identificador de Cloud.", "Comprueba la API Key y la conexi\u{00F3}n con la empresa correcta de Cloud antes de volver a enviarlas.", $count, 'billing_invoices');
    }

    $res = $mysqli->query("SELECT COUNT(*) total FROM appointments WHERE tenant_id = $tenant_id AND status <> 'cancelled' AND CONCAT(appointment_date, ' ', appointment_time) < NOW() AND COALESCE(payment_status, 'pending') <> 'paid'");
    $count = (int) ($res ? ($res->fetch_assoc()['total'] ?? 0) : 0);
    if ($count > 0) $add_incident('past_sessions_unpaid', 'warning', 'Sesiones anteriores pendientes de cobro', 'Hay citas ya realizadas cuyo pago no consta como completado.', 'Revisa las citas y confirma si deben cobrarse, marcarse como pagadas o corregirse porque no asistieron.', $count, 'billing_invoices');

    $res = $mysqli->query("SELECT COUNT(*) total FROM appointments WHERE tenant_id = $tenant_id AND payment_status = 'paid' AND (payment_method IS NULL OR payment_method = '')");
    $count = (int) ($res ? ($res->fetch_assoc()['total'] ?? 0) : 0);
    if ($count > 0) $add_incident('paid_without_method', 'warning', 'Pagos sin forma de pago', "Hay citas marcadas como pagadas sin indicar c\u{00F3}mo se cobraron.", 'Edita el pago de cada cita y selecciona efectivo, tarjeta, transferencia u otra forma de pago para mantener informes coherentes.', $count, 'billing_invoices');

    $exports_table = $mysqli->query("SHOW TABLES LIKE 'tenant_data_export_jobs'");
    if ($exports_table && $exports_table->num_rows > 0) {
        $res = $mysqli->query("SELECT status, error_message FROM tenant_data_export_jobs WHERE tenant_id = $tenant_id ORDER BY id DESC LIMIT 1");
        $row = $res ? $res->fetch_assoc() : null;
        if ($row && ($row['status'] ?? '') === 'failed') $add_incident('data_export_failed', 'danger', "La \u{00FA}ltima exportaci\u{00F3}n ha fallado", (string) (($row['error_message'] ?? '') ?: 'El proceso no pudo completarse.'), "Vuelve a generar la exportaci\u{00F3}n. Si se repite, revisa el espacio disponible y el Log para localizar el error.", 1, $is_superadmin ? 'data_export' : '');
    }

    $stmt = $mysqli->prepare("SELECT channel, COUNT(*) total FROM app_logs WHERE tenant_id = ? AND channel IN ('email','sms') AND status NOT IN ('ok','success') AND created_at >= DATE_SUB(NOW(), INTERVAL 7 DAY) GROUP BY channel");
    $stmt->bind_param('i', $tenant_id); $stmt->execute(); $failed_channels = $stmt->get_result();
    while ($row = $failed_channels->fetch_assoc()) {
        $channel = strtolower((string) $row['channel']); $count = (int) $row['total'];
        $label = $channel === 'sms' ? 'SMS' : 'emails';
        $add_incident('recent_' . $channel . '_failures', 'warning', "Env\u{00ED}os de {$label} fallidos", "Se han registrado fallos de {$label} durante los \u{00FA}ltimos 7 d\u{00ED}as.", "Consulta la pesta\u{00F1}a Log para ver el detalle y comprueba las credenciales, el remitente y el saldo o proveedor del servicio.", $count, 'app_log');
    }

    echo json_encode(['success' => true, 'incidents' => $incidents], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
} elseif ($action === 'list_app_logs') {
    ensure_app_logs_table($mysqli);
    $search = trim((string) ($_GET['search'] ?? ''));
    $date_to = trim((string) ($_GET['date_to'] ?? ''));
    $date_from = trim((string) ($_GET['date_from'] ?? ''));
    if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date_to)) {
        $date_to = date('Y-m-d');
    }
    if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $date_from)) {
        $date_from = date('Y-m-d', strtotime('-30 days'));
    }
    if ($date_from > $date_to) {
        [$date_from, $date_to] = [$date_to, $date_from];
    }

    $params = [$tenant_id, $date_from . ' 00:00:00', $date_to . ' 23:59:59'];
    $types = 'iss';
    $where = "l.tenant_id = ? AND l.created_at BETWEEN ? AND ?";
    if ($search !== '') {
        $like = '%' . $search . '%';
        $where .= " AND (l.action LIKE ? OR l.channel LIKE ? OR l.status LIKE ? OR l.title LIKE ? OR l.message LIKE ? OR u.name LIKE ?)";
        array_push($params, $like, $like, $like, $like, $like, $like);
        $types .= 'ssssss';
    }

    $stmt = $mysqli->prepare("
        SELECT l.id, l.created_at, l.user_id, l.target_type, l.target_id, l.action, l.channel, l.status,
               l.title, l.message, u.name AS user_name
        FROM app_logs l
        LEFT JOIN users u ON u.id = l.user_id AND u.tenant_id = l.tenant_id
        WHERE $where
        ORDER BY l.created_at DESC, l.id DESC
        LIMIT 300
    ");
    bind_params_dynamic($stmt, $types, $params);
    $stmt->execute();
    $rows = [];
    $res = $stmt->get_result();
    while ($row = $res->fetch_assoc()) {
        $rows[] = [
            'id' => (int) $row['id'],
            'created_at' => $row['created_at'],
            'user_id' => (int) ($row['user_id'] ?? 0),
            'user_name' => $row['user_name'] ?? '',
            'target_type' => $row['target_type'] ?? '',
            'target_id' => (int) ($row['target_id'] ?? 0),
            'action' => $row['action'] ?? '',
            'channel' => $row['channel'] ?? '',
            'status' => $row['status'] ?? '',
            'title' => $row['title'] ?? '',
            'message' => $row['message'] ?? ''
        ];
    }
    echo json_encode(['success' => true, 'logs' => $rows, 'date_from' => $date_from, 'date_to' => $date_to]);
} elseif ($action === 'appointment_payment_detail') {
    ensure_appointment_payment_columns($mysqli);
    ensure_appointment_services_tables($mysqli);
    $appointment_id = (int) ($_GET['appointment_id'] ?? 0);
    [$can_manage, $appointment] = admin_can_manage_appointment_payment($mysqli, $appointment_id);
    if (!$can_manage || !$appointment) {
        echo json_encode(['success' => false, 'error' => 'No autorizado para ver esta cita.']);
        exit;
    }

    $method = $appointment['payment_method'] ?? '';
    $professional_settings = cabinet_get_effective_professional_settings($mysqli, (int) ($appointment['professional_id'] ?? 0));
    $professional_delivery_mode = $professional_settings['appointment_delivery_mode'] ?? 'both';
    $livekit_for_professional = livekit_enabled_for_professional($mysqli, (int) ($appointment['professional_id'] ?? 0));
    $branding_settings = get_public_branding_settings($mysqli);
    $knowledge_problem = appointment_patient_knowledge_problem_payload($mysqli, (int) ($appointment['user_id'] ?? 0));
    echo json_encode([
        'success' => true,
        'appointment' => [
            'id' => (int) $appointment['id'],
            'patient_id' => (int) $appointment['user_id'],
            'patient_name' => $appointment['patient_name'] ?? '',
            'patient_email' => $appointment['patient_email'] ?? '',
            'patient_phone' => member_patient_phone($appointment['patient_phone'] ?? ''),
            'patient_address' => $appointment['patient_address'] ?? '',
            'professional_id' => (int) ($appointment['professional_id'] ?? 0),
            'professional_name' => $appointment['professional_name'] ?? '',
            'appointment_date' => $appointment['appointment_date'],
            'appointment_time' => substr((string) $appointment['appointment_time'], 0, 5),
            'status' => $appointment['status'] ?? '',
            'patient_confirmed_at' => $appointment['patient_confirmed_at'] ?? '',
            'consultation_type' => $appointment['consultation_type'] ?? 'presencial',
            'location_id' => (int) ($appointment['location_id'] ?? 0),
            'location_name' => $appointment['location_name'] ?? '',
            'location_type' => $appointment['location_type'] ?? '',
            'online_session_url' => $appointment['online_session_url'] ?? '',
            'session_notes' => $appointment['session_notes'] ?? '',
            'livekit_enabled' => $livekit_for_professional ? 1 : 0,
            'video_provider' => video_provider_for_professional($mysqli, (int) ($appointment['professional_id'] ?? 0)),
            'video_recording_enabled' => livekit_recording_enabled_for_professional($mysqli, (int) ($appointment['professional_id'] ?? 0)) ? 1 : 0,
            'default_appointment_location' => trim((string) ($professional_settings['default_appointment_location'] ?? '')),
            'default_location_id' => (int) ($professional_settings['default_location_id'] ?? 0),
            'locations' => fetch_appointment_locations($mysqli, true),
            'center_address' => trim((string) ($branding_settings['legal_address'] ?? '')),
            'can_online_appointment' => in_array($professional_delivery_mode, ['both', 'online'], true) ? 1 : 0,
            'can_presential_appointment' => in_array($professional_delivery_mode, ['both', 'presencial'], true) ? 1 : 0,
            'duration_minutes' => (int) ($appointment['duration_minutes'] ?? 60),
            'service_label' => appointment_service_option_label($appointment),
            'payment_status' => $appointment['payment_status'] ?? 'pending',
            'payment_method' => $method,
            'payment_method_label' => payment_method_label($method),
            'patient_bonus_id' => $appointment['patient_bonus_id'],
            'paid_at' => $appointment['paid_at'],
            'payment_updated_at' => $appointment['payment_updated_at'] ?? null,
            'is_bonus_payment' => ($method === 'bonus' || !empty($appointment['patient_bonus_id'])) ? 1 : 0,
            'knowledge_problem' => $knowledge_problem
        ]
    ]);
} elseif ($action === 'appointment_session') {
    ensure_patient_work_plan_tables($mysqli);
    ensure_patient_evolution_tables($mysqli);
    $online_document_editor_enabled = plan_feature_enabled_from_db($mysqli, 'documents.onlineEditor', false);
    $drawing_board_enabled = plan_feature_enabled_from_db($mysqli, 'documents.drawingBoard', false);
    $appointment_id = (int) ($_GET['appointment_id'] ?? 0);
    [$can_manage, $appointment] = admin_can_manage_appointment_payment($mysqli, $appointment_id);
    if (!$can_manage || !$appointment) {
        echo json_encode(['success' => false, 'error' => 'No autorizado para ver esta sesion.']);
        exit;
    }
    $patient_id = (int) ($appointment['user_id'] ?? 0);

    $stmt = $mysqli->prepare("
        SELECT t.id, t.patient_id, t.appointment_id, t.professional_id, t.title, t.description,
               t.status, t.priority, t.visible_to_patient, t.document_id,
               t.requires_docx, t.requires_drawing, t.requires_file, t.response_docx_document_id, t.response_drawing_document_id, t.response_file_document_id,
               t.completed_at, t.created_at, t.updated_at,
               d.original_file_name AS attachment_original_name,
               d.mime_type AS attachment_mime_type,
               d.editable_file_path AS attachment_editable_file_path
        FROM patient_work_plan_tasks t
        LEFT JOIN patient_documents d
          ON d.id = t.document_id
         AND d.tenant_id = t.tenant_id
         AND d.patient_id = t.patient_id
        WHERE t.tenant_id = ?
          AND t.patient_id = ?
        ORDER BY
            CASE WHEN t.status = 'pending' THEN 0 ELSE 1 END,
            t.priority ASC,
            t.updated_at DESC,
            t.id DESC
    ");
    $stmt->bind_param("ii", $tenant_id, $patient_id);
    $stmt->execute();
    $tasks_res = $stmt->get_result();
    $tasks = [];
    while ($row = $tasks_res->fetch_assoc()) {
        $tasks[] = [
            'id' => (int) $row['id'],
            'patient_id' => (int) $row['patient_id'],
            'appointment_id' => (int) ($row['appointment_id'] ?? 0),
            'professional_id' => (int) ($row['professional_id'] ?? 0),
            'title' => $row['title'],
            'description' => $row['description'] ?? '',
            'status' => $row['status'],
            'priority' => (int) ($row['priority'] ?? 2),
            'visible_to_patient' => (int) ($row['visible_to_patient'] ?? 0),
            'requires_docx' => (int) ($row['requires_docx'] ?? 0),
            'requires_drawing' => (int) ($row['requires_drawing'] ?? 0),
            'requires_file' => (int) ($row['requires_file'] ?? 0),
            'response_docx_document_id' => (int) ($row['response_docx_document_id'] ?? 0),
            'response_drawing_document_id' => (int) ($row['response_drawing_document_id'] ?? 0),
            'response_file_document_id' => (int) ($row['response_file_document_id'] ?? 0),
            'document_id' => (int) ($row['document_id'] ?? 0),
            'attachment_original_name' => $row['attachment_original_name'] ?? '',
            'attachment_mime_type' => $row['attachment_mime_type'] ?? '',
            'can_edit_docx' => !empty($row['attachment_editable_file_path']) && $online_document_editor_enabled ? 1 : 0,
            'completed_at' => $row['completed_at'] ?? '',
            'created_at' => $row['created_at'] ?? '',
            'updated_at' => $row['updated_at'] ?? ''
        ];
    }

    $stmt = $mysqli->prepare("
        SELECT n.id, n.patient_id, n.appointment_id, n.professional_id, n.note_date, n.title,
               n.description, n.observations, n.next_steps, n.created_at, n.updated_at,
               COUNT(f.id) AS file_count
        FROM patient_evolution_notes n
        LEFT JOIN patient_evolution_files f ON f.evolution_note_id = n.id AND f.tenant_id = n.tenant_id
        WHERE n.tenant_id = ?
          AND n.patient_id = ? AND n.appointment_id = ?
        GROUP BY n.id
        ORDER BY n.note_date DESC, n.id DESC
    ");
    $stmt->bind_param("iii", $tenant_id, $patient_id, $appointment_id);
    $stmt->execute();
    $notes_res = $stmt->get_result();
    $notes = [];
    while ($row = $notes_res->fetch_assoc()) {
        $notes[] = [
            'id' => (int) $row['id'],
            'patient_id' => (int) $row['patient_id'],
            'appointment_id' => (int) ($row['appointment_id'] ?? 0),
            'professional_id' => (int) ($row['professional_id'] ?? 0),
            'note_date' => $row['note_date'],
            'title' => $row['title'],
            'description' => $row['description'] ?? '',
            'observations' => $row['observations'] ?? '',
            'next_steps' => $row['next_steps'] ?? '',
            'file_count' => (int) ($row['file_count'] ?? 0),
            'files' => [],
            'created_at' => $row['created_at'],
            'updated_at' => $row['updated_at']
        ];
    }

    $stmt = $mysqli->prepare("
        SELECT f.id, f.evolution_note_id, f.original_name, f.file_size, f.visible_to_patient, f.uploaded_at, n.title
        FROM patient_evolution_files f
        JOIN patient_evolution_notes n ON n.id = f.evolution_note_id AND n.tenant_id = f.tenant_id
        WHERE f.tenant_id = ?
          AND f.patient_id = ? AND n.appointment_id = ?
        ORDER BY f.uploaded_at DESC, f.id DESC
    ");
    $stmt->bind_param("iii", $tenant_id, $patient_id, $appointment_id);
    $stmt->execute();
    $files_res = $stmt->get_result();
    $files = [];
    while ($row = $files_res->fetch_assoc()) {
        $file_payload = [
            'type' => 'evolution_file',
            'id' => (int) $row['id'],
            'note_id' => (int) ($row['evolution_note_id'] ?? 0),
            'name' => $row['original_name'],
            'source' => $row['title'] ?: 'Nota de sesion',
            'date' => $row['uploaded_at'],
            'size' => (int) ($row['file_size'] ?? 0),
            'visible_to_patient' => (int) ($row['visible_to_patient'] ?? 0),
            'url' => 'api/admin.php?action=download_evolution_file&id=' . (int) $row['id'],
            'can_edit_docx' => 0,
            'can_edit_drawing' => 0,
            'can_delete' => 1
        ];
        $files[] = $file_payload;
        foreach ($notes as &$note) {
            if ((int) $note['id'] === (int) $file_payload['note_id']) {
                $note['files'][] = $file_payload;
                break;
            }
        }
        unset($note);
    }

    $stmt = $mysqli->prepare("
        SELECT d.*,
               (SELECT COUNT(*) FROM patient_document_versions v WHERE v.tenant_id = d.tenant_id AND v.document_id = d.id) AS version_count
        FROM patient_documents d
        WHERE d.tenant_id = ?
          AND d.patient_id = ?
          AND d.appointment_id = ?
        ORDER BY d.updated_at DESC, d.id DESC
    ");
    $stmt->bind_param("iii", $tenant_id, $patient_id, $appointment_id);
    $stmt->execute();
    $doc_res = $stmt->get_result();
    while ($row = $doc_res->fetch_assoc()) {
        $files[] = [
            'type' => 'patient_document',
            'document_type' => $row['document_type'] ?? 'file',
            'id' => (int) $row['id'],
            'note_id' => 0,
            'name' => $row['title'] ?: ($row['original_file_name'] ?: 'Documento'),
            'file_name' => $row['original_file_name'] ?: '',
            'source' => 'Documento',
            'date' => $row['updated_at'] ?: ($row['created_at'] ?? $row['document_date']),
            'document_date' => $row['document_date'] ?: '',
            'size' => (int) ($row['file_size'] ?? 0),
            'url' => $row['file_path'] ? 'api/admin.php?action=download_patient_document_file&id=' . (int) $row['id'] : '',
            'mime_type' => $row['mime_type'] ?: '',
            'visible_to_patient' => (int) ($row['visible_to_patient'] ?? 0),
            'version_count' => (int) ($row['version_count'] ?? 0),
            'can_edit_docx' => ($online_document_editor_enabled && patient_document_is_docx($row)) ? 1 : 0,
            'can_edit_drawing' => ($drawing_board_enabled && patient_document_is_drawing($row)) ? 1 : 0,
            'can_delete' => 1
        ];
    }

    echo json_encode([
        'success' => true,
        'appointment_id' => $appointment_id,
        'patient_id' => $patient_id,
        'tasks' => $tasks,
        'notes' => $notes,
        'files' => $files
    ]);
} elseif ($action === 'update_appointment_payment') {
    ensure_appointment_payment_columns($mysqli);
    ensure_appointment_services_tables($mysqli);
    $appointment_id = (int) ($_POST['appointment_id'] ?? 0);
    $payment_status = $_POST['payment_status'] ?? 'pending';
    $payment_method = trim($_POST['payment_method'] ?? '');
    $session_notes_was_posted = array_key_exists('session_notes', $_POST);
    $session_notes = trim((string) ($_POST['session_notes'] ?? ''));
    [$can_manage, $appointment] = admin_can_manage_appointment_payment($mysqli, $appointment_id);
    if (!$can_manage || !$appointment) {
        echo json_encode(['success' => false, 'error' => 'No autorizado para actualizar esta cita.']);
        exit;
    }
    if (($appointment['payment_method'] ?? '') === 'bonus' || !empty($appointment['patient_bonus_id'])) {
        echo json_encode(['success' => false, 'error' => 'Esta cita fue pagada con bono y no es posible modificarlo desde aqui.']);
        exit;
    }
    if (($appointment['status'] ?? '') === 'cancelled') {
        echo json_encode(['success' => false, 'error' => 'No se puede modificar el pago de una cita cancelada.']);
        exit;
    }
    if (!in_array($payment_status, ['pending', 'paid'], true)) {
        echo json_encode(['success' => false, 'error' => 'Estado de pago no válido.']);
        exit;
    }

    $allowed_methods = ['card', 'bizum', 'cash', 'bank_transfer', 'other', 'manual'];
    $current_status = $appointment['payment_status'] ?? 'pending';
    $marking_as_paid = $payment_status === 'paid' && $current_status !== 'paid';
    $billing_enabled = invoice_billing_enabled($mysqli);
    if ($billing_enabled && $marking_as_paid && !invoice_manual_confirmation_received()) {
        echo json_encode(['success' => false, 'error' => 'Confirma la emision de la factura para marcar esta cita como pagada.']);
        exit;
    }
    if ($billing_enabled && $marking_as_paid) {
        [$recipient_ok, $recipient_error] = invoice_recipient_for_user($mysqli, (int) ($appointment['user_id'] ?? 0));
        if (!$recipient_ok) {
            echo json_encode(['success' => false, 'error' => $recipient_error]);
            exit;
        }
        $invoice_precheck = invoice_emit_for_appointment($mysqli, $appointment_id, $payment_method, true);
        if (empty($invoice_precheck['success'])) {
            echo json_encode(['success' => false, 'error' => $invoice_precheck['error'] ?? 'La factura no supera la validación previa.']);
            exit;
        }
    }
    $existing_invoice = invoice_existing_for_origin($mysqli, 'appointment', $appointment_id);
    if ($existing_invoice) {
        $current_method = $appointment['payment_method'] ?? '';
        if ($payment_status !== $current_status || ($payment_status === 'paid' && $payment_method !== $current_method)) {
            echo json_encode(['success' => false, 'error' => 'Esta cita ya tiene factura emitida y no se puede modificar el cobro.']);
            exit;
        }
    }
    if ($payment_status === 'paid' && !in_array($payment_method, $allowed_methods, true)) {
        echo json_encode(['success' => false, 'error' => 'Indica una forma de pago valida.']);
        exit;
    }

    $mysqli->begin_transaction();
    try {
    if ($payment_status === 'paid') {
        if (!in_array($payment_method, $allowed_methods, true)) {
            echo json_encode(['success' => false, 'error' => 'Indica una forma de pago válida.']);
            exit;
        }
        $stmt = $mysqli->prepare("
            UPDATE appointments
            SET payment_status = 'paid',
                payment_method = ?,
                paid_at = COALESCE(paid_at, NOW()),
                payment_updated_at = NOW(),
                payment_updated_by = ?
            WHERE tenant_id = ? AND id = ?
        ");
        $session_user_id = (int) ($_SESSION['user_id'] ?? 0);
        $stmt->bind_param("siii", $payment_method, $session_user_id, $tenant_id, $appointment_id);
    } else {
        $stmt = $mysqli->prepare("
            UPDATE appointments
            SET payment_status = 'pending',
                payment_method = NULL,
                paid_at = NULL,
                payment_updated_at = NOW(),
                payment_updated_by = ?
            WHERE tenant_id = ? AND id = ?
        ");
        $session_user_id = (int) ($_SESSION['user_id'] ?? 0);
        $stmt->bind_param("iii", $session_user_id, $tenant_id, $appointment_id);
    }

    if (!$stmt->execute()) {
        throw new Exception('No se pudo actualizar el pago.');
    }

    if ($session_notes_was_posted) {
        $stmt = $mysqli->prepare("UPDATE appointments SET session_notes = ? WHERE tenant_id = ? AND id = ?");
        $stmt->bind_param("sii", $session_notes, $tenant_id, $appointment_id);
        if (!$stmt->execute()) {
            throw new Exception('No se pudieron guardar las notas de la sesion.');
        }
    }

    $invoice_warning = '';
    $invoice_number = '';
    if ($payment_status === 'paid') {
        $invoice_result = invoice_emit_for_appointment($mysqli, $appointment_id, $payment_method);
        if (!empty($invoice_result['success'])) {
            $invoice_number = $invoice_result['invoice_number'] ?? '';
        } else {
            throw new Exception($invoice_result['error'] ?? 'No se pudo emitir la factura.');
        }
    }
        $mysqli->commit();
    } catch (\Exception $e) {
        $mysqli->rollback();
        echo json_encode(['success' => false, 'error' => $e->getMessage()]);
        exit;
    }

    $previous_method = $appointment['payment_method'] ?? '';
    if ($payment_status !== $current_status || ($payment_status === 'paid' && $payment_method !== $previous_method)) {
        app_log($mysqli, [
            'action' => 'appointment_payment_updated',
            'status' => 'ok',
            'target_type' => 'appointment',
            'target_id' => $appointment_id,
            'title' => 'Pago de cita actualizado',
            'message' => 'Pago actualizado de ' . ($current_status ?: 'pending') . ' a ' . $payment_status . '.',
            'metadata' => [
                'patient_id' => (int) ($appointment['user_id'] ?? 0),
                'patient_name' => $appointment['patient_name'] ?? '',
                'professional_id' => (int) ($appointment['professional_id'] ?? 0),
                'appointment_date' => $appointment['appointment_date'] ?? '',
                'appointment_time' => $appointment['appointment_time'] ?? '',
                'previous_payment_status' => $current_status,
                'new_payment_status' => $payment_status,
                'previous_payment_method' => $previous_method,
                'new_payment_method' => $payment_status === 'paid' ? $payment_method : '',
                'invoice_number' => $invoice_number
            ]
        ]);
    }

    echo json_encode([
        'success' => true,
        'message' => $invoice_warning ? 'Cambios guardados, pero no se pudo emitir la factura: ' . $invoice_warning : 'Cambios guardados correctamente.',
        'invoice_number' => $invoice_number,
        'invoice_warning' => $invoice_warning,
        'session_notes' => $session_notes_was_posted ? $session_notes : ($appointment['session_notes'] ?? '')
    ]);
} elseif ($action === 'update_appointment_status') {
    ensure_appointment_payment_columns($mysqli);
    $appointment_id = (int) ($_POST['appointment_id'] ?? 0);
    $status = $_POST['status'] ?? 'booked';
    [$can_manage, $appointment] = admin_can_manage_appointment_payment($mysqli, $appointment_id);
    if (!$can_manage || !$appointment) {
        echo json_encode(['success' => false, 'error' => 'No autorizado para actualizar esta cita.']);
        exit;
    }
    if (!in_array($status, ['booked', 'completed', 'no_show'], true)) {
        echo json_encode(['success' => false, 'error' => 'Estado de asistencia no valido.']);
        exit;
    }
    if (($appointment['status'] ?? '') === 'cancelled') {
        echo json_encode(['success' => false, 'error' => 'No se puede modificar el estado de una cita cancelada.']);
        exit;
    }
    try {
        $stmt = $mysqli->prepare("UPDATE appointments SET status = ? WHERE tenant_id = ? AND id = ?");
        $stmt->bind_param("sii", $status, $tenant_id, $appointment_id);
        $stmt->execute();
    } catch (Throwable $e) {
        echo json_encode(['success' => false, 'error' => 'No se pudo actualizar el estado de asistencia: ' . $e->getMessage()]);
        exit;
    }
    $labels = [
        'booked' => 'reservada',
        'completed' => 'realizada',
        'no_show' => 'no asistida'
    ];
    if (($appointment['status'] ?? '') !== $status) {
        app_log($mysqli, [
            'action' => 'appointment_attendance_updated',
            'status' => 'ok',
            'target_type' => 'appointment',
            'target_id' => $appointment_id,
            'title' => 'Estado de asistencia actualizado',
            'message' => 'Cita marcada como ' . ($labels[$status] ?? 'actualizada') . '.',
            'metadata' => [
                'patient_id' => (int) ($appointment['user_id'] ?? 0),
                'patient_name' => $appointment['patient_name'] ?? '',
                'professional_id' => (int) ($appointment['professional_id'] ?? 0),
                'appointment_date' => $appointment['appointment_date'] ?? '',
                'appointment_time' => $appointment['appointment_time'] ?? '',
                'previous_status' => $appointment['status'] ?? '',
                'new_status' => $status
            ]
        ]);
    }
    echo json_encode([
        'success' => true,
        'status' => $status,
        'message' => 'Cita marcada como ' . ($labels[$status] ?? 'actualizada') . '.'
    ]);
} elseif ($action === 'update_appointment_session_notes') {
    ensure_appointment_payment_columns($mysqli);
    $appointment_id = (int) ($_POST['appointment_id'] ?? 0);
    $session_notes = trim((string) ($_POST['session_notes'] ?? ''));
    [$can_manage, $appointment] = admin_can_manage_appointment_payment($mysqli, $appointment_id);
    if (!$can_manage || !$appointment) {
        echo json_encode(['success' => false, 'error' => 'No autorizado para actualizar esta cita.']);
        exit;
    }
    try {
        $stmt = $mysqli->prepare("UPDATE appointments SET session_notes = ? WHERE tenant_id = ? AND id = ?");
        $stmt->bind_param("sii", $session_notes, $tenant_id, $appointment_id);
        $stmt->execute();
    } catch (Throwable $e) {
        echo json_encode(['success' => false, 'error' => 'No se pudieron guardar las notas de la sesion: ' . $e->getMessage()]);
        exit;
    }
    echo json_encode([
        'success' => true,
        'session_notes' => $session_notes,
        'message' => 'Notas de la sesion guardadas.'
    ]);
} elseif ($action === 'update_appointment_online_details') {
    ensure_appointment_payment_columns($mysqli);
    ensure_appointment_services_tables($mysqli);
    ensure_appointment_locations_table($mysqli);
    $appointment_id = (int) ($_POST['appointment_id'] ?? 0);
    $consultation_type = $_POST['consultation_type'] ?? 'presencial';
    $online_session_url = trim($_POST['online_session_url'] ?? '');
    $location_id = (int) ($_POST['location_id'] ?? 0);
    [$can_manage, $appointment] = admin_can_manage_appointment_payment($mysqli, $appointment_id);
    if (!$can_manage || !$appointment) {
        echo json_encode(['success' => false, 'error' => 'No autorizado para actualizar esta cita.']);
        exit;
    }
    if (($appointment['status'] ?? '') === 'cancelled') {
        echo json_encode(['success' => false, 'error' => 'No se puede modificar una cita cancelada.']);
        exit;
    }
    if (!in_array($consultation_type, ['presencial', 'online'], true)) {
        echo json_encode(['success' => false, 'error' => 'Modalidad no valida.']);
        exit;
    }
    $professional_settings = cabinet_get_effective_professional_settings($mysqli, (int) ($appointment['professional_id'] ?? 0));
    $professional_delivery_mode = $professional_settings['appointment_delivery_mode'] ?? 'both';
    $uses_livekit = $consultation_type === 'online' && livekit_enabled_for_professional($mysqli, (int) ($appointment['professional_id'] ?? 0));
    if ($consultation_type === 'online' && !in_array($professional_delivery_mode, ['both', 'online'], true)) {
        echo json_encode(['success' => false, 'error' => 'Este profesional no admite citas online.']);
        exit;
    }
    if ($consultation_type === 'presencial' && !in_array($professional_delivery_mode, ['both', 'presencial'], true)) {
        echo json_encode(['success' => false, 'error' => 'Este profesional no admite citas presenciales.']);
        exit;
    }
    if ($uses_livekit) {
        $online_session_url = '';
    } elseif ($consultation_type === 'online' && $online_session_url !== '' && !filter_var($online_session_url, FILTER_VALIDATE_URL)) {
        echo json_encode(['success' => false, 'error' => 'Indica un enlace valido para la videollamada.']);
        exit;
    }
    $location = null;
    if ($consultation_type === 'presencial') {
        $location_id = normalize_location_id($mysqli, $location_id);
        $location = fetch_appointment_location($mysqli, $location_id);
        $online_session_url = appointment_location_display_name($location);
    } else {
        $location_id = null;
    }

    $stmt = $mysqli->prepare("UPDATE appointments SET consultation_type = ?, location_id = ?, online_session_url = ? WHERE tenant_id = ? AND id = ?");
    $stmt->bind_param("sisii", $consultation_type, $location_id, $online_session_url, $tenant_id, $appointment_id);
    if (!$stmt->execute()) {
        echo json_encode(['success' => false, 'error' => 'No se pudo guardar la modalidad de la cita.']);
        exit;
    }

    $livekit_link_ready = false;
    if ($uses_livekit) {
        $livekit_link_ready = livekit_ensure_appointment_link_token(
            $mysqli,
            $appointment_id,
            (string) ($appointment['livekit_access_token'] ?? '')
        ) !== '';
    }

    echo json_encode([
        'success' => true,
        'message' => $uses_livekit && $livekit_link_ready
            ? 'Modalidad de la cita actualizada. Enlace de videollamada preparado.'
            : 'Modalidad de la cita actualizada.',
        'consultation_type' => $consultation_type,
        'location_id' => $location_id ?: 0,
        'location_name' => $location['name'] ?? '',
        'location_type' => $location['location_type'] ?? '',
        'online_session_url' => $online_session_url,
        'livekit_enabled' => livekit_enabled_for_professional($mysqli, (int) ($appointment['professional_id'] ?? 0)) ? 1 : 0,
        'video_provider' => video_provider_for_professional($mysqli, (int) ($appointment['professional_id'] ?? 0)),
        'livekit_link_ready' => $livekit_link_ready ? 1 : 0
    ]);
} elseif ($action === 'send_appointment_online_link') {
    ensure_appointment_payment_columns($mysqli);
    $appointment_id = (int) ($_POST['appointment_id'] ?? 0);
    [$can_manage, $appointment] = admin_can_manage_appointment_payment($mysqli, $appointment_id);
    if (!$can_manage || !$appointment) {
        echo json_encode(['success' => false, 'error' => 'No autorizado para enviar este enlace.']);
        exit;
    }
    if (($appointment['status'] ?? '') !== 'booked') {
        echo json_encode(['success' => false, 'error' => 'Solo se puede enviar el enlace de una cita reservada.']);
        exit;
    }
    if (($appointment['consultation_type'] ?? 'presencial') !== 'online') {
        echo json_encode(['success' => false, 'error' => 'La cita no esta marcada como online.']);
        exit;
    }
    $uses_livekit = livekit_appointment_enabled($mysqli, $appointment);
    if ($uses_livekit) {
        $appointment['livekit_access_token'] = livekit_ensure_appointment_link_token(
            $mysqli,
            $appointment_id,
            (string) ($appointment['livekit_access_token'] ?? '')
        );
    }
    $online_session_url = $uses_livekit ? livekit_patient_join_url($appointment) : trim($appointment['online_session_url'] ?? '');
    if ($online_session_url === '') {
        echo json_encode(['success' => false, 'error' => 'Guarda primero el enlace de videollamada.']);
        exit;
    }
    if (empty($appointment['patient_email']) || !filter_var($appointment['patient_email'], FILTER_VALIDATE_EMAIL)) {
        echo json_encode(['success' => false, 'error' => 'El paciente no tiene un email valido.']);
        exit;
    }

    $appointment_text = appointment_label($appointment['appointment_date'], $appointment['appointment_time']);
    $service_text = appointment_service_option_label($appointment);
    $professional_line = !empty($appointment['professional_name'])
        ? '<p><b>Profesional:</b> ' . htmlspecialchars($appointment['professional_name']) . '</p>'
        : '';
    $sent = send_app_email(
        $appointment['patient_email'],
        'Enlace para tu cita online',
        '<p>Hola ' . htmlspecialchars($appointment['patient_name'] ?? 'Paciente') . ',</p>' .
        '<p>Te enviamos el enlace para tu cita online del ' . htmlspecialchars($appointment_text) . '.</p>' .
        $professional_line .
        '<p><b>Servicio:</b> ' . htmlspecialchars($service_text) . '</p>' .
        tenant_email_action_button($mysqli, $online_session_url, 'Acceder a la videollamada'),
        get_professional_reply_to_email($mysqli, (int) ($appointment['professional_id'] ?? 0)),
        $mysqli
    );

    echo json_encode($sent
        ? ['success' => true, 'message' => 'Enlace enviado al paciente.']
        : ['success' => false, 'error' => 'No se pudo enviar el email al paciente.']);
} elseif ($action === 'send_manual_appointment_reminder') {
    ensure_appointment_payment_columns($mysqli);
    ensure_appointment_services_tables($mysqli);
    $appointment_id = (int) ($_POST['appointment_id'] ?? 0);
    $channel = strtolower(trim((string) ($_POST['channel'] ?? 'email')));
    if (!in_array($channel, ['email', 'sms'], true)) {
        echo json_encode(['success' => false, 'error' => 'Canal de recordatorio no valido.']);
        exit;
    }
    if ($channel === 'email' && !plan_feature_enabled_from_db($mysqli, 'reminders.patient24h', false)) {
        echo json_encode(['success' => false, 'error' => 'Los recordatorios por email no estan disponibles en este plan.']);
        exit;
    }
    if ($channel === 'sms' && !plan_feature_enabled_from_db($mysqli, 'reminders.sms', false)) {
        echo json_encode(['success' => false, 'error' => 'Los recordatorios por SMS no estan disponibles en este plan.']);
        exit;
    }
    if ($channel === 'email' && !app_email_is_configured($mysqli)) {
        echo json_encode(['success' => false, 'error' => 'El envío de emails no está configurado.']);
        exit;
    }
    $manual_sms_settings = $channel === 'sms' ? sms_get_settings($mysqli) : [];
    if ($channel === 'sms' && (!sms_is_configured($mysqli) || (int) ($manual_sms_settings['sms_reminder_enabled'] ?? 0) !== 1)) {
        echo json_encode(['success' => false, 'error' => 'El envío de SMS no está configurado.']);
        exit;
    }
    [$can_manage, $appointment] = admin_can_manage_appointment_payment($mysqli, $appointment_id);
    if (!$can_manage || !$appointment) {
        echo json_encode(['success' => false, 'error' => 'No autorizado para enviar este recordatorio.']);
        exit;
    }
    if (($appointment['status'] ?? '') !== 'booked') {
        $message = 'Solo se pueden enviar recordatorios de citas reservadas.';
        admin_log_manual_reminder($mysqli, $appointment, $channel, false, $message);
        echo json_encode(['success' => false, 'error' => $message]);
        exit;
    }

    $settings = admin_payment_settings_for_reminder($mysqli);
    if ($channel === 'email') {
        if (empty($appointment['patient_email']) || !filter_var($appointment['patient_email'], FILTER_VALIDATE_EMAIL)) {
            $message = 'El paciente no tiene un email valido.';
            admin_log_manual_reminder($mysqli, $appointment, 'email', false, $message);
            echo json_encode(['success' => false, 'error' => $message]);
            exit;
        }
        $template = message_template_get($mysqli, 'appointment_email_reminder');
        $context = admin_appointment_reminder_context($mysqli, $appointment, $settings, false);
        $vars = $context['vars'];
        $body = admin_reminder_email_body_to_html(message_template_render($template['body'] ?? message_template_default_body('appointment_email_reminder'), $vars));

        $online_link_note = '';
        if (($appointment['consultation_type'] ?? '') === 'online' && !empty($context['online_link'])) {
            $online_link_note =
                '<p><b>Enlace de videollamada:</b></p>' .
                tenant_email_action_button($mysqli, $context['online_link'], 'Acceder a la cita online');
        }
        $payment_note = '';
        if ((int) ($settings['online_payment_enabled'] ?? 0) === 1 && ($appointment['payment_status'] ?? '') !== 'paid') {
            $payment_note = '<p>Si no has hecho aun el pago, puedes realizar el pago con tarjeta o Bizum desde el mismo enlace.</p>';
        }
        $body .=
            '<p><b>Servicio:</b> ' . htmlspecialchars($context['service_text']) . '</p>' .
            '<p><b>Modalidad:</b> ' . htmlspecialchars($context['consultation_text']) . '</p>' .
            $online_link_note .
            '<p><b>Importe:</b> ' . htmlspecialchars($context['price']) . ' &euro;</p>' .
            '<p><a href="' . htmlspecialchars($context['manage_link']) . '">Gestionar/cancelar reserva</a></p>' .
            $payment_note;
        $subject = message_template_render($template['subject'] ?: message_template_default_subject('appointment_email_reminder'), $vars);
        $sent = send_app_email(
            $appointment['patient_email'],
            $subject,
            $body,
            get_professional_reply_to_email($mysqli, (int) ($appointment['professional_id'] ?? 0)),
            $mysqli
        );
        $email_error = $sent ? '' : (function_exists('get_app_email_last_error') ? get_app_email_last_error() : '');
        $message = $sent
            ? 'Recordatorio enviado por email a ' . $appointment['patient_email'] . '.'
            : 'No se pudo enviar el recordatorio por email.' . ($email_error !== '' ? ' Motivo: ' . $email_error : '');
        admin_log_manual_reminder($mysqli, $appointment, 'email', $sent, $message, [
            'recipient' => $appointment['patient_email'] ?? '',
            'error' => $email_error
        ]);
        echo json_encode($sent
            ? ['success' => true, 'message' => 'Recordatorio enviado por email.']
            : ['success' => false, 'error' => 'No se pudo enviar el recordatorio por email.' . ($email_error !== '' ? ' ' . $email_error : '')]);
        exit;
    }

    if (empty($appointment['patient_phone'])) {
        $message = 'El paciente no tiene telefono guardado.';
        admin_log_manual_reminder($mysqli, $appointment, 'sms', false, $message);
        echo json_encode(['success' => false, 'error' => $message]);
        exit;
    }
    $sms_settings = sms_get_settings($mysqli);
    $settings = array_merge($settings, $sms_settings);
    $template = message_template_get($mysqli, 'appointment_sms_reminder');
    $context = admin_appointment_reminder_context($mysqli, $appointment, $settings, true);
    $message_body = message_template_render($template['body'] ?? message_template_default_body('appointment_sms_reminder'), $context['vars']);
    if (strpos($message_body, $context['manage_link']) === false) {
        $message_body .= ' Gestionar/cancelar: ' . $context['manage_link'];
    }
    try {
        $sms_result = sms_send_with_settings($settings, $appointment['patient_phone'], $message_body, [
            'custom' => 'manual-reminder-' . $tenant_id . '-' . (int) $appointment['id']
        ]);
    } catch (Throwable $e) {
        $sms_result = ['success' => false, 'error' => $e->getMessage()];
    }
    $sent = !empty($sms_result['success']);
    $message = $sent
        ? 'Recordatorio enviado por SMS a ' . $appointment['patient_phone'] . '.'
        : ('No se pudo enviar el recordatorio por SMS: ' . ($sms_result['error'] ?? 'Error desconocido.'));
    admin_log_manual_reminder($mysqli, $appointment, 'sms', $sent, $message, [
        'recipient' => $appointment['patient_phone'] ?? '',
        'provider' => $sms_settings['sms_provider'] ?? '',
        'sms_id' => $sms_result['id'] ?? ''
    ]);
    echo json_encode($sent
        ? ['success' => true, 'message' => 'Recordatorio enviado por SMS.']
        : ['success' => false, 'error' => $sms_result['error'] ?? 'No se pudo enviar el recordatorio por SMS.']);
} elseif ($action === 'daily_appointment_recordings') {
    $appointment_id = (int) ($_GET['appointment_id'] ?? 0);
    [$can_manage, $appointment] = admin_can_manage_appointment_payment($mysqli, $appointment_id);
    if (!$can_manage || !$appointment) {
        echo json_encode(['success' => false, 'error' => 'No autorizado para consultar las grabaciones de esta cita.']);
        exit;
    }
    try {
        $recordings = daily_sync_appointment_recordings($mysqli, $appointment);
        echo json_encode(['success' => true, 'recordings' => $recordings]);
    } catch (Throwable $e) {
        echo json_encode(['success' => false, 'error' => $e->getMessage()]);
    }
    exit;
} elseif ($action === 'regenerate_appointment_livekit_link') {
    ensure_appointment_payment_columns($mysqli);
    $appointment_id = (int) ($_POST['appointment_id'] ?? 0);
    [$can_manage, $appointment] = admin_can_manage_appointment_payment($mysqli, $appointment_id);
    if (!$can_manage || !$appointment) {
        echo json_encode(['success' => false, 'error' => 'No autorizado para regenerar este enlace.']);
        exit;
    }
    if (($appointment['status'] ?? '') !== 'booked' || !livekit_appointment_enabled($mysqli, $appointment)) {
        echo json_encode(['success' => false, 'error' => 'Esta cita no tiene una videollamada integrada activa.']);
        exit;
    }
    $token = livekit_ensure_appointment_link_token($mysqli, $appointment_id, '', true);
    if ($token === '') {
        echo json_encode(['success' => false, 'error' => 'No se pudo regenerar el enlace de videollamada.']);
        exit;
    }
    echo json_encode([
        'success' => true,
        'message' => 'Enlace de videollamada regenerado. El enlace anterior ya no es válido.'
    ]);
} elseif ($action === 'livekit_recording_status') {
    $appointment_id = (int) ($_GET['appointment_id'] ?? 0);
    [$can_manage, $appointment] = admin_can_manage_appointment_payment($mysqli, $appointment_id);
    if (!$can_manage || !$appointment) {
        echo json_encode(['success' => false, 'error' => 'No autorizado para consultar la configuración de grabación.']);
        exit;
    }
    $professional_id = (int) ($appointment['professional_id'] ?? 0);
    $settings = cabinet_get_effective_professional_settings($mysqli, $professional_id);
    $mode = in_array($settings['livekit_recording_mode'] ?? 'audio', ['audio', 'audio_video'], true)
        ? $settings['livekit_recording_mode']
        : 'audio';
    if (!video_recording_video_plan_enabled($mysqli)) $mode = 'audio';
    echo json_encode([
        'success' => true,
        'allowed' => ($appointment['status'] ?? '') === 'booked'
            && livekit_appointment_enabled($mysqli, $appointment)
            && livekit_recording_enabled_for_professional($mysqli, $professional_id),
        'storage_ready' => video_provider_for_professional($mysqli, $professional_id) === 'daily' ? daily_is_configured() : livekit_recording_storage_configured(),
        'mode' => $mode,
    ]);
    exit;
} elseif ($action === 'start_livekit_recording') {
    ensure_appointment_payment_columns($mysqli);
    ensure_livekit_recording_schema($mysqli);
    $appointment_id = (int) ($_POST['appointment_id'] ?? 0);
    [$can_manage, $appointment] = admin_can_manage_appointment_payment($mysqli, $appointment_id);
    if (!$can_manage || !$appointment) {
        echo json_encode(['success' => false, 'error' => 'No autorizado para iniciar la grabación.']);
        exit;
    }
    if (($appointment['status'] ?? '') !== 'booked' || !livekit_appointment_enabled($mysqli, $appointment)) {
        echo json_encode(['success' => false, 'error' => 'Esta cita no tiene una videollamada LiveKit activa.']);
        exit;
    }
    if (!livekit_recording_enabled_for_professional($mysqli, (int) ($appointment['professional_id'] ?? 0))) {
        echo json_encode(['success' => false, 'error' => 'Este profesional no tiene permitida la grabación de sesiones online.']);
        exit;
    }

    $settings = cabinet_get_effective_professional_settings($mysqli, (int) ($appointment['professional_id'] ?? 0));
    $recording_mode = in_array($settings['livekit_recording_mode'] ?? 'audio', ['audio', 'audio_video'], true)
        ? $settings['livekit_recording_mode']
        : 'audio';
    $room_name = livekit_room_name($tenant_id, $appointment_id);

    if (!livekit_recording_storage_configured()) {
        $stmt = $mysqli->prepare("
            INSERT INTO appointment_recordings
                (tenant_id, appointment_id, patient_id, professional_id, room_name, recording_mode, status, created_by)
            VALUES (?, ?, ?, ?, ?, ?, 'blocked', ?)
        ");
        if ($stmt) {
            $patient_id = (int) ($appointment['user_id'] ?? 0);
            $professional_id = (int) ($appointment['professional_id'] ?? 0);
            $created_by = (int) ($_SESSION['user_id'] ?? 0);
            $stmt->bind_param("iiiissi", $tenant_id, $appointment_id, $patient_id, $professional_id, $room_name, $recording_mode, $created_by);
            $stmt->execute();
        }
        $message = 'La grabación requiere configurar LiveKit Egress y el almacenamiento de las grabaciones.';
        app_log($mysqli, [
            'action' => 'livekit_recording_blocked',
            'target_type' => 'appointment',
            'target_id' => $appointment_id,
            'channel' => 'livekit',
            'status' => 'error',
            'title' => 'Grabación no iniciada',
            'message' => $message,
            'metadata' => [
                'room' => $room_name,
                'mode' => $recording_mode,
                'patient_id' => (int) ($appointment['user_id'] ?? 0),
                'professional_id' => (int) ($appointment['professional_id'] ?? 0)
            ]
        ]);
        echo json_encode(['success' => false, 'error' => $message]);
        exit;
    }

    echo json_encode([
        'success' => false,
        'error' => 'La grabación LiveKit Egress está preparada en configuración, pero todavía falta conectar la llamada real al servicio de grabación.'
    ]);
} elseif ($action === 'download_patient_document') {
    $patient_id = (int) ($_GET['patient_id'] ?? 0);
    if (!admin_can_access_patient($mysqli, $patient_id)) {
        http_response_code(403);
        echo 'No autorizado';
        exit;
    }
    $stmt = $mysqli->prepare("SELECT document_path, document_name FROM patient_profiles WHERE tenant_id = ? AND user_id = ? LIMIT 1");
    $stmt->bind_param("ii", $tenant_id, $patient_id);
    $stmt->execute();
    $document = $stmt->get_result()->fetch_assoc();
    $path = $document['document_path'] ?? '';
    $full_path = $path ? stored_upload_full_path($path) : '';
    if (!$document || !$path || !is_file($full_path)) {
        http_response_code(404);
        echo 'Archivo no encontrado';
        exit;
    }
    app_log_sensitive_access($mysqli, [
        'action' => 'patient_document_downloaded',
        'patient_id' => $patient_id,
        'resource_type' => 'profile_document',
        'title' => 'Documento sensible descargado'
    ]);
    header_remove('Content-Type');
    header('Content-Type: application/octet-stream');
    header('Content-Disposition: attachment; filename="' . addslashes($document['document_name'] ?: basename($full_path)) . '"');
    header('Content-Length: ' . filesize($full_path));
    readfile($full_path);
    exit;
} elseif ($action === 'download_evolution_file') {
    $file_id = (int) ($_GET['id'] ?? 0);
    $stmt = $mysqli->prepare("
        SELECT f.id, f.patient_id, f.original_name, f.file_path, f.mime_type, f.file_size
        FROM patient_evolution_files f
        WHERE f.tenant_id = ?
          AND f.id = ?
        LIMIT 1
    ");
    $stmt->bind_param("ii", $tenant_id, $file_id);
    $stmt->execute();
    $file = $stmt->get_result()->fetch_assoc();
    if (!$file || !admin_can_access_patient($mysqli, (int) $file['patient_id'])) {
        http_response_code(403);
        echo 'No autorizado';
        exit;
    }
    $full_path = stored_upload_full_path($file['file_path']);
    if (!is_file($full_path)) {
        http_response_code(404);
        echo 'Archivo no encontrado';
        exit;
    }
    app_log_sensitive_access($mysqli, [
        'action' => 'patient_evolution_file_downloaded',
        'patient_id' => (int) $file['patient_id'],
        'resource_type' => 'evolution_file',
        'resource_id' => $file_id,
        'title' => 'Adjunto de evolución descargado'
    ]);
    header_remove('Content-Type');
    header('Content-Type: ' . ($file['mime_type'] ?: 'application/octet-stream'));
    header('Content-Disposition: attachment; filename="' . addslashes($file['original_name'] ?: basename($full_path)) . '"');
    header('Content-Length: ' . filesize($full_path));
    readfile($full_path);
    exit;
} elseif ($action === 'delete_patient_evolution_note') {
    $note_id = (int) ($_POST['note_id'] ?? 0);
    $stmt = $mysqli->prepare("SELECT id, patient_id, title FROM patient_evolution_notes WHERE tenant_id = ? AND id = ? LIMIT 1");
    $stmt->bind_param("ii", $tenant_id, $note_id);
    $stmt->execute();
    $note = $stmt->get_result()->fetch_assoc();
    if (!$note || !admin_can_access_patient($mysqli, (int) $note['patient_id'])) {
        echo json_encode(['success' => false, 'error' => 'No autorizado para eliminar esta nota.']);
        exit;
    }

    $stmt = $mysqli->prepare("SELECT id, file_path FROM patient_evolution_files WHERE tenant_id = ? AND evolution_note_id = ?");
    $stmt->bind_param("ii", $tenant_id, $note_id);
    $stmt->execute();
    $files_res = $stmt->get_result();
    $file_paths = [];
    while ($file = $files_res->fetch_assoc()) {
        $file_paths[] = $file['file_path'] ?? '';
    }

    $mysqli->begin_transaction();
    try {
        $stmt = $mysqli->prepare("DELETE FROM patient_evolution_files WHERE tenant_id = ? AND evolution_note_id = ?");
        $stmt->bind_param("ii", $tenant_id, $note_id);
        $stmt->execute();

        $stmt = $mysqli->prepare("DELETE FROM patient_evolution_notes WHERE tenant_id = ? AND id = ?");
        $stmt->bind_param("ii", $tenant_id, $note_id);
        $stmt->execute();

        $mysqli->commit();
        foreach ($file_paths as $path) {
            $full_path = stored_upload_full_path($path);
            if ($full_path && is_file($full_path)) {
                praxis_storage_delete_path($full_path);
            }
        }
        app_log($mysqli, [
            'action' => 'patient_evolution_deleted',
            'status' => 'ok',
            'target_type' => 'patient',
            'target_id' => (int) $note['patient_id'],
            'title' => 'Registro de evolucion eliminado',
            'message' => $note['title'] ?? '',
            'metadata' => [
                'patient_id' => (int) $note['patient_id'],
                'note_id' => $note_id
            ]
        ]);
        echo json_encode(['success' => true, 'message' => 'Nota eliminada correctamente.']);
    } catch (\Exception $e) {
        $mysqli->rollback();
        echo json_encode(['success' => false, 'error' => 'No se pudo eliminar la nota.']);
    }
} elseif (in_array($action, ['save_patient_ai_document', 'export_patient_ai_pdf'], true)) {
    $patient_id = (int) ($_POST['patient_id'] ?? 0);
    $appointment_id = (int) ($_POST['appointment_id'] ?? 0);
    $report_type = trim((string) ($_POST['report_type'] ?? 'clinical_report'));
    $content = trim((string) ($_POST['content'] ?? ''));
    $session_token = (string) ($_SESSION['ai_csrf_token'] ?? '');
    $request_token = (string) ($_POST['csrf_token'] ?? '');
    if ($session_token === '' || $request_token === '' || !hash_equals($session_token, $request_token)) {
        echo json_encode(['success' => false, 'error' => 'La sesión ha caducado. Recarga la página e inténtalo de nuevo.']);
        exit;
    }
    if (plan_config_normalize_key(dashboard_config_plan_key_from_db($mysqli), '') !== 'summum') {
        echo json_encode(['success' => false, 'error' => 'Esta función está disponible en el plan Summum.']);
        exit;
    }
    if (!$is_superadmin && empty($member_permissions['private_patient_data'])) {
        echo json_encode(['success' => false, 'error' => 'No tienes permiso para utilizar la información privada de este paciente.']);
        exit;
    }
    if (!$is_superadmin && empty($member_permissions['ai_tools'])) {
        echo json_encode(['success' => false, 'error' => 'No tienes permiso para utilizar las opciones de IA.']);
        exit;
    }
    if ($patient_id <= 0 || !admin_can_access_patient($mysqli, $patient_id) || $content === '' || mb_strlen($content, 'UTF-8') > 60000) {
        echo json_encode(['success' => false, 'error' => 'No se pudo preparar el documento.']);
        exit;
    }
    if ($appointment_id > 0) {
        $stmt = $mysqli->prepare("SELECT id FROM appointments WHERE tenant_id = ? AND id = ? AND user_id = ? LIMIT 1");
        $stmt->bind_param('iii', $tenant_id, $appointment_id, $patient_id);
        $stmt->execute();
        if (!$stmt->get_result()->fetch_assoc()) {
            echo json_encode(['success' => false, 'error' => 'La cita indicada no pertenece a este paciente.']);
            exit;
        }
    }
    $stmt = $mysqli->prepare("SELECT name FROM users WHERE tenant_id = ? AND id = ? AND role = 'patient' LIMIT 1");
    $stmt->bind_param('ii', $tenant_id, $patient_id);
    $stmt->execute();
    $patient_name = (string) (($stmt->get_result()->fetch_assoc()['name'] ?? ''));
    $base_title = praxis_ai_document_title($report_type);
    $title = $base_title . ' · ' . date('d/m/Y');
    $html = praxis_ai_document_html($title, $content, $patient_name);

    if ($action === 'export_patient_ai_pdf') {
        try {
            pdf_output_html($html, $base_title . '-' . date('Y-m-d') . '.pdf', [
                'title' => $title,
                'download' => true
            ]);
        } catch (Throwable $e) {
            http_response_code(500);
            header_remove('Content-Type');
            header('Content-Type: text/plain; charset=UTF-8');
            echo 'No se pudo generar el PDF.';
        }
        exit;
    }

    try {
        $upload_dir = app_tenant_protected_upload_dir('documents');
        if (!app_ensure_dir($upload_dir)) throw new RuntimeException('No se pudo preparar la carpeta de documentos.');
        $stored_name = 'ai_document_' . $patient_id . '_' . bin2hex(random_bytes(12)) . '.pdf';
        $destination = $upload_dir . '/' . $stored_name;
        $pdf = pdf_render_html($html, ['title' => $title]);
        $relative_path = app_tenant_protected_upload_relative_path('documents', $stored_name);
        if (praxis_storage_write_contents($relative_path, $destination, $pdf, 'application/pdf') === false) throw new RuntimeException('No se pudo guardar el PDF.');
        $file_name = pdf_safe_filename($base_title . '-' . date('Y-m-d'));
        $file_size = strlen($pdf);
        $professional_id = current_professional_id_for_user($mysqli, (int) ($_SESSION['user_id'] ?? 0));
        $document_type = 'file';
        $description = 'Documento preparado con el asistente de IA y revisado por el profesional.';
        $document_date = date('Y-m-d');
        $mime_type = 'application/pdf';
        $status = 'completed';
        $created_by = (int) ($_SESSION['user_id'] ?? 0);
        $stmt = $mysqli->prepare("INSERT INTO patient_documents
            (tenant_id, patient_id, appointment_id, professional_id, document_type, title, description, document_date,
             file_path, original_file_name, file_size, mime_type, visible_to_patient, status, created_by)
            VALUES (?, ?, NULLIF(?, 0), NULLIF(?, 0), ?, ?, ?, ?, ?, ?, ?, ?, 0, ?, ?)");
        $stmt->bind_param('iiiissssssissi', $tenant_id, $patient_id, $appointment_id, $professional_id, $document_type, $title, $description, $document_date, $relative_path, $file_name, $file_size, $mime_type, $status, $created_by);
        $stmt->execute();
        $document_id = (int) $mysqli->insert_id;
        app_log($mysqli, [
            'action' => 'patient_ai_document_saved', 'status' => 'ok', 'target_type' => 'patient', 'target_id' => $patient_id,
            'title' => 'Documento IA guardado', 'message' => $base_title,
            'metadata' => ['patient_id' => $patient_id, 'appointment_id' => $appointment_id, 'document_id' => $document_id, 'content_type' => $report_type]
        ]);
        echo json_encode(['success' => true, 'message' => $appointment_id > 0 ? 'Documento guardado y asociado a la cita.' : 'Documento guardado en la ficha del paciente.', 'document_id' => $document_id], JSON_UNESCAPED_UNICODE);
    } catch (Throwable $e) {
        error_log('Praxis AI document save error: ' . $e->getMessage());
        echo json_encode(['success' => false, 'error' => 'No se pudo guardar el documento.']);
    }
} elseif ($action === 'generate_patient_ai_content') {
    $patient_id = (int) ($_POST['patient_id'] ?? 0);
    $report_type = trim((string) ($_POST['report_type'] ?? 'clinical_report'));
    $instructions = trim((string) ($_POST['instructions'] ?? ''));
    $allowed_types = ['clinical_report', 'evolution', 'follow_up_report', 'evolution_summary', 'next_session', 'tasks_summary', 'questionnaires_summary'];
    $session_token = (string) ($_SESSION['ai_csrf_token'] ?? '');
    $request_token = (string) ($_POST['csrf_token'] ?? '');

    if ($session_token === '' || $request_token === '' || !hash_equals($session_token, $request_token)) {
        echo json_encode(['success' => false, 'error' => 'La sesión ha caducado. Recarga la página e inténtalo de nuevo.']);
        exit;
    }
    if (plan_config_normalize_key(dashboard_config_plan_key_from_db($mysqli), '') !== 'summum') {
        echo json_encode(['success' => false, 'error' => 'Las herramientas de IA están disponibles en el plan Summum.']);
        exit;
    }
    if (!$is_superadmin && empty($member_permissions['private_patient_data'])) {
        echo json_encode(['success' => false, 'error' => 'No tienes permiso para utilizar la informaci&oacute;n privada de este paciente.']);
        exit;
    }
    if (!$is_superadmin && empty($member_permissions['ai_tools'])) {
        echo json_encode(['success' => false, 'error' => 'No tienes permiso para utilizar las opciones de IA.']);
        exit;
    }
    if (!in_array($report_type, $allowed_types, true)) {
        echo json_encode(['success' => false, 'error' => 'El tipo de contenido solicitado no es v&aacute;lido.']);
        exit;
    }
    if ($report_type === 'clinical_report' && !$is_superadmin && empty($member_permissions['reports'])) {
        echo json_encode(['success' => false, 'error' => 'No tienes permiso para generar informes.']);
        exit;
    }
    if ($patient_id <= 0 || !admin_can_access_patient($mysqli, $patient_id)) {
        echo json_encode(['success' => false, 'error' => 'No autorizado para acceder a este paciente.']);
        exit;
    }

    try {
        $prepared = praxis_ai_report_context($mysqli, $tenant_id, $patient_id, $report_type);
        if (!praxis_ai_report_type_sufficient($prepared, $report_type)) {
        echo json_encode(['success' => false, 'error' => 'Todavía no hay suficiente información para generar este contenido.']);
            exit;
        }
        $generated = praxis_ai_generate_report(
            (string) $prepared['context'],
            $report_type,
            mb_substr($instructions, 0, 1200, 'UTF-8'),
            $prepared['_redaction_values'] ?? []
        );
        $text = str_replace('{NOMBRE_PACIENTE}', (string) ($prepared['_patient_name'] ?? 'El paciente'), (string) $generated['text']);
        app_log($mysqli, [
            'action' => 'patient_ai_content_generated',
            'status' => 'ok',
            'target_type' => 'patient',
            'target_id' => $patient_id,
            'title' => 'Borrador generado con IA',
            'message' => $report_type,
            'metadata' => [
                'patient_id' => $patient_id,
                'content_type' => $report_type,
                'model' => $generated['model'] ?? '',
                'usage' => $generated['usage'] ?? [],
                'counts' => $prepared['counts'] ?? []
            ]
        ]);
        echo json_encode(['success' => true, 'text' => $text, 'counts' => $prepared['counts'] ?? []], JSON_UNESCAPED_UNICODE);
    } catch (Throwable $e) {
        error_log('Praxis AI generation error: ' . $e->getMessage());
        echo json_encode(['success' => false, 'error' => 'No se pudo generar el borrador en este momento. Inténtalo de nuevo.']);
    }
} elseif ($action === 'system_status') {
    $services = [];
    $add = static function ($key, $title, $icon, $state, $label, $description, $details = [], $metric = []) use (&$services) {
        $services[] = compact('key', 'title', 'icon', 'state', 'label', 'description', 'details', 'metric');
    };
    $started = microtime(true);
    $db_ok = @$mysqli->ping();
    $add('database', 'Base de datos', 'bi-database-check', $db_ok ? 'ok' : 'error', $db_ok ? 'Conexión disponible' : 'Sin conexión', $db_ok ? 'Praxis puede consultar y guardar información.' : 'No se ha podido comprobar la conexión con la base de datos.', [['label' => 'Tiempo de respuesta', 'value' => ((int) round((microtime(true) - $started) * 1000)) . ' ms']]);

    $email = get_email_settings($mysqli);
    $email_provider = strtolower((string) ($email['email_provider'] ?? 'platform'));
    $email_labels = ['platform' => 'Plataforma Praxis', 'google' => 'Google Workspace / Gmail', 'smtp' => 'Servidor SMTP'];
    $email_ok = app_email_is_configured($mysqli);
    $add('email', 'Correo electrónico', 'bi-envelope-check', $email_ok ? 'ok' : 'warning', $email_ok ? 'Configurado' : 'Requiere configuración', $email_ok ? 'El canal de correo está listo para enviar comunicaciones.' : 'Faltan datos necesarios para poder enviar correos.', [['label' => 'Proveedor', 'value' => $email_labels[$email_provider] ?? ucfirst($email_provider)]]);

    $sms = sms_get_settings($mysqli); $sms_provider = (string) ($sms['sms_provider'] ?? 'none');
    $sms_ok = sms_is_configured($mysqli); $sms_disabled = $sms_provider === 'none';
    $add('sms', 'SMS', 'bi-chat-dots', $sms_disabled ? 'disabled' : ($sms_ok ? 'ok' : 'warning'), $sms_disabled ? 'No configurado' : ($sms_ok ? 'Configurado' : 'Configuración incompleta'), $sms_disabled ? 'El envío de SMS no está activado.' : ($sms_ok ? 'El proveedor de SMS está preparado para enviar mensajes.' : 'Revisa las credenciales o el remitente del servicio SMS.'), [['label' => 'Proveedor', 'value' => sms_provider_label($sms_provider)]]);

    $storage = tenant_storage_status($mysqli, (int) $tenant_id); $percent = (float) ($storage['percent'] ?? 0); $limit = (int) ($storage['limit_bytes'] ?? 0);
    $storage_state = $limit <= 0 ? 'ok' : ($percent >= 100 ? 'error' : ($percent >= 85 ? 'warning' : 'ok'));
    $add('storage', 'Almacenamiento', 'bi-cloud-check', $storage_state, $limit <= 0 ? 'Sin límite configurado' : ($percent . '% utilizado'), $storage_state === 'error' ? 'No queda espacio disponible para nuevos archivos.' : ($storage_state === 'warning' ? 'El espacio disponible empieza a ser reducido.' : 'El almacenamiento está disponible.'), [['label' => 'Usado', 'value_bytes' => (int) ($storage['used_bytes'] ?? 0)], ['label' => 'Disponible', 'value_bytes' => (int) ($storage['remaining_bytes'] ?? 0)]], ['percent' => $percent, 'used_bytes' => (int) ($storage['used_bytes'] ?? 0), 'limit_bytes' => $limit]);

    $billing = simplygest_cloud_billing_settings($mysqli, (int) $tenant_id); $provider = (string) ($billing['provider'] ?? 'none');
    if ($provider === 'simplygest_cloud') {
        if (empty($billing['has_api_key'])) {
            $add('billing', 'Facturación y VeriFactu', 'bi-receipt-cutoff', 'error', 'Falta la API key', 'La facturación está vinculada a SimplyGest Cloud, pero no hay una API key configurada.', [['label' => 'Proveedor', 'value' => 'SimplyGest Cloud']]);
        } else {
            try {
                $cloud_started = microtime(true); $client = new SimplyGestCloudClient(simplygest_cloud_decrypt((string) $billing['api_key_encrypted']));
                $account = $client->account(); $client->validateInvoiceAccess();
                $add('billing', 'Facturación y VeriFactu', 'bi-receipt-cutoff', 'ok', 'Conectado con SimplyGest Cloud', 'La API key es válida y permite consultar la facturación.', [['label' => 'Empresa', 'value' => (string) ($account['name'] ?? 'SimplyGest Cloud')], ['label' => 'Tiempo de respuesta', 'value' => ((int) round((microtime(true) - $cloud_started) * 1000)) . ' ms']]);
            } catch (Throwable $e) {
                error_log('System status SimplyGest Cloud: ' . $e->getMessage());
                $add('billing', 'Facturación y VeriFactu', 'bi-receipt-cutoff', 'error', 'No se puede conectar con Cloud', 'La API key no es válida, no tiene permisos de facturación o SimplyGest Cloud no responde.', [['label' => 'Acción recomendada', 'value' => 'Revisa la API key en Facturación']]);
            }
        }
    } elseif ($provider === 'praxis') {
        $vf = $mysqli->query("SELECT verifactu_enabled, verifactu_environment FROM payment_settings WHERE tenant_id = " . (int) $tenant_id . " LIMIT 1"); $row = $vf ? ($vf->fetch_assoc() ?: []) : [];
        $enabled = (int) ($row['verifactu_enabled'] ?? 0) === 1;
        $add('billing', 'Facturación y VeriFactu', 'bi-receipt-cutoff', $enabled ? 'ok' : 'warning', $enabled ? 'Gestionado por Praxis' : 'VeriFactu no activado', $enabled ? 'Praxis gestiona la facturación y VeriFactu.' : 'La facturación se realiza en Praxis, pero VeriFactu no está activado.', [['label' => 'Entorno', 'value' => $enabled ? ((int) ($row['verifactu_environment'] ?? 0) === 1 ? 'Producción' : 'Pruebas') : 'No aplica']]);
