} elseif ($action === 'save_drawing_patient_document') {
    ensure_plan_action_feature($mysqli, 'documents.drawingBoard', 'La pizarra online de dibujo solo esta disponible en el plan Summum.');
    $patient_id = (int) ($_GET['patient_id'] ?? 0);
