    if ($appointment_was_posted && $appointment_id > 0) {
        $appointment_manage_result = admin_can_manage_appointment_payment($mysqli, $appointment_id);
        if (!$appointment_manage_result[0] || (int) ($appointment_manage_result[1]['user_id'] ?? 0) !== $patient_id) {
            echo json_encode(['success' => false, 'error' => 'No autorizado para vincular esa cita.']);
            exit;
        }
        $appointment_id_db = $appointment_id;
        if (!empty($appointment_manage_result[1]['professional_id'])) {
            $professional_id = (int) $appointment_manage_result[1]['professional_id'];
        }
    }

    $creating_work_plan_task = $task_id <= 0;
    if ($task_id > 0) {
        $stmt = $mysqli->prepare("SELECT patient_id, appointment_id, professional_id, status, document_id FROM patient_work_plan_tasks WHERE tenant_id = ? AND id = ? LIMIT 1");
        $stmt->bind_param("ii", $tenant_id, $task_id);
        $stmt->execute();
        $existing = $stmt->get_result()->fetch_assoc();
        if (!$existing || (int) $existing['patient_id'] !== $patient_id) {
            echo json_encode(['success' => false, 'error' => 'No se encontro la tarea.']);
            exit;
        }
        if (!$task_status_enabled) {
            $status = ($existing['status'] ?? '') === 'completed' ? 'completed' : 'pending';
        }
        $existing_professional_id = (int) ($existing['professional_id'] ?? 0);
        if ($professional_id <= 0) {
            $professional_id = $existing_professional_id > 0 ? $existing_professional_id : null;
        }
        if (!$appointment_was_posted) {
            $appointment_id_db = !empty($existing['appointment_id']) ? (int) $existing['appointment_id'] : null;
        }
        if ($status === 'completed' && ($existing['status'] ?? '') === 'completed') {
            $completed_at = null;
            $completed_by = null;
            $stmt = $mysqli->prepare("
                UPDATE patient_work_plan_tasks
                SET appointment_id = ?, title = ?, description = ?, priority = ?, visible_to_patient = ?, status = ?, requires_docx = ?, requires_drawing = ?, requires_file = ?
                WHERE tenant_id = ? AND id = ? AND patient_id = ?
            ");
            $stmt->bind_param("issiisiiiiii", $appointment_id_db, $title, $description, $priority, $visible_to_patient, $status, $requires_docx, $requires_drawing, $requires_file, $tenant_id, $task_id, $patient_id);
        } else {
            $stmt = $mysqli->prepare("
                UPDATE patient_work_plan_tasks
                SET appointment_id = ?, professional_id = ?, title = ?, description = ?, priority = ?, visible_to_patient = ?, status = ?,
                    completed_at = ?, completed_by = ?, requires_docx = ?, requires_drawing = ?, requires_file = ?
                WHERE tenant_id = ? AND id = ? AND patient_id = ?
            ");
            $stmt->bind_param("iissiissiiiiiii", $appointment_id_db, $professional_id, $title, $description, $priority, $visible_to_patient, $status, $completed_at, $completed_by, $requires_docx, $requires_drawing, $requires_file, $tenant_id, $task_id, $patient_id);
        }
        $stmt->execute();
    } else {
        if ($professional_id <= 0) {
            $professional_id = null;
        }
        $stmt = $mysqli->prepare("
            INSERT INTO patient_work_plan_tasks (tenant_id, patient_id, appointment_id, professional_id, title, description, status, priority, visible_to_patient, created_by, completed_at, completed_by, requires_docx, requires_drawing, requires_file)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ");
        $stmt->bind_param("iiiisssiiisiiii", $tenant_id, $patient_id, $appointment_id_db, $professional_id, $title, $description, $status, $priority, $visible_to_patient, $session_user_id, $completed_at, $completed_by, $requires_docx, $requires_drawing, $requires_file);
        $stmt->execute();
        $task_id = $mysqli->insert_id;
    }
    app_log($mysqli, [
        'action' => $creating_work_plan_task ? 'patient_task_created' : 'patient_task_updated',
        'status' => 'ok',
        'target_type' => 'patient',
        'target_id' => $patient_id,
        'title' => $creating_work_plan_task ? 'Tarea creada' : 'Tarea actualizada',
        'message' => $title,
        'metadata' => [
            'patient_id' => $patient_id,
            'task_id' => $task_id,
            'appointment_id' => $appointment_id_db ? (int) $appointment_id_db : 0,
            'professional_id' => $professional_id ? (int) $professional_id : 0,
            'status' => $status,
            'visible_to_patient' => $visible_to_patient
        ]
    ]);
    echo json_encode(['success' => true, 'message' => 'Plan de trabajo guardado correctamente.', 'task_id' => $task_id]);
} elseif ($action === 'add_fitness_exercise_to_work_plan') {
