        'status' => 'ok',
        'target_type' => 'patient',
        'target_id' => $patient_id,
        'title' => 'Ejercicio anadido al plan',
        'message' => $title,
        'metadata' => [
            'patient_id' => $patient_id,
            'task_id' => $task_id,
            'appointment_id' => $appointment_id_db ? (int) $appointment_id_db : 0,
            'professional_id' => $professional_id ? (int) $professional_id : 0,
