            );
            if (!$customFieldsOk) throw new \RuntimeException($customFieldsError);
        }
        $mysqli->commit();
        if (!$creating_patient) {
            $current_audit_data = array_merge([
                'name' => $name,
                'email' => $email,
                'phone' => $phone,
                'professional_id' => $profile_professional_id,
