    }
} elseif ($action === 'transfer_patient_professional') {
    if (!$is_superadmin) {
        echo json_encode(['success' => false, 'error' => 'Solo el superadmin puede realizar traspasos.']);
        exit;
    }
    ensure_cabinet_schema($mysqli);
    $settings_res = $mysqli->query("SELECT allow_patient_transfer FROM payment_settings WHERE tenant_id = $tenant_id");
    $settings = $settings_res ? $settings_res->fetch_assoc() : ['allow_patient_transfer' => 0];

    $patient_id = (int) ($_POST['patient_id'] ?? 0);
    $target_professional_id = (int) ($_POST['professional_id'] ?? 0);
    if ($patient_id <= 0 || $target_professional_id <= 0) {
        echo json_encode(['success' => false, 'error' => 'Selecciona paciente y profesional.']);
        exit;
    }
    $stmt = $mysqli->prepare("SELECT id FROM users WHERE tenant_id = ? AND id = ? AND role = 'patient' LIMIT 1");
    $stmt->bind_param("ii", $tenant_id, $patient_id);
    $stmt->execute();
    if (!$stmt->get_result()->fetch_assoc()) {
        echo json_encode(['success' => false, 'error' => 'Paciente no encontrado.']);
        exit;
    }
    $stmt = $mysqli->prepare("SELECT id, display_name FROM professionals WHERE tenant_id = ? AND id = ? AND is_active = 1 LIMIT 1");
    $stmt->bind_param("ii", $tenant_id, $target_professional_id);
    $stmt->execute();
    $target_professional = $stmt->get_result()->fetch_assoc();
    if (!$target_professional) {
        echo json_encode(['success' => false, 'error' => 'Profesional no valido o inactivo.']);
        exit;
    }
    $current_professional_id = cabinet_patient_primary_professional_id($mysqli, $patient_id);
    if ($current_professional_id > 0 && (int) ($settings['allow_patient_transfer'] ?? 0) !== 1) {
        echo json_encode(['success' => false, 'error' => 'El traspaso no esta activado en configuracion.']);
        exit;
    }
    if ($current_professional_id === $target_professional_id) {
        echo json_encode(['success' => false, 'error' => 'El paciente ya esta asignado a ese profesional.']);
        exit;
    }

    $mysqli->begin_transaction();
    try {
        $stmt = $mysqli->prepare("UPDATE patient_professionals SET is_primary = 0 WHERE tenant_id = ? AND patient_id = ?");
        $stmt->bind_param("ii", $tenant_id, $patient_id);
        $stmt->execute();

        $notes = $current_professional_id > 0 ? 'Traspaso manual desde ficha' : 'Asignacion manual desde ficha';
        $stmt = $mysqli->prepare("
            INSERT INTO patient_professionals (tenant_id, patient_id, professional_id, is_primary, assigned_at, transferred_at, notes)
            VALUES (?, ?, ?, 1, NOW(), NOW(), ?)
            ON DUPLICATE KEY UPDATE is_primary = 1, transferred_at = NOW(), notes = VALUES(notes)
        ");
        $stmt->bind_param("iiis", $tenant_id, $patient_id, $target_professional_id, $notes);
        $stmt->execute();

        $stmt = $mysqli->prepare("
            INSERT INTO patient_profiles (tenant_id, user_id, professional_id, created_by_admin)
            VALUES (?, ?, ?, 1)
            ON DUPLICATE KEY UPDATE professional_id = VALUES(professional_id)
        ");
        $stmt->bind_param("iii", $tenant_id, $patient_id, $target_professional_id);
        $stmt->execute();

        $stmt = $mysqli->prepare("
            UPDATE appointments
            SET professional_id = ?
            WHERE tenant_id = ?
              AND user_id = ?
              AND status = 'booked'
              AND CONCAT(appointment_date, ' ', appointment_time) >= NOW()
        ");
        $stmt->bind_param("iii", $target_professional_id, $tenant_id, $patient_id);
        $stmt->execute();
        $moved_appointments = $stmt->affected_rows;

        $mysqli->commit();
        app_log($mysqli, [
            'action' => 'patient_professional_transferred',
            'status' => 'ok',
            'target_type' => 'patient',
            'target_id' => $patient_id,
            'title' => $current_professional_id > 0 ? 'Paciente traspasado' : 'Profesional asignado',
            'message' => ($target_professional['display_name'] ?? ''),
            'metadata' => [
                'patient_id' => $patient_id,
                'previous_professional_id' => (int) $current_professional_id,
                'new_professional_id' => (int) $target_professional_id,
                'moved_appointments' => (int) $moved_appointments
            ]
        ]);
        echo json_encode([
            'success' => true,
            'message' => $current_professional_id > 0 ? 'Paciente traspasado correctamente.' : 'Profesional asignado correctamente.',
            'professional_id' => $target_professional_id,
            'professional_name' => $target_professional['display_name'] ?? '',
            'moved_appointments' => $moved_appointments
        ]);
    } catch (\Exception $e) {
        $mysqli->rollback();
        echo json_encode(['success' => false, 'error' => 'No se pudo completar el traspaso.']);
    }
} elseif ($action === 'send_patient_invite') {
    if (!app_feature_enabled_from_db($mysqli, 'patientPortal.enabled', false) || !app_feature_enabled_from_db($mysqli, 'patientPortal.invitations', false)) {
        echo json_encode(['success' => false, 'error' => 'Las invitaciones del portal no estan disponibles en este plan.']);
        exit;
    }
    try {
    $patient_id = (int) ($_POST['patient_id'] ?? 0);
    $stmt = $mysqli->prepare("SELECT id, name, email, password_hash FROM users WHERE tenant_id = ? AND id = ? AND role = 'patient'");
    $stmt->bind_param("ii", $tenant_id, $patient_id);
    $stmt->execute();
    $patient = $stmt->get_result()->fetch_assoc();
    if (!$patient) {
        echo json_encode(['success' => false, 'error' => 'Paciente no encontrado.']);
        exit;
    }
    if (patient_has_portal_access($patient)) {
        echo json_encode(['success' => false, 'error' => 'Este paciente ya tiene acceso web.']);
        exit;
    }
    if (empty($patient['email']) || !filter_var($patient['email'], FILTER_VALIDATE_EMAIL)) {
        echo json_encode(['success' => false, 'error' => 'El paciente necesita un email válido para enviar la invitación.']);
        exit;
    }

    $token = bin2hex(random_bytes(32));
    $stmt = $mysqli->prepare("INSERT INTO invitations (tenant_id, token, user_id) VALUES (?, ?, ?)");
    $stmt->bind_param("isi", $tenant_id, $token, $patient_id);
    $stmt->execute();
    $registration_link = app_public_base_url() . 'register.php?token=' . urlencode($token);
    $link = urlme_shorten_url($registration_link, 'Invitación registro SimplyGest Praxis') ?: $registration_link;

    $sent = send_app_email(
        $patient['email'],
        'Invitación para crear tu cuenta',
        '<p>Hola ' . htmlspecialchars($patient['name']) . ',</p>' .
        '<p>Te enviamos la invitaci&oacute;n para crear tu cuenta y poder acceder a la web para gestionar tus citas.</p>' .
        '<p><a href="' . htmlspecialchars($link) . '">Crear mi cuenta</a></p>' .
        '<p>Si el boton no funciona, copia y pega este enlace en tu navegador:<br>' . htmlspecialchars($link) . '</p>',
        null,
        $mysqli
    );
    $email_error = $sent ? '' : (function_exists('get_app_email_last_error') ? get_app_email_last_error() : '');
    if (!$sent && $email_error !== '') {
        error_log('Invitación al Portal para paciente ' . $patient_id . ': ' . $email_error);
    }

    app_log($mysqli, [
        'action' => $sent ? 'patient_portal_invite_sent' : 'patient_portal_invite_failed',
        'status' => $sent ? 'ok' : 'error',
        'channel' => 'email',
        'target_type' => 'patient',
        'target_id' => $patient_id,
        'title' => $sent ? 'Invitación al Portal enviada' : 'No se pudo enviar la invitación al Portal',
        'message' => $patient['email'] ?? '',
        'metadata' => [
            'patient_id' => $patient_id,
            'email' => $patient['email'] ?? '',
            'reason' => $sent ? '' : ($email_error ?: 'Fallo al enviar el email de invitación.')
        ]
    ]);

    echo json_encode($sent
        ? ['success' => true, 'message' => 'Invitación enviada correctamente.', 'link' => $link]
        : ['success' => false, 'error' => 'No se pudo enviar el email de invitación.' . ($email_error !== '' ? ' Motivo: ' . $email_error : '')]);
    } catch (Throwable $exception) {
        error_log('Error preparando la invitación al Portal: ' . $exception->getMessage());
        echo json_encode(['success' => false, 'error' => 'No se pudo preparar la invitación. Motivo: ' . $exception->getMessage()]);
    }
} elseif ($action === 'send_invite_email') {
    if (!app_feature_enabled_from_db($mysqli, 'patientPortal.enabled', false) || !app_feature_enabled_from_db($mysqli, 'patientPortal.invitations', false)) {
        echo json_encode(['success' => false, 'error' => 'Las invitaciones del Portal no están disponibles en este plan.']);
        exit;
    }
    try {
    $email = trim($_POST['email'] ?? '');
    $posted_link = trim($_POST['link'] ?? '');
    $posted_token = trim($_POST['token'] ?? '');
    $parts = parse_url($posted_link);
    parse_str($parts['query'] ?? '', $query);
    $token = $posted_token ?: ($query['token'] ?? '');

    if (!$email || !filter_var($email, FILTER_VALIDATE_EMAIL)) {
        echo json_encode(['success' => false, 'error' => 'Indica un email válido.']);
        exit;
    }
    if (!preg_match('/^[a-f0-9]{64}$/', $token)) {
        echo json_encode(['success' => false, 'error' => 'El enlace de invitación no es válido.']);
        exit;
    }

    $stmt = $mysqli->prepare("SELECT id, user_id FROM invitations WHERE tenant_id = ? AND token = ? AND used = 0");
    $stmt->bind_param("is", $tenant_id, $token);
    $stmt->execute();
    $invitation = $stmt->get_result()->fetch_assoc();
    if (!$invitation) {
        echo json_encode(['success' => false, 'error' => 'La invitación no existe o ya fue utilizada.']);
        exit;
    }

    $registration_link = app_public_base_url() . 'register.php?token=' . urlencode($token);
    $link = urlme_shorten_url($registration_link, 'Invitación registro SimplyGest Praxis') ?: $registration_link;
    $sent = send_app_email(
        $email,
        'Invitación para crear tu cuenta',
        '<p>Hola,</p>' .
        '<p>Te enviamos la invitaci&oacute;n para crear tu cuenta y poder acceder a la web para gestionar tus citas.</p>' .
        '<p><a href="' . htmlspecialchars($link) . '">Crear mi cuenta</a></p>' .
        '<p>Si el boton no funciona, copia y pega este enlace en tu navegador:<br>' . htmlspecialchars($link) . '</p>',
        null,
        $mysqli
    );
    $email_error = $sent ? '' : (function_exists('get_app_email_last_error') ? get_app_email_last_error() : '');

    app_log($mysqli, [
        'action' => $sent ? 'patient_portal_invite_sent' : 'patient_portal_invite_failed',
        'status' => $sent ? 'ok' : 'error',
        'channel' => 'email',
        'target_type' => 'patient',
        'target_id' => (int) ($invitation['user_id'] ?? 0),
        'title' => $sent ? 'Invitación al Portal enviada' : 'No se pudo enviar la invitación al Portal',
        'message' => $email,
        'metadata' => [
            'patient_id' => (int) ($invitation['user_id'] ?? 0),
            'email' => $email,
            'reason' => $sent ? '' : ($email_error ?: 'Fallo al enviar el email de invitación.')
        ]
    ]);

    echo json_encode($sent
        ? ['success' => true, 'message' => 'Invitación enviada correctamente.']
        : ['success' => false, 'error' => 'No se pudo enviar el email de invitación.' . ($email_error !== '' ? ' Motivo: ' . $email_error : '')]);
    } catch (Throwable $exception) {
        error_log('Error enviando una invitación generada: ' . $exception->getMessage());
        echo json_encode(['success' => false, 'error' => 'No se pudo enviar la invitación. Motivo: ' . $exception->getMessage()]);
    }
} elseif ($action === 'export_appointments') {
    $format = strtolower((string) ($_GET['format'] ?? 'xlsx'));
    $current_professional_id = current_professional_id_for_user($mysqli, (int) ($_SESSION['user_id'] ?? 0));
    $requested_professional_id = $is_superadmin ? max(0, (int) ($_GET['professional_id'] ?? 0)) : $current_professional_id;
    $where = "a.tenant_id = ?";
    $types = 'i';
    $params = [$tenant_id];
    if ($requested_professional_id > 0) {
        $where .= " AND a.professional_id = ?";
        $types .= 'i';
        $params[] = $requested_professional_id;
    } elseif (!$is_superadmin) {
        $where .= " AND 1 = 0";
    }
    $date_from = trim((string) ($_GET['date_from'] ?? ''));
    $date_to = trim((string) ($_GET['date_to'] ?? ''));
    if (preg_match('/^\d{4}-\d{2}-\d{2}$/', $date_from)) {
        $where .= " AND a.appointment_date >= ?";
        $types .= 's';
        $params[] = $date_from;
    }
    if (preg_match('/^\d{4}-\d{2}-\d{2}$/', $date_to)) {
        $where .= " AND a.appointment_date <= ?";
        $types .= 's';
        $params[] = $date_to;
    }
    $status = trim((string) ($_GET['status'] ?? ''));
    if (in_array($status, ['booked', 'completed', 'no_show', 'cancelled'], true)) {
        $where .= " AND a.status = ?";
        $types .= 's';
        $params[] = $status;
    }
    $can_phone = $is_superadmin || !empty($member_permissions['view_patient_phone']);
    $stmt = $mysqli->prepare("
        SELECT a.id, a.appointment_date, a.appointment_time,
               COALESCE(a.duration_minutes, aso.duration_minutes, 60) AS duration_minutes,
               a.status, a.patient_confirmed_at, a.consultation_type,
               s.name AS service, al.name AS location, p.display_name AS professional,
               u.name AS patient, u.email AS patient_email, " . ($can_phone ? "u.phone" : "''") . " AS patient_phone,
               a.payment_status, a.payment_method, a.paid_at, a.cancelled_at, a.created_at
        FROM appointments a
        JOIN users u ON u.id = a.user_id AND u.tenant_id = a.tenant_id
        LEFT JOIN appointment_service_options aso ON aso.id = a.service_option_id AND aso.tenant_id = a.tenant_id
        LEFT JOIN appointment_services s ON s.id = aso.service_id AND s.tenant_id = a.tenant_id
        LEFT JOIN appointment_locations al ON al.id = a.location_id AND al.tenant_id = a.tenant_id
        LEFT JOIN professionals p ON p.id = a.professional_id AND p.tenant_id = a.tenant_id
        WHERE $where
        ORDER BY a.appointment_date DESC, a.appointment_time DESC, a.id DESC
    ");
    bind_params_dynamic($stmt, $types, $params);
    $stmt->execute();
    $records = $stmt->get_result()->fetch_all(MYSQLI_ASSOC);
    if ($format === 'json') {
        export_output_json('citas-' . date('Y-m-d'), ['exported_at' => date(DATE_ATOM), 'appointments' => $records]);
    }
    $headers = $records ? array_keys($records[0]) : ['id', 'appointment_date', 'appointment_time'];
    $rows = array_map(function ($row) use ($headers) {
        return array_map(function ($key) use ($row) { return $row[$key] ?? ''; }, $headers);
    }, $records);
    export_output_xlsx('citas-' . date('Y-m-d'), $headers, $rows, 'Citas');
} elseif ($action === 'quick_appointments') {
    ensure_appointment_payment_columns($mysqli);
    ensure_appointment_services_tables($mysqli);
    ensure_cabinet_schema($mysqli);
    $branding = get_public_branding_settings($mysqli);
    $dashboard_photo = $branding['profile_image_path'] ?? '';
    $current_professional_id = current_professional_id_for_user($mysqli, (int) ($_SESSION['user_id'] ?? 0));
    $professional_filter = $current_professional_id > 0
        ? " AND a.professional_id = " . (int) $current_professional_id
        : " AND 1 = 0";

    $base_select = "
        SELECT a.id, a.user_id, a.professional_id, a.appointment_date, a.appointment_time,
               a.consultation_type, a.service_type, a.online_session_url,
               COALESCE(a.duration_minutes, so.duration_minutes, 60) AS duration_minutes,
               COALESCE(a.payment_status, 'pending') AS payment_status,
               a.payment_method, a.patient_bonus_id,
               s.name AS service_name,
               u.name, u.email, u.phone,
               p.display_name AS professional_name, p.public_photo_path AS professional_photo_path,
               pu.role AS professional_user_role
        FROM appointments a
        LEFT JOIN appointment_service_options so ON so.id = a.service_option_id AND so.tenant_id = a.tenant_id
        LEFT JOIN appointment_services s ON s.id = so.service_id AND s.tenant_id = a.tenant_id
        JOIN users u ON u.id = a.user_id AND u.tenant_id = a.tenant_id
        LEFT JOIN professionals p ON p.id = a.professional_id AND p.tenant_id = a.tenant_id
        LEFT JOIN users pu ON pu.id = p.user_id AND pu.tenant_id = p.tenant_id
        WHERE a.tenant_id = $tenant_id
          AND a.status = 'booked'
          $professional_filter
    ";
    $today_sql = $mysqli->real_escape_string(date('Y-m-d'));
    $now_time_sql = $mysqli->real_escape_string(date('H:i:s'));

    $current_res = $mysqli->query("
        $base_select
          AND a.appointment_date = '$today_sql'
          AND a.appointment_time <= '$now_time_sql'
          AND ADDTIME(a.appointment_time, SEC_TO_TIME(COALESCE(a.duration_minutes, so.duration_minutes, 60) * 60)) > '$now_time_sql'
        ORDER BY a.appointment_date ASC, a.appointment_time ASC
        LIMIT 1
    ");
    $current = $current_res ? $current_res->fetch_assoc() : null;
    $exclude_current = $current ? " AND a.id <> " . (int) $current['id'] : '';
    $next_res = $mysqli->query("
        $base_select
          AND (a.appointment_date > '$today_sql' OR (a.appointment_date = '$today_sql' AND a.appointment_time > '$now_time_sql'))
          $exclude_current
        ORDER BY a.appointment_date ASC, a.appointment_time ASC
        LIMIT 1
    ");
    $next = $next_res ? $next_res->fetch_assoc() : null;
    $waiting_list_payload = ($is_superadmin || !empty($member_permissions['patients']))
        ? dashboard_waiting_list_summary_payload($mysqli, $current_professional_id)
        : ['count' => 0, 'has_slot' => false];
    if ($current_professional_id > 0 && !cabinet_professional_notification_enabled($mysqli, $current_professional_id, 'waiting_list')) {
        $waiting_list_payload = ['count' => 0, 'has_slot' => false];
    }
    $important_notices = [];
    if ($is_superadmin || $session_role === 'admin') {
        $payment_settings_res = $mysqli->query("
            SELECT online_payment_enabled, environment,
                   billing_enabled, billing_provider, billing_country, billing_province,
                   legal_owner_name, legal_nif, legal_address, legal_city, legal_postal_code,
                   verifactu_enabled, verifactu_start_date
            FROM payment_settings
            WHERE tenant_id = $tenant_id
            LIMIT 1
        ");
        $payment_settings_row = $payment_settings_res ? ($payment_settings_res->fetch_assoc() ?: []) : [];
        if (
            (int) ($payment_settings_row['online_payment_enabled'] ?? 0) === 1
            && (string) ($payment_settings_row['environment'] ?? 'sandbox') === 'sandbox'
        ) {
            $important_notices[] = [
                'type' => 'online_payments_sandbox',
                'level' => 'danger',
                'title' => 'Pagos online en modo de prueba',
                'message' => "Los cobros realizados por los clientes son simulaciones y no ingresar\u{00E1}n dinero en tu cuenta.",
                'action' => 'payment_settings',
                'action_label' => "Revisar configuraci\u{00F3}n"
            ];
        }
        $billing_enabled = (int) ($payment_settings_row['billing_enabled'] ?? 0) === 1;
        if ($billing_enabled) {
            $missing_fiscal_fields = [];
            if (trim((string) ($payment_settings_row['legal_owner_name'] ?? '')) === '') {
                $missing_fiscal_fields[] = 'nombre fiscal';
            }
            if (trim((string) ($payment_settings_row['legal_nif'] ?? '')) === '') {
                $missing_fiscal_fields[] = 'NIF';
            }
            if (trim((string) ($payment_settings_row['legal_address'] ?? '')) === '') {
                $missing_fiscal_fields[] = 'domicilio';
            }
            if (trim((string) ($payment_settings_row['legal_city'] ?? '')) === '') {
                $missing_fiscal_fields[] = 'municipio';
            }
            if (trim((string) ($payment_settings_row['legal_postal_code'] ?? '')) === '') {
                $missing_fiscal_fields[] = "c\u{00F3}digo postal";
            }
            if (
                strtoupper(trim((string) ($payment_settings_row['billing_country'] ?? 'ES'))) === 'ES'
                && trim((string) ($payment_settings_row['billing_province'] ?? '')) === ''
            ) {
                $missing_fiscal_fields[] = 'provincia';
            }
            if ($missing_fiscal_fields) {
                $important_notices[] = [
                    'type' => 'billing_fiscal_data_incomplete',
                    'level' => 'danger',
                    'title' => "Informaci\u{00F3}n fiscal incompleta",
                    'message' => 'Falta completar: ' . implode(', ', $missing_fiscal_fields) . ". No se podr\u{00E1}n emitir facturas correctamente.",
                    'action' => 'billing_settings',
                    'action_label' => 'Completar datos'
                ];
            }
        }
        $verifactu_configured = $billing_enabled
            && (int) ($payment_settings_row['verifactu_enabled'] ?? 0) === 1;
        $billing_provider = (string) ($payment_settings_row['billing_provider'] ?? 'praxis');
        if ($verifactu_configured && $billing_provider === 'praxis') {
            $verifactu_records_table = $mysqli->query("SHOW TABLES LIKE 'verifactu_records'");
            if ($verifactu_records_table && $verifactu_records_table->num_rows > 0) {
                $verifactu_failed_res = $mysqli->query("
                    SELECT COUNT(*) AS total
                    FROM verifactu_records
                    WHERE tenant_id = $tenant_id
                      AND status = 'error'
                ");
                $verifactu_failed = (int) ($verifactu_failed_res ? ($verifactu_failed_res->fetch_assoc()['total'] ?? 0) : 0);
                if ($verifactu_failed > 0) {
                    $important_notices[] = [
                        'type' => 'verifactu_failed_records',
                        'level' => 'danger',
                        'title' => $verifactu_failed === 1
                            ? 'Hay 1 registro VeriFactu fallido'
                            : "Hay {$verifactu_failed} registros VeriFactu fallidos",
                        'message' => 'Revisa las facturas afectadas y el motivo del rechazo o del error de envío.',
                        'action' => 'billing_invoices',
                        'action_label' => 'Ver facturas'
                    ];
                }
            }
        }
        if ($billing_enabled && $billing_provider === 'simplygest_cloud') {
            $cloud_pending_res = $mysqli->query("
                SELECT COUNT(*) AS total
                FROM movim
                WHERE tenant_id = $tenant_id
                  AND tipo_movim = 'factura'
                  AND billing_provider = 'simplygest_cloud'
                  AND (external_invoice_id IS NULL OR external_invoice_id = '')
            ");
            $cloud_pending = (int) ($cloud_pending_res ? ($cloud_pending_res->fetch_assoc()['total'] ?? 0) : 0);
            if ($cloud_pending > 0) {
                $important_notices[] = [
                    'type' => 'cloud_invoices_pending',
                    'level' => 'danger',
                    'title' => $cloud_pending === 1
                        ? 'Hay 1 factura sin enviar a Cloud'
                        : "Hay {$cloud_pending} facturas sin enviar a Cloud",
                    'message' => 'Comprueba la conexión con SimplyGest Cloud y revisa las facturas pendientes.',
                    'action' => 'billing_invoices',
                    'action_label' => 'Ver facturas'
                ];
            }
        }
        // Read signing independently from billing/VeriFactu. This keeps the
        // certificate notice active even when billing is disabled.
        $signature_settings = signature_settings_values($mysqli);
        $automatic_signing_enabled =
            (int) ($signature_settings['signature_auto_invoices'] ?? 0) === 1
            || (int) ($signature_settings['signature_auto_reports'] ?? 0) === 1
            || (int) ($signature_settings['signature_auto_documents'] ?? 0) === 1;
        $certificate_status = stampbyme_certificate_status($tenant_id);
        $certificate_expired_notice_added = false;
        if ($verifactu_configured) {
            $legal_nif = verifactu_normalize_tax_id((string) ($payment_settings_row['legal_nif'] ?? ''));
            if (
                !empty($certificate_status['available'])
                &&
                trim((string) ($certificate_status['valid_to'] ?? '')) !== ''
                && strtotime((string) $certificate_status['valid_to']) <= time()
            ) {
                $important_notices[] = [
                    'type' => 'verifactu_certificate_expired',
                    'level' => 'danger',
                    'title' => "El certificado de VeriFactu est\u{00E1} caducado",
                    'message' => 'Sustituye el certificado general para poder continuar enviando facturas.',
                    'action' => 'signature_settings',
                    'action_label' => 'Sustituir certificado'
                ];
                $certificate_expired_notice_added = true;
            } elseif (!empty($certificate_status['available'])) {
                $certificate_tax_ids = array_values(array_unique(array_filter(array_map(
                    'verifactu_normalize_tax_id',
                    (array) ($certificate_status['tax_ids'] ?? [])
                ))));
                if ($legal_nif !== '' && $certificate_tax_ids && !in_array($legal_nif, $certificate_tax_ids, true)) {
                    $important_notices[] = [
                        'type' => 'verifactu_certificate_mismatch',
                        'level' => 'danger',
                        'title' => 'El certificado no corresponde al emisor',
                        'message' => 'El NIF del certificado general no coincide con el NIF fiscal configurado para VeriFactu.',
                        'action' => 'signature_settings',
                        'action_label' => 'Revisar certificado'
                    ];
                }
            }
        }
        if (
            empty($certificate_status['available'])
            && ($verifactu_configured || $automatic_signing_enabled)
        ) {
            if ($verifactu_configured && $automatic_signing_enabled) {
                $missing_certificate_title = 'Falta el certificado digital del centro';
                $missing_certificate_message = "Es necesario para VeriFactu y para aplicar las firmas autom\u{00E1}ticas configuradas.";
            } elseif ($verifactu_configured) {
                $missing_certificate_title = 'VeriFactu no tiene certificado digital';
                $missing_certificate_message = 'Importa el certificado general del centro antes de emitir o enviar facturas a la AEAT.';
            } else {
                $missing_certificate_title = "Falta el certificado para la firma autom\u{00E1}tica";
                $missing_certificate_message = "Has activado la firma autom\u{00E1}tica de PDF, pero todav\u{00ED}a no has importado el certificado general del centro.";
            }
            $important_notices[] = [
                'type' => 'certificate_missing',
                'level' => 'danger',
                'title' => $missing_certificate_title,
                'message' => $missing_certificate_message,
                'action' => 'signature_settings',
                'action_label' => 'Importar certificado'
            ];
        }
        if (
            !empty($certificate_status['available'])
            && trim((string) ($certificate_status['valid_to'] ?? '')) !== ''
        ) {
            $certificate_expires_ts = strtotime((string) $certificate_status['valid_to']);
            if ($certificate_expires_ts && $certificate_expires_ts <= time() && !$certificate_expired_notice_added) {
                $important_notices[] = [
                    'type' => 'certificate_expired',
                    'level' => 'danger',
                    'title' => "El certificado digital est\u{00E1} caducado",
                    'message' => 'Sustituye el certificado general para poder seguir firmando documentos.',
                    'action' => 'signature_settings',
                    'action_label' => 'Sustituir certificado'
                ];
            } elseif ($certificate_expires_ts && $certificate_expires_ts > time()) {
                $certificate_days_remaining = max(1, (int) ceil(($certificate_expires_ts - time()) / 86400));
                if ($certificate_days_remaining <= 30) {
                    $certificate_level = $certificate_days_remaining < 5 ? 'danger' : 'warning';
                    if ($certificate_days_remaining === 1) {
                        $certificate_title = "El certificado digital caduca ma\u{00F1}ana";
                    } else {
                        $certificate_title = "El certificado digital caduca en {$certificate_days_remaining} d\u{00ED}as";
                    }
                    $certificate_message = $certificate_days_remaining < 5
                        ? "Sustit\u{00FA}yelo cuanto antes para evitar interrupciones en la firma y en VeriFactu."
                        : ($certificate_days_remaining <= 10
                            ? "Conviene sustituirlo ya para evitar interrupciones en la firma y en VeriFactu."
                            : "Planifica su renovaci\u{00F3}n antes del " . date('d/m/Y', $certificate_expires_ts) . '.');
                    $important_notices[] = [
                        'type' => 'certificate_expiring',
                        'level' => $certificate_level,
                        'title' => $certificate_title,
                        'message' => $certificate_message,
                        'action' => 'signature_settings',
                        'action_label' => 'Revisar certificado'
                    ];
                }
            }
        }
        $data_exports_table = $mysqli->query("SHOW TABLES LIKE 'tenant_data_export_jobs'");
        if ($data_exports_table && $data_exports_table->num_rows > 0) {
            $latest_data_export_res = $mysqli->query("
                SELECT status, error_message
                FROM tenant_data_export_jobs
                WHERE tenant_id = $tenant_id
                ORDER BY id DESC
                LIMIT 1
            ");
            $latest_data_export = $latest_data_export_res ? $latest_data_export_res->fetch_assoc() : null;
            if ($latest_data_export && (string) ($latest_data_export['status'] ?? '') === 'failed') {
                $important_notices[] = [
                    'type' => 'data_export_failed',
                    'level' => 'danger',
                    'title' => "La exportaci\u{00F3}n de datos ha fallado",
                    'message' => trim((string) ($latest_data_export['error_message'] ?? '')) !== ''
                        ? (string) $latest_data_export['error_message']
                        : "No se pudo completar la \u{00FA}ltima exportaci\u{00F3}n. Revisa el estado o vuelve a intentarlo.",
                    'action' => $is_superadmin ? 'data_export' : '',
                    'action_label' => $is_superadmin ? "Revisar exportaci\u{00F3}n" : ''
                ];
            }
            $data_export_res = $mysqli->query("
                SELECT id, expires_at
                FROM tenant_data_export_jobs
                WHERE tenant_id = $tenant_id
                  AND status = 'completed'
                  AND downloaded_at IS NULL
                  AND expires_at > NOW()
                ORDER BY completed_at DESC
                LIMIT 1
            ");
            $data_export = $data_export_res ? $data_export_res->fetch_assoc() : null;
            if ($data_export) {
                $important_notices[] = [
                    'type' => 'data_export_ready',
                    'level' => 'info',
                    'title' => 'Tu exportación de datos ya está disponible',
                    'message' => 'Descárgala antes del ' . date('d/m/Y H:i', strtotime((string) $data_export['expires_at'])) . '. Después se eliminará automáticamente.',
                    'action' => $is_superadmin ? 'data_export' : '',
                    'action_label' => $is_superadmin ? 'Descargar' : ''
                ];
            }
        }
        $trial_res = $mysqli->query("
            SELECT registration_status, trial_days, installed_at, created_at
            FROM tenants
            WHERE id = $tenant_id
            LIMIT 1
        ");
        $trial = $trial_res ? ($trial_res->fetch_assoc() ?: []) : [];
        if ((int) ($trial['registration_status'] ?? 1) === 0) {
            $trial_started_at = trim((string) ($trial['installed_at'] ?? ''));
            if ($trial_started_at === '') {
                $trial_started_at = trim((string) ($trial['created_at'] ?? ''));
            }
            $trial_started_ts = $trial_started_at !== '' ? strtotime($trial_started_at) : false;
            $trial_days = max(1, (int) ($trial['trial_days'] ?? 15));
            $trial_expires_ts = $trial_started_ts ? strtotime('+' . $trial_days . ' days', $trial_started_ts) : false;
            if ($trial_expires_ts && $trial_expires_ts > time()) {
                $trial_days_remaining = max(1, (int) ceil(($trial_expires_ts - time()) / 86400));
                $important_notices[] = [
                    'type' => 'trial_days_remaining',
                    'level' => 'info',
                    'title' => $trial_days_remaining === 1
                        ? "Te queda 1 d\u{00ED}a de prueba"
                        : "Te quedan {$trial_days_remaining} d\u{00ED}as de prueba",
                    'message' => "Est\u{00E1}s utilizando el periodo gratuito de SimplyGest Praxis."
                ];
            }
        }
    }

    // Internal team tasks are personal to the signed-in member, so this
    // notice is deliberately built outside the superadmin-only settings block.
    if (
        ($is_superadmin || !empty($member_permissions['team_notes']))
        && in_array(plan_config_normalize_key(dashboard_config_plan_key_from_db($mysqli), ''), ['magister', 'summum'], true)
    ) {
        $team_notes_table = $mysqli->query("SHOW TABLES LIKE 'team_notes'");
        if ($team_notes_table && $team_notes_table->num_rows > 0) {
            $viewer_user_id = (int) ($_SESSION['user_id'] ?? 0);
            $team_tasks_res = $mysqli->query("
                SELECT
                    COUNT(*) AS pending_count,
                    SUM(CASE WHEN due_at IS NOT NULL AND due_at < NOW() THEN 1 ELSE 0 END) AS overdue_count,
                    MIN(due_at) AS next_due_at
                FROM team_notes
                WHERE tenant_id = $tenant_id
                  AND item_type = 'task'
                  AND status = 'pending'
                  AND (
                    author_user_id = $viewer_user_id
                    OR visibility = 'team'
                    OR (visibility = 'professional' AND target_user_id = $viewer_user_id)
                  )
            ");
            $team_tasks = $team_tasks_res ? ($team_tasks_res->fetch_assoc() ?: []) : [];
            $pending_team_tasks = (int) ($team_tasks['pending_count'] ?? 0);
            $overdue_team_tasks = (int) ($team_tasks['overdue_count'] ?? 0);
            if ($pending_team_tasks > 0) {
                $task_title = $overdue_team_tasks > 0
                    ? ($overdue_team_tasks === 1 ? 'Tienes 1 tarea interna vencida' : "Tienes {$overdue_team_tasks} tareas internas vencidas")
                    : ($pending_team_tasks === 1 ? 'Tienes 1 tarea interna pendiente' : "Tienes {$pending_team_tasks} tareas internas pendientes");
                $task_message = $overdue_team_tasks > 0
                    ? 'Revísalas para evitar que queden asuntos del equipo sin atender.'
                    : 'Consulta las notas y tareas internas del equipo.';
                $important_notices[] = [
                    'type' => 'team_tasks_pending',
                    'level' => $overdue_team_tasks > 0 ? 'danger' : 'warning',
                    'title' => $task_title,
                    'message' => $task_message,
                    'action' => 'team_notes',
                    'action_label' => 'Ver tareas'
                ];
            }
        }
    }

    echo json_encode([
        'success' => true,
        'current' => quick_appointment_payload($current, $dashboard_photo),
        'next' => quick_appointment_payload($next, $dashboard_photo),
        'waiting_list' => $waiting_list_payload,
        'important_notices' => $important_notices,
        'current_professional_id' => $current_professional_id
    ]);
} elseif ($action === 'upcoming_appointments') {
    ensure_appointment_payment_columns($mysqli);
    ensure_appointment_services_tables($mysqli);
    ensure_cabinet_schema($mysqli);
    $branding = get_public_branding_settings($mysqli);
    $dashboard_photo = $branding['profile_image_path'] ?? '';
    $scope = $_GET['scope'] ?? 'limit10';
    $planning_scope = $_GET['planning_scope'] ?? '3days';
    $requested_professional_raw = $_GET['professional_id'] ?? '';
    $requested_professional_id = (int) $requested_professional_raw;
    $past_professional_raw = $_GET['past_professional_id'] ?? $requested_professional_raw;
    $past_professional_id = (int) $past_professional_raw;
    $where_extra = '';
    $professional_filter = '';
    $limit_sql = 'LIMIT 10';
    if ($scope === '3days') {
        $where_extra = " AND a.appointment_date < DATE_ADD(CURDATE(), INTERVAL 3 DAY)";
        $limit_sql = '';
    } elseif ($scope === '7days') {
        $where_extra = " AND a.appointment_date < DATE_ADD(CURDATE(), INTERVAL 7 DAY)";
        $limit_sql = '';
    } elseif ($scope === '14days') {
        $where_extra = " AND a.appointment_date < DATE_ADD(CURDATE(), INTERVAL 14 DAY)";
        $limit_sql = '';
    } elseif ($scope === 'all') {
        $limit_sql = '';
    }

    $current_professional_id = current_professional_id_for_user($mysqli, (int) ($_SESSION['user_id'] ?? 0));
    if ($is_superadmin) {
        if ($requested_professional_raw === 'current') {
            $requested_professional_id = $current_professional_id;
        }
        if ($requested_professional_raw !== 'all' && $requested_professional_id > 0) {
            $professional_filter = " AND a.professional_id = " . $requested_professional_id;
        }
    } elseif (!$is_superadmin) {
        $professional_filter = $current_professional_id > 0 ? " AND a.professional_id = " . $current_professional_id : " AND 1 = 0";
    }
    $past_professional_filter = '';
    if ($is_superadmin) {
        if ($past_professional_raw === 'current') $past_professional_id = $current_professional_id;
        if ($past_professional_raw !== 'all' && $past_professional_id > 0) $past_professional_filter = " AND a.professional_id = " . $past_professional_id;
    } else {
        $past_professional_filter = $current_professional_id > 0 ? " AND a.professional_id = " . $current_professional_id : " AND 1 = 0";
    }

    $res = $mysqli->query("
        SELECT a.id, a.appointment_date, a.appointment_time, a.consultation_type, a.service_type, a.online_session_url,
               COALESCE(a.duration_minutes, so.duration_minutes, 60) AS duration_minutes,
               s.name AS service_name,
               COALESCE(a.payment_status, 'pending') AS payment_status,
               a.payment_method, a.patient_bonus_id,
               u.name, u.email, u.phone,
               p.id AS professional_id, p.display_name AS professional_name, p.public_photo_path AS professional_photo_path,
               pu.role AS professional_user_role
        FROM appointments a
        LEFT JOIN appointment_service_options so ON so.id = a.service_option_id AND so.tenant_id = a.tenant_id
        LEFT JOIN appointment_services s ON s.id = so.service_id AND s.tenant_id = a.tenant_id
        LEFT JOIN professionals p ON p.id = a.professional_id AND p.tenant_id = a.tenant_id
        LEFT JOIN users pu ON pu.id = p.user_id AND pu.tenant_id = p.tenant_id
        JOIN users u ON u.id = a.user_id AND u.tenant_id = a.tenant_id
        WHERE a.tenant_id = $tenant_id
          AND a.status = 'booked'
          AND CONCAT(a.appointment_date, ' ', a.appointment_time) >= NOW()
          $where_extra
          $professional_filter
        ORDER BY a.appointment_date ASC, a.appointment_time ASC
        $limit_sql
    ");

    $appointments = [];
    while ($row = $res->fetch_assoc()) {
        $professional_photo_path = professional_photo_with_dashboard_fallback($row, $dashboard_photo);
        $appointments[] = [
            'id' => (int) $row['id'],
            'appointment_date' => $row['appointment_date'],
            'appointment_time' => substr($row['appointment_time'], 0, 5),
            'patient_name' => $row['name'],
            'patient_email' => $row['email'],
            'patient_phone' => member_patient_phone($row['phone'] ?? ''),
            'professional_id' => (int) ($row['professional_id'] ?? 0),
            'professional_name' => $row['professional_name'] ?? '',
            'professional_photo_path' => $professional_photo_path,
            'consultation_type' => $row['consultation_type'] ?? 'presencial',
            'online_session_url' => $row['online_session_url'] ?? '',
            'service_label' => appointment_service_option_label($row),
            'payment_status' => $row['payment_status'] ?? 'pending',
            'payment_method' => $row['payment_method'],
            'patient_bonus_id' => $row['patient_bonus_id']
        ];
    }

    $past_res = $mysqli->query("\n        SELECT a.id, a.appointment_date, a.appointment_time, a.status, a.consultation_type, a.service_type, a.online_session_url,\n               COALESCE(a.duration_minutes, so.duration_minutes, 60) AS duration_minutes, s.name AS service_name,\n               COALESCE(a.payment_status, 'pending') AS payment_status, a.payment_method, a.patient_bonus_id,\n               u.name, u.email, u.phone, p.id AS professional_id, p.display_name AS professional_name,\n               p.public_photo_path AS professional_photo_path, pu.role AS professional_user_role\n        FROM appointments a\n        LEFT JOIN appointment_service_options so ON so.id = a.service_option_id AND so.tenant_id = a.tenant_id\n        LEFT JOIN appointment_services s ON s.id = so.service_id AND s.tenant_id = a.tenant_id\n        LEFT JOIN professionals p ON p.id = a.professional_id AND p.tenant_id = a.tenant_id\n        LEFT JOIN users pu ON pu.id = p.user_id AND pu.tenant_id = p.tenant_id\n        JOIN users u ON u.id = a.user_id AND u.tenant_id = a.tenant_id\n        WHERE a.tenant_id = $tenant_id AND a.status <> 'cancelled'\n          AND CONCAT(a.appointment_date, ' ', a.appointment_time) < NOW()\n          $past_professional_filter\n        ORDER BY a.appointment_date DESC, a.appointment_time DESC, a.id DESC\n    ");
    $past_appointments = [];
    while ($row = $past_res->fetch_assoc()) {
        $past_appointments[] = [
            'id' => (int) $row['id'], 'appointment_date' => $row['appointment_date'],
            'appointment_time' => substr($row['appointment_time'], 0, 5), 'duration_minutes' => (int) ($row['duration_minutes'] ?? 60),
            'status' => $row['status'] ?? 'booked', 'patient_name' => $row['name'], 'patient_email' => $row['email'],
            'patient_phone' => member_patient_phone($row['phone'] ?? ''), 'professional_id' => (int) ($row['professional_id'] ?? 0),
            'professional_name' => $row['professional_name'] ?? '',
            'professional_photo_path' => professional_photo_with_dashboard_fallback($row, $dashboard_photo),
            'consultation_type' => $row['consultation_type'] ?? 'presencial', 'online_session_url' => $row['online_session_url'] ?? '',
            'service_label' => appointment_service_option_label($row), 'payment_status' => $row['payment_status'] ?? 'pending',
            'payment_method' => $row['payment_method'], 'patient_bonus_id' => $row['patient_bonus_id']
        ];
    }

    $cancelled_res = $mysqli->query("
        SELECT a.id, a.appointment_date, a.appointment_time, a.cancelled_at, a.consultation_type, a.service_type, a.online_session_url,
               COALESCE(a.duration_minutes, so.duration_minutes, 60) AS duration_minutes,
               s.name AS service_name,
               COALESCE(a.payment_status, 'pending') AS payment_status,
               a.payment_method, a.patient_bonus_id,
               u.name, u.email, u.phone,
               p.id AS professional_id, p.display_name AS professional_name, p.public_photo_path AS professional_photo_path,
               pu.role AS professional_user_role
        FROM appointments a
        LEFT JOIN appointment_service_options so ON so.id = a.service_option_id AND so.tenant_id = a.tenant_id
        LEFT JOIN appointment_services s ON s.id = so.service_id AND s.tenant_id = a.tenant_id
        LEFT JOIN professionals p ON p.id = a.professional_id AND p.tenant_id = a.tenant_id
        LEFT JOIN users pu ON pu.id = p.user_id AND pu.tenant_id = p.tenant_id
        JOIN users u ON u.id = a.user_id AND u.tenant_id = a.tenant_id
        WHERE a.tenant_id = $tenant_id
          AND a.status = 'cancelled'
          $professional_filter
        ORDER BY COALESCE(a.cancelled_at, a.appointment_date) DESC, a.appointment_date DESC, a.appointment_time DESC
        LIMIT 50
    ");

    $cancelled_appointments = [];
    while ($row = $cancelled_res->fetch_assoc()) {
        $professional_photo_path = professional_photo_with_dashboard_fallback($row, $dashboard_photo);
        $cancelled_appointments[] = [
            'id' => (int) $row['id'],
            'appointment_date' => $row['appointment_date'],
            'appointment_time' => substr($row['appointment_time'], 0, 5),
            'cancelled_at' => $row['cancelled_at'] ?? '',
            'patient_name' => $row['name'],
            'patient_email' => $row['email'],
            'patient_phone' => member_patient_phone($row['phone'] ?? ''),
            'professional_id' => (int) ($row['professional_id'] ?? 0),
            'professional_name' => $row['professional_name'] ?? '',
            'professional_photo_path' => $professional_photo_path,
            'consultation_type' => $row['consultation_type'] ?? 'presencial',
            'online_session_url' => $row['online_session_url'] ?? '',
            'service_label' => appointment_service_option_label($row),
            'payment_status' => $row['payment_status'] ?? 'pending',
            'payment_method' => $row['payment_method'],
            'patient_bonus_id' => $row['patient_bonus_id']
        ];
    }

    $professionals = [];
    if ($is_superadmin) {
        $professionals = active_professionals_payload($mysqli);
    }

    $planning_days = 7;
    $planning_start_offset = 0;
    if ($planning_scope === 'today') {
        $planning_days = 1;
    } elseif ($planning_scope === 'tomorrow') {
        $planning_days = 1;
        $planning_start_offset = 1;
    } elseif ($planning_scope === '3days') {
        $planning_days = 3;
    }
    $planning_professional_id = $current_professional_id;
    $planning_settings = cabinet_get_effective_professional_settings($mysqli, $planning_professional_id);
    $planning_settings = [
        'professional_id' => (int) $planning_professional_id,
        'appointment_start_time' => substr($planning_settings['appointment_start_time'] ?? '10:00:00', 0, 5),
        'appointment_end_time' => substr($planning_settings['appointment_end_time'] ?? '19:00:00', 0, 5),
        'break_start_time' => !empty($planning_settings['break_start_time']) ? substr($planning_settings['break_start_time'], 0, 5) : '',
        'break_end_time' => !empty($planning_settings['break_end_time']) ? substr($planning_settings['break_end_time'], 0, 5) : '',
        'available_weekdays' => $planning_settings['available_weekdays'] ?? '1,2,3,4,5',
        'start_offset' => $planning_start_offset,
        'days' => $planning_days
    ];

    $closed_where = "(cd.is_global = 1 OR cd.professional_id = " . (int) $planning_professional_id . " OR (cd.professional_id IS NULL AND cd.is_global = 0))";
    $closed_res = $mysqli->query("
        SELECT cd.closed_date, cd.reason, cd.is_global, cd.professional_id
        FROM closed_days cd
        WHERE cd.closed_date >= DATE_ADD(CURDATE(), INTERVAL " . (int) $planning_start_offset . " DAY)
          AND cd.tenant_id = $tenant_id
          AND cd.closed_date < DATE_ADD(CURDATE(), INTERVAL " . (int) ($planning_start_offset + $planning_days) . " DAY)
          AND $closed_where
        ORDER BY cd.closed_date ASC
    ");
    $closed_days = [];
    while ($row = $closed_res->fetch_assoc()) {
        $closed_days[] = [
            'date' => $row['closed_date'],
            'reason' => $row['reason'] ?? '',
            'is_global' => (int) ($row['is_global'] ?? 0),
            'professional_id' => (int) ($row['professional_id'] ?? 0)
        ];
    }

    $planning_appointments = [];
    if ($planning_professional_id > 0) {
        $planning_res = $mysqli->query("
            SELECT a.id, a.appointment_date, a.appointment_time, a.consultation_type, a.service_type, a.online_session_url,
                   COALESCE(a.duration_minutes, so.duration_minutes, 60) AS duration_minutes,
                   s.name AS service_name,
                   COALESCE(a.payment_status, 'pending') AS payment_status,
                   a.payment_method, a.patient_bonus_id,
                   u.name, u.email, u.phone
            FROM appointments a
            LEFT JOIN appointment_service_options so ON so.id = a.service_option_id AND so.tenant_id = a.tenant_id
            LEFT JOIN appointment_services s ON s.id = so.service_id AND s.tenant_id = a.tenant_id
            JOIN users u ON u.id = a.user_id AND u.tenant_id = a.tenant_id
            WHERE a.tenant_id = $tenant_id
              AND a.status = 'booked'
              AND a.appointment_date >= DATE_ADD(CURDATE(), INTERVAL " . (int) $planning_start_offset . " DAY)
              AND a.appointment_date < DATE_ADD(CURDATE(), INTERVAL " . (int) ($planning_start_offset + $planning_days) . " DAY)
              AND (a.professional_id = " . (int) $planning_professional_id . " OR a.professional_id IS NULL)
            ORDER BY a.appointment_date ASC, a.appointment_time ASC
        ");
        while ($row = $planning_res->fetch_assoc()) {
            $planning_appointments[] = [
                'id' => (int) $row['id'],
                'appointment_date' => $row['appointment_date'],
                'appointment_time' => substr($row['appointment_time'], 0, 5),
                'patient_name' => $row['name'],
                'patient_email' => $row['email'],
                'patient_phone' => member_patient_phone($row['phone'] ?? ''),
                'consultation_type' => $row['consultation_type'] ?? 'presencial',
                'online_session_url' => $row['online_session_url'] ?? '',
                'service_label' => appointment_service_option_label($row),
                'duration_minutes' => (int) ($row['duration_minutes'] ?? 60),
                'payment_status' => $row['payment_status'] ?? 'pending',
                'payment_method' => $row['payment_method'],
                'patient_bonus_id' => $row['patient_bonus_id']
            ];
        }
    }

    echo json_encode([
        'success' => true,
        'appointments' => $appointments,
        'past_appointments' => $past_appointments,
        'cancelled_appointments' => $cancelled_appointments,
        'planning_appointments' => $planning_appointments,
        'professionals' => $professionals,
        'current_professional_id' => $current_professional_id,
        'planning_settings' => $planning_settings,
        'closed_days' => $closed_days
    ]);
} elseif ($action === 'dashboard_summary') {
    $period_days = (int) ($_GET['period_days'] ?? 30);
    if (!in_array($period_days, [7, 30, 90], true)) {
        $period_days = 30;
    }
    $current_professional_id = current_professional_id_for_user($mysqli, (int) ($_SESSION['user_id'] ?? 0));
    $current_role = (string) ($_SESSION['role'] ?? '');
    $professional_scope = !$is_superadmin && $current_role === 'admin';
    $appointment_scope = $professional_scope
        ? ($current_professional_id > 0 ? " AND a.professional_id = " . (int) $current_professional_id : " AND 1 = 0")
        : "";
    $patient_scope = $professional_scope
        ? ($current_professional_id > 0 ? " AND COALESCE(ppf.professional_id, pp.professional_id) = " . (int) $current_professional_id : " AND 1 = 0")
        : "";
    $can_appointments = $is_superadmin || !empty($member_permissions['appointments']) || !empty($member_permissions['agenda']);
    $can_patients = $is_superadmin || !empty($member_permissions['patients']);
    $can_billing = $is_superadmin || !empty($member_permissions['billing']);
    $period_start_sql = "DATE_SUB(CURDATE(), INTERVAL " . ($period_days - 1) . " DAY)";

    $payload = [
        'period_days' => $period_days,
        'scope' => $is_superadmin ? 'tenant' : ($professional_scope ? 'professional' : 'permitted'),
        'today' => null,
        'period' => null,
        'patients' => null,
        'attention' => [],
        'billing' => null,
        'team' => []
    ];

    if ($can_appointments) {
        $res = $mysqli->query("
            SELECT
                COUNT(*) AS total,
                SUM(CASE WHEN a.status = 'completed' THEN 1 ELSE 0 END) AS completed,
                SUM(CASE WHEN a.status = 'booked' THEN 1 ELSE 0 END) AS pending,
                SUM(CASE WHEN a.status = 'no_show' THEN 1 ELSE 0 END) AS no_show,
                SUM(CASE WHEN a.status = 'cancelled' THEN 1 ELSE 0 END) AS cancelled,
                SUM(CASE WHEN a.status = 'booked' AND a.patient_confirmed_at IS NOT NULL THEN 1 ELSE 0 END) AS confirmed
            FROM appointments a
            WHERE a.tenant_id = $tenant_id
              AND a.appointment_date = CURDATE()
              $appointment_scope
        ");
        $row = $res ? $res->fetch_assoc() : [];
        $payload['today'] = [
            'total' => (int) ($row['total'] ?? 0),
            'completed' => (int) ($row['completed'] ?? 0),
            'pending' => (int) ($row['pending'] ?? 0),
            'no_show' => (int) ($row['no_show'] ?? 0),
            'cancelled' => (int) ($row['cancelled'] ?? 0),
            'confirmed' => (int) ($row['confirmed'] ?? 0)
        ];

        $res = $mysqli->query("
            SELECT
                COUNT(*) AS total,
                SUM(CASE WHEN a.status = 'completed' THEN 1 ELSE 0 END) AS completed,
                SUM(CASE WHEN a.status = 'booked' THEN 1 ELSE 0 END) AS booked,
                SUM(CASE WHEN a.status = 'no_show' THEN 1 ELSE 0 END) AS no_show,
                SUM(CASE WHEN a.status = 'cancelled' THEN 1 ELSE 0 END) AS cancelled
            FROM appointments a
            WHERE a.tenant_id = $tenant_id
              AND a.appointment_date BETWEEN $period_start_sql AND CURDATE()
              $appointment_scope
        ");
        $row = $res ? $res->fetch_assoc() : [];
        $attended_base = (int) ($row['completed'] ?? 0) + (int) ($row['no_show'] ?? 0);
        $payload['period'] = [
            'total' => (int) ($row['total'] ?? 0),
            'completed' => (int) ($row['completed'] ?? 0),
            'booked' => (int) ($row['booked'] ?? 0),
            'no_show' => (int) ($row['no_show'] ?? 0),
            'cancelled' => (int) ($row['cancelled'] ?? 0),
            'attendance_rate' => $attended_base > 0 ? round(((int) $row['completed'] / $attended_base) * 100, 1) : 0
        ];
    }

    if ($can_patients) {
        $patient_joins = "
            LEFT JOIN patient_professionals ppf ON ppf.patient_id = u.id AND ppf.tenant_id = u.tenant_id AND ppf.is_primary = 1
            LEFT JOIN patient_profiles pp ON pp.user_id = u.id AND pp.tenant_id = u.tenant_id
        ";
        $res = $mysqli->query("
            SELECT COUNT(DISTINCT u.id) AS total,
                   COUNT(DISTINCT CASE WHEN u.created_at >= $period_start_sql THEN u.id END) AS new_count,
                   COUNT(DISTINCT CASE WHEN COALESCE(pp.waiting_list, 0) = 1 THEN u.id END) AS waiting_count
            FROM users u
            $patient_joins
            WHERE u.tenant_id = $tenant_id
              AND u.role = 'patient'
              $patient_scope
        ");
        $row = $res ? $res->fetch_assoc() : [];
        $payload['patients'] = [
            'total' => (int) ($row['total'] ?? 0),
            'new' => (int) ($row['new_count'] ?? 0),
            'waiting' => (int) ($row['waiting_count'] ?? 0)
        ];
        if ((int) ($row['waiting_count'] ?? 0) > 0) {
            $payload['attention'][] = [
                'type' => 'waiting_list',
                'level' => 'warning',
                'count' => (int) $row['waiting_count'],
                'label' => (int) $row['waiting_count'] === 1
                    ? '1 paciente en lista de espera'
                    : (int) $row['waiting_count'] . ' pacientes en lista de espera'
            ];
        }

        if (table_exists($mysqli, 'patient_legal_documents') && table_exists($mysqli, 'legal_documents')) {
            $res = $mysqli->query("
                SELECT COUNT(*) AS total
                FROM patient_legal_documents pld
                INNER JOIN legal_documents ld ON ld.id = pld.legal_document_id AND ld.tenant_id = pld.tenant_id
                INNER JOIN users u ON u.id = pld.patient_id AND u.tenant_id = pld.tenant_id
                $patient_joins
                WHERE pld.tenant_id = $tenant_id
                  AND ld.is_required = 1
                  AND COALESCE(pld.accepted, 0) = 0
                  $patient_scope
            ");
            $pending_consents = (int) (($res ? $res->fetch_assoc()['total'] ?? 0 : 0));
            if ($pending_consents > 0) {
                $payload['attention'][] = [
                    'type' => 'consents',
                    'level' => 'danger',
                    'count' => $pending_consents,
                    'label' => $pending_consents === 1
                        ? '1 consentimiento obligatorio pendiente'
                        : $pending_consents . ' consentimientos obligatorios pendientes'
                ];
            }
        }
    }

    if ($can_billing) {
        $res = $mysqli->query("
            SELECT
                COALESCE(SUM(CASE WHEN COALESCE(a.payment_status, 'pending') = 'paid' THEN COALESCE(aso.price, 0) ELSE 0 END), 0) AS collected,
                SUM(CASE WHEN COALESCE(a.payment_status, 'pending') <> 'paid' AND a.status <> 'cancelled' THEN 1 ELSE 0 END) AS pending_count
            FROM appointments a
            LEFT JOIN appointment_service_options aso ON aso.id = a.service_option_id AND aso.tenant_id = a.tenant_id
            WHERE a.tenant_id = $tenant_id
              AND a.appointment_date BETWEEN $period_start_sql AND CURDATE()
              $appointment_scope
        ");
        $row = $res ? $res->fetch_assoc() : [];
        $payload['billing'] = [
            'collected' => number_format((float) ($row['collected'] ?? 0), 2, '.', ''),
            'pending_count' => (int) ($row['pending_count'] ?? 0)
        ];
        if ((int) ($row['pending_count'] ?? 0) > 0) {
            $payload['attention'][] = [
                'type' => 'pending_payments',
                'level' => 'warning',
                'count' => (int) $row['pending_count'],
                'label' => (int) $row['pending_count'] === 1
                    ? '1 cita pendiente de cobro'
                    : (int) $row['pending_count'] . ' citas pendientes de cobro'
            ];
        }
    }

    if ($is_superadmin && $can_appointments) {
        $res = $mysqli->query("
            SELECT p.id, p.display_name,
                   COUNT(a.id) AS total,
                   SUM(CASE WHEN a.status = 'completed' THEN 1 ELSE 0 END) AS completed,
                   SUM(CASE WHEN a.status = 'no_show' THEN 1 ELSE 0 END) AS no_show
            FROM professionals p
            LEFT JOIN appointments a ON a.professional_id = p.id
                AND a.tenant_id = p.tenant_id
                AND a.appointment_date BETWEEN $period_start_sql AND CURDATE()
            LEFT JOIN users pu ON pu.id = p.user_id AND pu.tenant_id = p.tenant_id
            WHERE p.tenant_id = $tenant_id
              AND p.is_active = 1
              AND pu.role IN ('superadmin', 'admin')
            GROUP BY p.id, p.display_name, p.sort_order
            ORDER BY p.sort_order ASC, p.display_name ASC
        ");
        while ($res && ($row = $res->fetch_assoc())) {
            $payload['team'][] = [
                'id' => (int) $row['id'],
                'name' => $row['display_name'] ?? '',
                'total' => (int) ($row['total'] ?? 0),
                'completed' => (int) ($row['completed'] ?? 0),
                'no_show' => (int) ($row['no_show'] ?? 0)
            ];
        }
    }

    echo json_encode(['success' => true, 'dashboard' => $payload]);
} elseif ($action === 'admin_stats') {
    ensure_action_feature($mysqli, 'reports.globalReports', 'Los informes y estadisticas no estan disponibles en este plan.');
    ensure_appointment_payment_columns($mysqli);
    ensure_appointment_services_tables($mysqli);
    ensure_bonus_tables($mysqli);
    ensure_payment_attempts_table($mysqli);
    ensure_cabinet_schema($mysqli);
    $branding = get_public_branding_settings($mysqli);
    $dashboard_photo = $branding['profile_image_path'] ?? '';
    $professional_id = admin_requested_professional_filter($mysqli);
    $appointment_filter = " AND tenant_id = $tenant_id" . ($professional_id > 0 ? " AND professional_id = " . (int) $professional_id : ($professional_id < 0 ? " AND 1 = 0" : ""));
    $appointment_filter_a = " AND a.tenant_id = $tenant_id" . ($professional_id > 0 ? " AND a.professional_id = " . (int) $professional_id : ($professional_id < 0 ? " AND 1 = 0" : ""));
    $patient_join = "LEFT JOIN patient_professionals ppf ON ppf.patient_id = u.id AND ppf.tenant_id = u.tenant_id AND ppf.is_primary = 1 LEFT JOIN patient_profiles pp ON pp.user_id = u.id AND pp.tenant_id = u.tenant_id";
    $patient_filter = $professional_id > 0 ? " AND COALESCE(ppf.professional_id, pp.professional_id) = " . (int) $professional_id : ($professional_id < 0 ? " AND 1 = 0" : "");

    $stats = [
        'upcoming_count' => 0,
        'today_count' => 0,
        'month_count' => 0,
        'patient_count' => 0,
        'online_revenue_month' => '0.00',
        'payment_revenue_month' => [
            'card' => '0.00',
            'bizum' => '0.00',
            'cash' => '0.00',
            'bank_transfer' => '0.00',
            'other' => '0.00',
            'manual' => '0.00',
            'bonus' => '0.00'
        ],
        'pending_payment_count' => 0,
        'active_bonus_count' => 0,
        'active_bonus_sessions' => 0,
        'patients_by_age' => [],
        'patients_by_status' => [],
        'sessions_by_service' => [],
        'sessions_by_communication' => [],
        'sessions_by_month' => [],
        'billing_by_month' => [],
        'top_patients' => [],
        'professional_summary' => [],
        'reports' => [
            'patients_without_upcoming' => [],
            'recent_cancellations' => [],
            'pending_payments' => []
        ]
    ];

    $res = $mysqli->query("SELECT COUNT(*) AS total FROM appointments WHERE status = 'booked' AND CONCAT(appointment_date, ' ', appointment_time) >= NOW() $appointment_filter");
    if ($row = $res->fetch_assoc()) {
        $stats['upcoming_count'] = (int) $row['total'];
    }

    $res = $mysqli->query("SELECT COUNT(*) AS total FROM appointments WHERE status = 'booked' AND appointment_date = CURDATE() $appointment_filter");
    if ($row = $res->fetch_assoc()) {
        $stats['today_count'] = (int) $row['total'];
    }

    $res = $mysqli->query("
        SELECT COUNT(*) AS total
        FROM appointments
        WHERE status = 'booked'
          AND appointment_date >= DATE_FORMAT(CURDATE(), '%Y-%m-01')
          AND appointment_date < DATE_ADD(DATE_FORMAT(CURDATE(), '%Y-%m-01'), INTERVAL 1 MONTH)
          $appointment_filter
    ");
    if ($row = $res->fetch_assoc()) {
        $stats['month_count'] = (int) $row['total'];
    }

    $res = $mysqli->query("
        SELECT COUNT(DISTINCT u.id) AS total
        FROM users u
        $patient_join
        WHERE u.tenant_id = $tenant_id
          AND u.role = 'patient'
          $patient_filter
    ");
    if ($row = $res->fetch_assoc()) {
        $stats['patient_count'] = (int) $row['total'];
    }

    $res = $mysqli->query("
        SELECT COALESCE(SUM(amount_cents), 0) AS cents
        FROM payment_attempts
        WHERE tenant_id = $tenant_id
          AND status = 'OK'
          AND created_at >= DATE_FORMAT(CURDATE(), '%Y-%m-01')
          AND created_at < DATE_ADD(DATE_FORMAT(CURDATE(), '%Y-%m-01'), INTERVAL 1 MONTH)
          " . ($professional_id > 0 ? " AND professional_id = " . (int) $professional_id : ($professional_id < 0 ? " AND 1 = 0" : "")) . "
    ");
    if ($row = $res->fetch_assoc()) {
        $stats['online_revenue_month'] = number_format(((int) $row['cents']) / 100, 2, '.', '');
    }

    $res = $mysqli->query("
        SELECT COALESCE(payment_method, 'pending') AS payment_method, COUNT(*) AS total
        FROM appointments
        WHERE status = 'booked'
          AND COALESCE(payment_status, 'pending') <> 'paid'
          AND appointment_date >= DATE_FORMAT(CURDATE(), '%Y-%m-01')
          AND appointment_date < DATE_ADD(DATE_FORMAT(CURDATE(), '%Y-%m-01'), INTERVAL 1 MONTH)
          $appointment_filter
        GROUP BY COALESCE(payment_method, 'pending')
    ");
    while ($row = $res->fetch_assoc()) {
        $stats['pending_payment_count'] += (int) $row['total'];
    }

    $res = $mysqli->query("
        SELECT COALESCE(a.payment_method, 'manual') AS payment_method,
               COALESCE(SUM(COALESCE(aso.price, 0)), 0) AS amount
        FROM appointments a
        LEFT JOIN appointment_service_options aso ON aso.id = a.service_option_id AND aso.tenant_id = a.tenant_id
        WHERE a.status = 'booked'
          AND COALESCE(a.payment_status, 'pending') = 'paid'
          AND a.appointment_date >= DATE_FORMAT(CURDATE(), '%Y-%m-01')
          AND a.appointment_date < DATE_ADD(DATE_FORMAT(CURDATE(), '%Y-%m-01'), INTERVAL 1 MONTH)
          $appointment_filter_a
        GROUP BY COALESCE(a.payment_method, 'manual')
    ");
    while ($row = $res->fetch_assoc()) {
        $method = $row['payment_method'] ?: 'manual';
        if (array_key_exists($method, $stats['payment_revenue_month'])) {
            $stats['payment_revenue_month'][$method] = number_format((float) $row['amount'], 2, '.', '');
        }
    }

    $res = $mysqli->query("
        SELECT COUNT(*) AS total, COALESCE(SUM(remaining_sessions), 0) AS sessions
        FROM patient_bonuses
        WHERE tenant_id = $tenant_id
          AND status = 'active'
          AND remaining_sessions > 0
          AND (expires_at IS NULL OR expires_at >= CURDATE())
          " . ($professional_id > 0 ? " AND professional_id = " . (int) $professional_id : ($professional_id < 0 ? " AND 1 = 0" : "")) . "
    ");
    if ($row = $res->fetch_assoc()) {
        $stats['active_bonus_count'] = (int) $row['total'];
        $stats['active_bonus_sessions'] = (int) $row['sessions'];
    }

    $res = $mysqli->query("
        SELECT age_group label, COUNT(*) total
        FROM (
            SELECT CASE
                WHEN pp.birth_date IS NULL THEN 'Sin indicar'
                WHEN TIMESTAMPDIFF(YEAR, pp.birth_date, CURDATE()) < 18 THEN 'Menos de 18'
                WHEN TIMESTAMPDIFF(YEAR, pp.birth_date, CURDATE()) BETWEEN 18 AND 29 THEN '18-29'
                WHEN TIMESTAMPDIFF(YEAR, pp.birth_date, CURDATE()) BETWEEN 30 AND 44 THEN '30-44'
                WHEN TIMESTAMPDIFF(YEAR, pp.birth_date, CURDATE()) BETWEEN 45 AND 59 THEN '45-59'
                ELSE '60 o más'
            END age_group
            FROM users u
            $patient_join
            WHERE u.tenant_id = $tenant_id AND u.role = 'patient' $patient_filter
        ) age_rows
        GROUP BY age_group
        ORDER BY FIELD(age_group, 'Menos de 18', '18-29', '30-44', '45-59', '60 o más', 'Sin indicar')
    ");
    while ($row = $res->fetch_assoc()) $stats['patients_by_age'][] = ['label' => $row['label'], 'value' => (int) $row['total']];

    $res = $mysqli->query("
        SELECT COALESCE(pp.patient_status, 'active') status_key, COUNT(DISTINCT u.id) total
        FROM users u
        $patient_join
        WHERE u.tenant_id = $tenant_id AND u.role = 'patient' $patient_filter
        GROUP BY COALESCE(pp.patient_status, 'active')
    ");
    $status_labels = ['active' => 'Activo', 'paused' => 'En pausa', 'discharged' => 'Alta', 'inactive' => 'Baja'];
    while ($row = $res->fetch_assoc()) $stats['patients_by_status'][] = ['label' => $status_labels[$row['status_key']] ?? ucfirst((string) $row['status_key']), 'value' => (int) $row['total']];

    $res = $mysqli->query("
        SELECT COALESCE(NULLIF(s.name, ''), 'Sin servicio') label, COUNT(*) total
        FROM appointments a
        LEFT JOIN appointment_service_options aso ON aso.id=a.service_option_id AND aso.tenant_id=a.tenant_id
        LEFT JOIN appointment_services s ON s.id=aso.service_id AND s.tenant_id=aso.tenant_id
        WHERE a.appointment_date >= DATE_SUB(CURDATE(), INTERVAL 12 MONTH) $appointment_filter_a
        GROUP BY COALESCE(NULLIF(s.name, ''), 'Sin servicio')
        ORDER BY total DESC LIMIT 10
    ");
    while ($row = $res->fetch_assoc()) $stats['sessions_by_service'][] = ['label' => $row['label'], 'value' => (int) $row['total']];

    $res = $mysqli->query("
        SELECT COALESCE(NULLIF(a.consultation_type, ''), 'presencial') type_key, COUNT(*) total
        FROM appointments a
        WHERE a.appointment_date >= DATE_SUB(CURDATE(), INTERVAL 12 MONTH) $appointment_filter_a
        GROUP BY COALESCE(NULLIF(a.consultation_type, ''), 'presencial')
    ");
    $communication_labels = ['presencial' => 'Presencial', 'online' => 'Videollamada', 'video' => 'Videollamada', 'domicilio' => 'A domicilio', 'home' => 'A domicilio'];
    while ($row = $res->fetch_assoc()) $stats['sessions_by_communication'][] = ['label' => $communication_labels[$row['type_key']] ?? ucfirst((string) $row['type_key']), 'value' => (int) $row['total']];

    $res = $mysqli->query("
        SELECT DATE_FORMAT(a.appointment_date, '%Y-%m') month_key, COUNT(*) total
        FROM appointments a
        WHERE a.appointment_date >= DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 11 MONTH), '%Y-%m-01') $appointment_filter_a
        GROUP BY DATE_FORMAT(a.appointment_date, '%Y-%m') ORDER BY month_key
    ");
    while ($row = $res->fetch_assoc()) $stats['sessions_by_month'][] = ['label' => $row['month_key'], 'value' => (int) $row['total']];

    $res = $mysqli->query("
        SELECT DATE_FORMAT(a.appointment_date, '%Y-%m') month_key,
               COALESCE(SUM(CASE WHEN COALESCE(a.payment_status,'pending')='paid' THEN COALESCE(aso.price,0) ELSE 0 END),0) collected,
               COALESCE(SUM(CASE WHEN COALESCE(a.payment_status,'pending')<>'paid' AND a.status='booked' THEN COALESCE(aso.price,0) ELSE 0 END),0) pending
        FROM appointments a
        LEFT JOIN appointment_service_options aso ON aso.id=a.service_option_id AND aso.tenant_id=a.tenant_id
        WHERE a.appointment_date >= DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 11 MONTH), '%Y-%m-01') $appointment_filter_a
        GROUP BY DATE_FORMAT(a.appointment_date, '%Y-%m') ORDER BY month_key
    ");
    while ($row = $res->fetch_assoc()) $stats['billing_by_month'][] = ['label' => $row['month_key'], 'collected' => (float) $row['collected'], 'pending' => (float) $row['pending']];

    $res = $mysqli->query("
        SELECT u.name, u.email, COUNT(*) AS sessions
        FROM appointments a
        JOIN users u ON u.id = a.user_id AND u.tenant_id = a.tenant_id
        WHERE a.status = 'booked'
          $appointment_filter_a
        GROUP BY a.user_id, u.name, u.email
        ORDER BY sessions DESC, u.name ASC
        LIMIT 5
    ");
    while ($row = $res->fetch_assoc()) {
        $stats['top_patients'][] = [
            'name' => $row['name'],
            'email' => $row['email'],
            'sessions' => (int) $row['sessions']
        ];
    }

    $res = $mysqli->query("
        SELECT u.id, u.name, u.email, u.phone,
               MAX(CASE WHEN a.status = 'booked' AND CONCAT(a.appointment_date, ' ', a.appointment_time) < NOW() THEN CONCAT(a.appointment_date, ' ', a.appointment_time) ELSE NULL END) AS last_appointment_at,
               SUM(CASE WHEN a.status = 'booked' AND CONCAT(a.appointment_date, ' ', a.appointment_time) >= NOW() THEN 1 ELSE 0 END) AS future_count
        FROM users u
        $patient_join
        LEFT JOIN appointments a ON a.user_id = u.id AND a.tenant_id = u.tenant_id
        WHERE u.tenant_id = $tenant_id
          AND u.role = 'patient'
          $patient_filter
        GROUP BY u.id, u.name, u.email, u.phone
        HAVING future_count = 0
        ORDER BY last_appointment_at IS NULL ASC, last_appointment_at DESC, u.name ASC
        LIMIT 10
    ");
    while ($row = $res->fetch_assoc()) {
        $stats['reports']['patients_without_upcoming'][] = [
            'patient_id' => (int) $row['id'],
            'name' => $row['name'],
            'email' => $row['email'],
            'phone' => member_patient_phone($row['phone'] ?? ''),
            'last_appointment_at' => $row['last_appointment_at'] ?? ''
        ];
    }

    $res = $mysqli->query("
        SELECT a.id, a.appointment_date, a.appointment_time, a.cancelled_at,
               COALESCE(a.duration_minutes, so.duration_minutes, 60) AS duration_minutes,
               s.name AS service_name,
               u.name AS patient_name, u.email AS patient_email, u.phone AS patient_phone,
               p.display_name AS professional_name
        FROM appointments a
        LEFT JOIN appointment_service_options so ON so.id = a.service_option_id AND so.tenant_id = a.tenant_id
        LEFT JOIN appointment_services s ON s.id = so.service_id AND s.tenant_id = a.tenant_id
        JOIN users u ON u.id = a.user_id AND u.tenant_id = a.tenant_id
        LEFT JOIN professionals p ON p.id = a.professional_id AND p.tenant_id = a.tenant_id
        WHERE a.status = 'cancelled'
          AND COALESCE(a.cancelled_at, CONCAT(a.appointment_date, ' ', a.appointment_time)) >= DATE_SUB(NOW(), INTERVAL 30 DAY)
          $appointment_filter_a
        ORDER BY COALESCE(a.cancelled_at, CONCAT(a.appointment_date, ' ', a.appointment_time)) DESC
        LIMIT 10
    ");
    while ($row = $res->fetch_assoc()) {
        $stats['reports']['recent_cancellations'][] = [
            'id' => (int) $row['id'],
            'appointment_date' => $row['appointment_date'],
            'appointment_time' => substr((string) $row['appointment_time'], 0, 5),
            'cancelled_at' => $row['cancelled_at'] ?? '',
            'patient_name' => $row['patient_name'],
            'patient_email' => $row['patient_email'],
            'patient_phone' => member_patient_phone($row['patient_phone'] ?? ''),
            'professional_name' => $row['professional_name'] ?? '',
            'service_label' => appointment_service_option_label($row),
            'duration_minutes' => (int) ($row['duration_minutes'] ?? 60)
        ];
    }

    $res = $mysqli->query("
        SELECT a.id, a.appointment_date, a.appointment_time, a.consultation_type, a.service_type,
               COALESCE(a.duration_minutes, so.duration_minutes, 60) AS duration_minutes,
               COALESCE(a.payment_status, 'pending') AS payment_status,
               a.payment_method,
               s.name AS service_name,
               u.name AS patient_name, u.email AS patient_email, u.phone AS patient_phone,
               p.display_name AS professional_name
        FROM appointments a
        LEFT JOIN appointment_service_options so ON so.id = a.service_option_id AND so.tenant_id = a.tenant_id
        LEFT JOIN appointment_services s ON s.id = so.service_id AND s.tenant_id = a.tenant_id
        JOIN users u ON u.id = a.user_id AND u.tenant_id = a.tenant_id
        LEFT JOIN professionals p ON p.id = a.professional_id AND p.tenant_id = a.tenant_id
        WHERE a.status = 'booked'
          AND COALESCE(a.payment_status, 'pending') <> 'paid'
          $appointment_filter_a
        ORDER BY a.appointment_date ASC, a.appointment_time ASC
        LIMIT 10
    ");
    while ($row = $res->fetch_assoc()) {
        $stats['reports']['pending_payments'][] = [
            'id' => (int) $row['id'],
            'appointment_date' => $row['appointment_date'],
            'appointment_time' => substr((string) $row['appointment_time'], 0, 5),
            'patient_name' => $row['patient_name'],
            'patient_email' => $row['patient_email'],
            'patient_phone' => member_patient_phone($row['patient_phone'] ?? ''),
            'professional_name' => $row['professional_name'] ?? '',
            'service_label' => appointment_service_option_label($row),
            'consultation_type' => $row['consultation_type'] ?? 'presencial',
            'payment_status' => $row['payment_status'] ?? 'pending',
            'payment_method' => $row['payment_method'] ?? ''
        ];
    }

    if ($is_superadmin) {
        $res = $mysqli->query("
            SELECT p.id, p.display_name, p.public_photo_path, u.role AS user_role,
                   COUNT(DISTINCT COALESCE(ppf.patient_id, pp.user_id)) AS patient_count,
                   COUNT(DISTINCT CASE WHEN a.status = 'booked' AND CONCAT(a.appointment_date, ' ', a.appointment_time) >= NOW() THEN a.id END) AS upcoming_count
            FROM professionals p
            LEFT JOIN users u ON u.id = p.user_id AND u.tenant_id = p.tenant_id
            LEFT JOIN patient_professionals ppf ON ppf.professional_id = p.id AND ppf.tenant_id = p.tenant_id AND ppf.is_primary = 1
            LEFT JOIN patient_profiles pp ON pp.professional_id = p.id AND pp.tenant_id = p.tenant_id
            LEFT JOIN appointments a ON a.professional_id = p.id AND a.tenant_id = p.tenant_id
            WHERE p.tenant_id = $tenant_id
              AND p.is_active = 1
              AND u.role IN ('superadmin', 'admin')
            GROUP BY p.id, p.display_name, p.public_photo_path, u.role
            ORDER BY CASE WHEN u.role = 'superadmin' THEN 0 ELSE 1 END ASC,
                     p.sort_order ASC,
                     p.display_name ASC
        ");
        while ($row = $res->fetch_assoc()) {
            $photo_path = professional_photo_with_dashboard_fallback($row, $dashboard_photo);
            $stats['professional_summary'][] = [
                'id' => (int) $row['id'],
                'display_name' => $row['display_name'],
                'public_photo_path' => $photo_path,
                'patient_count' => (int) $row['patient_count'],
                'upcoming_count' => (int) $row['upcoming_count']
            ];
        }
    }

    echo json_encode(['success' => true, 'stats' => $stats]);
} elseif ($action === 'list_closed_days') {
    ensure_action_feature($mysqli, 'closures.enabled', 'Los cierres y vacaciones no estan disponibles en este plan.');
    ensure_cabinet_schema($mysqli);
    $branding = get_public_branding_settings($mysqli);
    $dashboard_photo = $branding['profile_image_path'] ?? '';
    $current_professional_id = current_professional_id_for_user($mysqli, (int) ($_SESSION['user_id'] ?? 0));
    $effective_professional_expr = "CASE WHEN cd.is_global = 0 AND cd.professional_id IS NULL THEN " . (int) $current_professional_id . " ELSE cd.professional_id END";
    $where = $is_superadmin
        ? "1 = 1"
        : "($effective_professional_expr = " . (int) $current_professional_id . " OR cd.is_global = 1)";
    $res = $mysqli->query("
        SELECT cd.*, $effective_professional_expr AS effective_professional_id,
               p.display_name AS professional_name, p.public_photo_path AS professional_photo_path,
               pu.role AS professional_user_role
        FROM closed_days cd
        LEFT JOIN professionals p ON p.id = $effective_professional_expr AND p.tenant_id = cd.tenant_id
        LEFT JOIN users pu ON pu.id = p.user_id AND pu.tenant_id = p.tenant_id
        WHERE cd.tenant_id = $tenant_id
          AND cd.closed_date >= CURDATE()
          AND $where
        ORDER BY cd.closed_date ASC, cd.is_global DESC, p.sort_order ASC, p.display_name ASC
    ");
    $days = [];
    while ($row = $res->fetch_assoc()) {
        $row['professional_id'] = (int) ($row['effective_professional_id'] ?? 0);
        $row['professional_photo_path'] = professional_photo_with_dashboard_fallback($row, $dashboard_photo);
        $row['can_delete'] = $is_superadmin
            || ((int) ($row['is_global'] ?? 0) === 0
                && $current_professional_id > 0
                && (int) ($row['professional_id'] ?? 0) === $current_professional_id);
        $days[] = $row;
    }
    echo json_encode(['success' => true, 'days' => $days, 'show_professionals' => $is_superadmin ? 1 : 0]);
} elseif ($action === 'add_closed_day') {
    ensure_action_feature($mysqli, 'closures.enabled', 'Los cierres y vacaciones no estan disponibles en este plan.');
    $date = $_POST['date'] ?? ($_POST['start_date'] ?? '');
    $end_date = $_POST['end_date'] ?? $date;
    $reason = $_POST['reason'] ?? 'Descanso';
    $is_global = ($is_superadmin && isset($_POST['is_global']) && $_POST['is_global'] === '1') ? 1 : 0;
    $professional_id = $is_global ? null : current_professional_id_for_user($mysqli, (int) ($_SESSION['user_id'] ?? 0));
    if (!$date) {
        echo json_encode(['success' => false, 'error' => 'Fecha inválida']);
        exit;
    }

    if (!$end_date) {
        $end_date = $date;
    }

    try {
        $start = new DateTime($date);
        $end = new DateTime($end_date);
    } catch (\Exception $e) {
        echo json_encode(['success' => false, 'error' => 'Rango de fechas inválido']);
        exit;
    }

    if ($end < $start) {
        echo json_encode(['success' => false, 'error' => 'La fecha final no puede ser anterior a la inicial']);
        exit;
    }

    if ($start->diff($end)->days > 370) {
        echo json_encode(['success' => false, 'error' => 'El intervalo no puede superar 370 días']);
        exit;
    }

    try {
        $inserted = 0;
        $skipped = 0;
        $stmt = $mysqli->prepare("INSERT INTO closed_days (tenant_id, closed_date, professional_id, reason, is_global) VALUES (?, ?, ?, ?, ?)");
        $current = clone $start;

        while ($current <= $end) {
            $current_date = $current->format('Y-m-d');
            if ($is_global) {
                $exists_stmt = $mysqli->prepare("SELECT id FROM closed_days WHERE tenant_id = ? AND closed_date = ? AND is_global = 1 AND reason = ? LIMIT 1");
                $exists_stmt->bind_param("iss", $tenant_id, $current_date, $reason);
            } else {
                $exists_stmt = $mysqli->prepare("SELECT id FROM closed_days WHERE tenant_id = ? AND closed_date = ? AND is_global = 0 AND professional_id = ? AND reason = ? LIMIT 1");
                $exists_stmt->bind_param("isis", $tenant_id, $current_date, $professional_id, $reason);
            }
            $exists_stmt->execute();
            if ($exists_stmt->get_result()->fetch_assoc()) {
                $skipped++;
                $current->modify('+1 day');
                continue;
            }

            $stmt->bind_param("isisi", $tenant_id, $current_date, $professional_id, $reason, $is_global);
            $stmt->execute();

            $inserted++;

            $current->modify('+1 day');
        }

        // Also we might want to cancel existing appointments on that day, but for simplicity, we just block new ones
        // In a real scenario we could delete or mark them as cancelled. 
        echo json_encode(['success' => true, 'inserted' => $inserted, 'skipped' => $skipped]);
    } catch (\Exception $e) {
        // If duplicate
        echo json_encode(['success' => false, 'error' => 'No se pudo guardar el descanso.']);
    }
} elseif ($action === 'delete_closed_day') {
    ensure_action_feature($mysqli, 'closures.enabled', 'Los cierres y vacaciones no estan disponibles en este plan.');
    $id = (int) ($_POST['id'] ?? 0);
    if ($id <= 0) {
        echo json_encode(['success' => false, 'error' => 'Cierre no válido.']);
        exit;
    }
    if (!$is_superadmin) {
        $current_professional_id = current_professional_id_for_user($mysqli, (int) ($_SESSION['user_id'] ?? 0));
        $stmt = $mysqli->prepare("
            SELECT id
            FROM closed_days
            WHERE tenant_id = ?
              AND id = ?
              AND is_global = 0
              AND professional_id = ?
            LIMIT 1
        ");
        $stmt->bind_param("iii", $tenant_id, $id, $current_professional_id);
        $stmt->execute();
        if (!$stmt->get_result()->fetch_assoc()) {
            echo json_encode(['success' => false, 'error' => 'No tienes permiso para eliminar este cierre.']);
            exit;
        }
    }
    $stmt = $mysqli->prepare("DELETE FROM closed_days WHERE tenant_id = ? AND id = ?");
    $stmt->bind_param("ii", $tenant_id, $id);
    $stmt->execute();
    echo json_encode(['success' => true]);
} elseif ($action === 'delete_closed_range') {
    ensure_action_feature($mysqli, 'closures.enabled', 'Los cierres y vacaciones no estan disponibles en este plan.');
    $start_date = $_POST['start_date'] ?? '';
    $end_date = $_POST['end_date'] ?? $start_date;
    $reason = $_POST['reason'] ?? '';
    $is_global = isset($_POST['is_global']) && $_POST['is_global'] === '1' ? 1 : 0;
    $professional_id = isset($_POST['professional_id']) && $_POST['professional_id'] !== '' ? (int) $_POST['professional_id'] : 0;

    if (!$start_date || !$end_date || $reason === '') {
        echo json_encode(['success' => false, 'error' => 'Rango invalido']);
        exit;
    }

    if ($is_superadmin) {
        if ($is_global) {
            $stmt = $mysqli->prepare("DELETE FROM closed_days WHERE tenant_id = ? AND closed_date BETWEEN ? AND ? AND reason = ? AND is_global = 1");
            $stmt->bind_param("isss", $tenant_id, $start_date, $end_date, $reason);
        } elseif ($professional_id <= 0) {
            $stmt = $mysqli->prepare("DELETE FROM closed_days WHERE tenant_id = ? AND closed_date BETWEEN ? AND ? AND reason = ? AND is_global = 0 AND professional_id IS NULL");
            $stmt->bind_param("isss", $tenant_id, $start_date, $end_date, $reason);
        } else {
            $current_professional_id = current_professional_id_for_user($mysqli, (int) ($_SESSION['user_id'] ?? 0));
            $stmt = $mysqli->prepare("
                DELETE FROM closed_days
                WHERE tenant_id = ?
                  AND closed_date BETWEEN ? AND ?
                  AND reason = ?
                  AND is_global = 0
                  AND (professional_id = ? OR (professional_id IS NULL AND ? = ?))
            ");
            $stmt->bind_param("isssiii", $tenant_id, $start_date, $end_date, $reason, $professional_id, $professional_id, $current_professional_id);
        }
    } else {
        $current_professional_id = current_professional_id_for_user($mysqli, (int) ($_SESSION['user_id'] ?? 0));
        $stmt = $mysqli->prepare("DELETE FROM closed_days WHERE tenant_id = ? AND closed_date BETWEEN ? AND ? AND reason = ? AND is_global = 0 AND professional_id = ?");
        $stmt->bind_param("isssi", $tenant_id, $start_date, $end_date, $reason, $current_professional_id);
    }
    $stmt->execute();
    echo json_encode(['success' => true, 'deleted' => $stmt->affected_rows]);
} elseif ($action === 'save_last_calendar_view') {
    ensure_cabinet_schema($mysqli);
    $professional_id = current_professional_id_for_user($mysqli, (int) ($_SESSION['user_id'] ?? 0));
    $view = trim((string) ($_POST['view'] ?? ''));
    if ($professional_id <= 0 || !in_array($view, ['month', 'week', 'agenda', 'list'], true)) {
        echo json_encode(['success' => false, 'error' => 'No se pudo guardar la vista seleccionada.']);
        exit;
    }
    if (!cabinet_save_last_calendar_view($mysqli, $professional_id, $view)) {
        echo json_encode(['success' => false, 'error' => 'No se pudo guardar la vista seleccionada.']);
        exit;
    }
    echo json_encode(['success' => true]);
} elseif ($action === 'get_my_professional_profile') {
    ensure_cabinet_schema($mysqli);
    $professional_id = current_professional_id_for_user($mysqli, (int) ($_SESSION['user_id'] ?? 0));
    if ($professional_id <= 0) {
        echo json_encode(['success' => false, 'error' => 'No se pudo localizar tu ficha profesional.']);
        exit;
    }
    $knowledge_select = professional_knowledge_sector_columns_available($mysqli)
        ? "ps.knowledge_sector_mode, ps.knowledge_sector_keys_json"
        : "'own' AS knowledge_sector_mode, NULL AS knowledge_sector_keys_json";
    $stmt = $mysqli->prepare("
        SELECT p.id, p.user_id, p.display_name, p.professional_title, p.license_number, p.professional_college,
               p.professional_specialty, p.public_bio, p.public_photo_path, p.public_phone,
               p.instagram_url, p.facebook_url, p.tiktok_url, p.appointment_summary_email_mode,
               p.is_active, u.email, u.role,
               ps.available_session_types, ps.available_session_durations,
               ps.default_appointment_location, ps.default_location_id,
               ps.livekit_enabled, ps.video_provider,
               ps.livekit_recording_enabled, ps.livekit_recording_mode,
               $knowledge_select
        FROM professionals p
        INNER JOIN users u ON u.id = p.user_id AND u.tenant_id = p.tenant_id
        LEFT JOIN professional_settings ps ON ps.professional_id = p.id AND ps.tenant_id = p.tenant_id
        WHERE p.tenant_id = ? AND p.id = ? AND p.user_id = ?
        LIMIT 1
    ");
    $session_user_id = (int) ($_SESSION['user_id'] ?? 0);
    $stmt->bind_param('iii', $tenant_id, $professional_id, $session_user_id);
    $stmt->execute();
    $row = $stmt->get_result()->fetch_assoc();
    if (!$row) {
        echo json_encode(['success' => false, 'error' => 'No se pudo localizar tu ficha profesional.']);
        exit;
    }
    $effective = cabinet_get_effective_professional_settings($mysqli, $professional_id);
    foreach ($effective as $key => $value) {
        if (!array_key_exists($key, $row) || $row[$key] === null || $row[$key] === '') {
            $row[$key] = $value;
        }
    }
    $row = array_merge($row, cabinet_get_professional_preferences($mysqli, $professional_id));
    $row['id'] = (int) $row['id'];
    $row['user_id'] = (int) $row['user_id'];
    $row['default_location_id'] = (int) ($row['default_location_id'] ?? 0);
    $row['livekit_enabled'] = (int) ($row['livekit_enabled'] ?? 1);
    $row['livekit_recording_enabled'] = (int) ($row['livekit_recording_enabled'] ?? 0);
    $row['knowledge_sector_keys'] = normalize_knowledge_sector_keys($row['knowledge_sector_keys_json'] ?? '');
    $row['is_current_user'] = 1;
    echo json_encode(['success' => true, 'professional' => $row], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
} elseif ($action === 'save_my_professional_profile') {
    ensure_cabinet_schema($mysqli);
    $professional_id = current_professional_id_for_user($mysqli, (int) ($_SESSION['user_id'] ?? 0));
    $session_user_id = (int) ($_SESSION['user_id'] ?? 0);
    if ($professional_id <= 0) {
        echo json_encode(['success' => false, 'error' => 'No se pudo localizar tu ficha profesional.']);
        exit;
    }
    $payload = json_decode((string) ($_POST['professional'] ?? ''), true);
    if (!is_array($payload)) {
        echo json_encode(['success' => false, 'error' => 'Los datos de la ficha no son válidos.']);
        exit;
    }
    $display_name = trim((string) ($payload['display_name'] ?? ''));
    if ($display_name === '') {
        echo json_encode(['success' => false, 'error' => 'Indica tu nombre profesional.']);
        exit;
    }
    try {
        $title = trim((string) ($payload['professional_title'] ?? ''));
        $license = trim((string) ($payload['license_number'] ?? ''));
        $college = trim((string) ($payload['professional_college'] ?? ''));
        $specialty = trim((string) ($payload['professional_specialty'] ?? ''));
        $bio = trim((string) ($payload['public_bio'] ?? ''));
        $phone = trim((string) ($payload['public_phone'] ?? ''));
        $instagram = normalize_optional_url($payload['instagram_url'] ?? '', 'Instagram');
        $facebook = normalize_optional_url($payload['facebook_url'] ?? '', 'Facebook');
        $tiktok = normalize_optional_url($payload['tiktok_url'] ?? '', 'TikTok');
        $summary_mode = (string) ($payload['appointment_summary_email_mode'] ?? 'on_booking');
        if (!in_array($summary_mode, ['disabled', 'tomorrow_evening', 'today_morning', 'on_booking'], true)) {
            $summary_mode = 'on_booking';
        }
        if (!plan_feature_enabled_from_db($mysqli, 'reminders.patient24h', false)) {
            $summary_mode = 'disabled';
        }
        $session_types = normalize_available_session_types(explode(',', (string) ($payload['available_session_types'] ?? '')), $mysqli);
        $session_durations = normalize_available_session_durations(explode(',', (string) ($payload['available_session_durations'] ?? '')), $mysqli);
        $location_id = normalize_location_id($mysqli, $payload['default_location_id'] ?? 0);
        $location_text = trim((string) ($payload['default_appointment_location'] ?? ''));
        $plan_config = plan_config_for_key(dashboard_config_plan_key_from_db($mysqli));
        $livekit_allowed = plan_config_feature_enabled($plan_config, 'videoCalls.integrated', plan_config_feature_enabled($plan_config, 'livekit.enabled', false));
        $recording_allowed = plan_config_feature_enabled($plan_config, 'videoCalls.recordingAudio', plan_config_feature_enabled($plan_config, 'livekit.recording', false));
        $video_recording_allowed = plan_config_feature_enabled($plan_config, 'videoCalls.recordingVideo', false);
        $video_provider = strtolower(trim((string) ($payload['video_provider'] ?? 'daily')));
        if ($video_provider === 'livekit') $video_provider = 'daily';
        if (!$livekit_allowed || !in_array($video_provider, ['daily', 'manual'], true)) {
            $video_provider = 'manual';
        }
        $livekit_enabled = $video_provider === 'manual' ? 0 : 1;
        $recording_enabled = $livekit_enabled && $recording_allowed && !empty($payload['livekit_recording_enabled']) ? 1 : 0;
        $recording_mode = in_array($payload['livekit_recording_mode'] ?? 'audio', ['audio', 'audio_video'], true)
            ? $payload['livekit_recording_mode'] : 'audio';
        if (!$video_recording_allowed) $recording_mode = 'audio';

        $mysqli->begin_transaction();
        $stmt = $mysqli->prepare("
            UPDATE professionals
            SET display_name = ?, professional_title = ?, license_number = ?, professional_college = ?, professional_specialty = ?,
                public_bio = ?, public_phone = ?, instagram_url = ?, facebook_url = ?, tiktok_url = ?,
                appointment_summary_email_mode = ?
            WHERE tenant_id = ? AND id = ? AND user_id = ?
        ");
        $stmt->bind_param('sssssssssssiii', $display_name, $title, $license, $college, $specialty, $bio, $phone, $instagram, $facebook, $tiktok, $summary_mode, $tenant_id, $professional_id, $session_user_id);
        $stmt->execute();
        $stmt = $mysqli->prepare('UPDATE users SET name = ? WHERE tenant_id = ? AND id = ?');
        $stmt->bind_param('sii', $display_name, $tenant_id, $session_user_id);
        $stmt->execute();

        $effective = cabinet_get_effective_professional_settings($mysqli, $professional_id);
        $effective['available_session_types'] = $session_types;
        $effective['available_session_durations'] = $session_durations;
        $effective['default_appointment_location'] = $location_text;
        $effective['default_location_id'] = $location_id;
        $effective['livekit_enabled'] = $livekit_enabled;
        $effective['video_provider'] = $video_provider;
        $effective['livekit_recording_enabled'] = $recording_enabled;
        $effective['livekit_recording_mode'] = $recording_mode;
        if (!cabinet_upsert_professional_settings($mysqli, $professional_id, $effective)) {
            throw new RuntimeException('No se pudieron guardar tus preferencias profesionales.');
        }
        if (!cabinet_save_professional_preferences($mysqli, $professional_id, $payload)) {
            throw new RuntimeException('No se pudieron guardar tus preferencias personales.');
        }

        if (professional_knowledge_sector_columns_available($mysqli)) {
            $knowledge_mode = (string) ($payload['knowledge_sector_mode'] ?? 'own');
            if (!knowledge_multi_sector_enabled($mysqli) || !in_array($knowledge_mode, ['own', 'tenant', 'related', 'custom'], true)) {
                $knowledge_mode = 'own';
            }
            $knowledge_keys = normalize_knowledge_sector_keys($payload['knowledge_sector_keys'] ?? []);
            $knowledge_json = $knowledge_mode === 'custom'
                ? json_encode($knowledge_keys, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES)
                : null;
            $stmt = $mysqli->prepare('UPDATE professional_settings SET knowledge_sector_mode = ?, knowledge_sector_keys_json = ? WHERE tenant_id = ? AND professional_id = ?');
            $stmt->bind_param('ssii', $knowledge_mode, $knowledge_json, $tenant_id, $professional_id);
            $stmt->execute();
        }
        if (isset($_FILES['professional_photo']) && ($_FILES['professional_photo']['error'] ?? UPLOAD_ERR_NO_FILE) !== UPLOAD_ERR_NO_FILE) {
            $photo_path = save_uploaded_professional_photo($_FILES['professional_photo'], $professional_id);
            $stmt = $mysqli->prepare('UPDATE professionals SET public_photo_path = ? WHERE tenant_id = ? AND id = ? AND user_id = ?');
            $stmt->bind_param('siii', $photo_path, $tenant_id, $professional_id, $session_user_id);
            $stmt->execute();
        }
        $mysqli->commit();
        echo json_encode(['success' => true, 'message' => 'Ficha profesional guardada correctamente.']);
    } catch (Throwable $e) {
        $mysqli->rollback();
        echo json_encode(['success' => false, 'error' => $e->getMessage() ?: 'No se pudo guardar tu ficha profesional.']);
    }
} elseif ($action === 'get_cabinet_settings') {
    if (!$is_superadmin) {
        echo json_encode(['success' => false, 'error' => 'Solo el superadmin puede gestionar el equipo.']);
        exit;
    }
    ensure_payment_settings_table($mysqli);
    ensure_cabinet_schema($mysqli);

    $settings_res = $mysqli->query("SELECT show_team_public, allow_patient_transfer, new_patient_booking_mode, new_patient_fixed_professional_id FROM payment_settings WHERE tenant_id = $tenant_id");
    $settings = $settings_res ? $settings_res->fetch_assoc() : ['show_team_public' => 0, 'allow_patient_transfer' => 0, 'new_patient_booking_mode' => 'day_first', 'new_patient_fixed_professional_id' => null];
    $knowledge_columns_available = professional_knowledge_sector_columns_available($mysqli);
    $knowledge_settings_select = $knowledge_columns_available
        ? "ps.knowledge_sector_mode, ps.knowledge_sector_keys_json"
        : "'own' AS knowledge_sector_mode, NULL AS knowledge_sector_keys_json";
    $member_permissions_select = column_exists($mysqli, 'professional_settings', 'member_permissions_json')
        ? "ps.member_permissions_json"
        : "NULL AS member_permissions_json";
    $livekit_recording_settings_select = column_exists($mysqli, 'professional_settings', 'livekit_recording_enabled')
        ? "ps.livekit_recording_enabled, ps.livekit_recording_mode"
        : "0 AS livekit_recording_enabled, 'audio' AS livekit_recording_mode";
    $contract_hours_settings_select = column_exists($mysqli, 'professional_settings', 'contract_hours')
        ? "ps.contract_hours, ps.contract_hours_unit"
        : "NULL AS contract_hours, 'daily' AS contract_hours_unit";
    $res = $mysqli->query("
        SELECT p.id, p.user_id, p.display_name, p.professional_title, p.license_number, p.professional_college, p.professional_specialty, p.public_bio,
               p.public_photo_path, p.public_email, p.public_phone, p.instagram_url, p.facebook_url, p.tiktok_url,
               p.appointment_summary_email_mode,
               p.is_active, u.email AS login_email, u.role,
               ps.available_session_types, ps.available_session_durations, ps.default_appointment_location, ps.default_location_id, ps.livekit_enabled, ps.video_provider, $member_permissions_select,
               $livekit_recording_settings_select,
               $contract_hours_settings_select,
               $knowledge_settings_select
        FROM professionals p
        LEFT JOIN users u ON u.id = p.user_id AND u.tenant_id = p.tenant_id
        LEFT JOIN professional_settings ps ON ps.professional_id = p.id AND ps.tenant_id = p.tenant_id
        WHERE p.tenant_id = $tenant_id
        ORDER BY p.sort_order ASC, p.display_name ASC
    ");
    $professionals = [];
    while ($row = $res->fetch_assoc()) {
        $is_current_user = (int) ($row['user_id'] ?? 0) === (int) ($_SESSION['user_id'] ?? 0) ? 1 : 0;
        $photo_path = $row['public_photo_path'] ?? '';
        $preferences = cabinet_get_professional_preferences($mysqli, (int) $row['id']);
        $professionals[] = array_merge([
            'id' => (int) $row['id'],
            'user_id' => (int) ($row['user_id'] ?? 0),
            'display_name' => $row['display_name'] ?? '',
            'professional_title' => $row['professional_title'] ?? '',
            'license_number' => $row['license_number'] ?? '',
            'professional_college' => $row['professional_college'] ?? '',
            'professional_specialty' => $row['professional_specialty'] ?? '',
            'public_bio' => $row['public_bio'] ?? '',
            'public_photo_path' => $photo_path,
            'display_photo_path' => $photo_path,
            'email' => $row['login_email'] ?: ($row['public_email'] ?? ''),
            'public_phone' => $row['public_phone'] ?? '',
            'instagram_url' => $row['instagram_url'] ?? '',
            'facebook_url' => $row['facebook_url'] ?? '',
            'tiktok_url' => $row['tiktok_url'] ?? '',
            'appointment_summary_email_mode' => $row['appointment_summary_email_mode'] ?? 'on_booking',
            'contract_hours' => $row['contract_hours'] === null ? null : (float) $row['contract_hours'],
            'contract_hours_unit' => ($row['contract_hours_unit'] ?? 'daily') === 'weekly' ? 'weekly' : 'daily',
            'available_session_types' => $row['available_session_types'] ?? '',
            'available_session_durations' => $row['available_session_durations'] ?? '',
            'default_appointment_location' => $row['default_appointment_location'] ?? '',
            'default_location_id' => (int) ($row['default_location_id'] ?? 0),
            'livekit_enabled' => (int) ($row['livekit_enabled'] ?? 1),
            'video_provider' => (string) ($row['video_provider'] ?? (!empty($row['livekit_enabled']) ? 'daily' : 'manual')),
            'livekit_recording_enabled' => (int) ($row['livekit_recording_enabled'] ?? 0),
            'livekit_recording_mode' => in_array($row['livekit_recording_mode'] ?? 'audio', ['audio', 'audio_video'], true) ? $row['livekit_recording_mode'] : 'audio',
            'knowledge_sector_mode' => in_array($row['knowledge_sector_mode'] ?? 'own', ['own', 'tenant', 'related', 'custom'], true) ? $row['knowledge_sector_mode'] : 'own',
            'knowledge_sector_keys' => normalize_knowledge_sector_keys($row['knowledge_sector_keys_json'] ?? ''),
            'role' => in_array($row['role'] ?? 'admin', ['superadmin', 'admin', 'reception', 'administration', 'technical'], true) ? $row['role'] : 'admin',
            'member_permissions' => cabinet_normalize_member_permissions($row['member_permissions_json'] ?? null, $row['role'] ?? 'admin'),
            'is_active' => (int) ($row['is_active'] ?? 1),
            'is_current_user' => $is_current_user
        ], $preferences);
    }

    $team_limit_config = plan_config_for_key(dashboard_config_plan_key_from_db($mysqli));
    echo json_encode([
        'success' => true,
        'settings' => $settings,
        'professionals' => $professionals,
        'limits' => [
            'teamMembers' => plan_config_limit_value($team_limit_config, 'teamMembers', null)
        ]
    ]);
} elseif ($action === 'knowledge_sector_options') {
    if (!app_feature_enabled_from_db($mysqli, 'knowledgeBase.enabled', false)) {
        echo json_encode(['success' => true, 'enabled' => false, 'multi_sector_enabled' => false, 'sectors' => []]);
        exit;
    }
    $main_sector = current_knowledge_sector_key($mysqli);
    $available = available_knowledge_sectors($mysqli);
    $available_keys = array_column($available, 'key');
    if (!in_array($main_sector, $available_keys, true)) {
        $labels = knowledge_sector_label_map();
        $available[] = [
            'key' => $main_sector,
            'name' => $labels[$main_sector] ?? ucfirst(str_replace(['_', '-'], ' ', $main_sector)),
            'total' => 0
        ];
    }
    $related = array_values(array_filter(knowledge_related_sector_presets()[$main_sector] ?? [], static function ($key) use ($available_keys) {
        return in_array($key, $available_keys, true);
    }));
    echo json_encode([
        'success' => true,
        'enabled' => true,
        'multi_sector_enabled' => knowledge_multi_sector_enabled($mysqli),
        'main_sector' => $main_sector,
        'tenant_sectors' => tenant_knowledge_sector_keys($mysqli),
        'related_sectors' => $related,
        'sectors' => $available
    ]);
} elseif ($action === 'check_professional_delete') {
    ensure_action_feature($mysqli, 'team.enabled', 'El equipo de trabajo no esta disponible en este plan.');
    if (!$is_superadmin) {
        echo json_encode(['success' => false, 'error' => 'Solo el superadmin puede gestionar el equipo.']);
        exit;
    }
    ensure_cabinet_schema($mysqli);

    $professional_id = (int) ($_POST['professional_id'] ?? 0);
    if ($professional_id <= 0) {
        echo json_encode(['success' => false, 'error' => 'Miembro invalido.']);
        exit;
    }

    $stmt = $mysqli->prepare("SELECT id, user_id, display_name FROM professionals WHERE tenant_id = ? AND id = ? LIMIT 1");
    $stmt->bind_param("ii", $tenant_id, $professional_id);
    $stmt->execute();
    $professional = $stmt->get_result()->fetch_assoc();
    if (!$professional) {
        echo json_encode(['success' => false, 'error' => 'No se encontro el miembro del equipo.']);
        exit;
    }
    if ((int) ($professional['user_id'] ?? 0) === (int) ($_SESSION['user_id'] ?? 0)) {
        echo json_encode(['success' => false, 'error' => 'No puedes borrar tu propio usuario administrador.']);
        exit;
    }

    $stmt = $mysqli->prepare("SELECT COUNT(*) AS total FROM appointments WHERE tenant_id = ? AND professional_id = ? AND status <> 'cancelled' AND appointment_date >= CURDATE()");
    $stmt->bind_param("ii", $tenant_id, $professional_id);
    $stmt->execute();
    $pending_appointments = (int) ($stmt->get_result()->fetch_assoc()['total'] ?? 0);

    $stmt = $mysqli->prepare("
        SELECT COUNT(*) AS total FROM (
            SELECT user_id AS patient_id FROM patient_profiles WHERE tenant_id = ? AND professional_id = ?
            UNION
            SELECT patient_id FROM patient_professionals WHERE tenant_id = ? AND professional_id = ?
        ) assigned_patients
    ");
    $stmt->bind_param("iiii", $tenant_id, $professional_id, $tenant_id, $professional_id);
    $stmt->execute();
    $assigned_patients = (int) ($stmt->get_result()->fetch_assoc()['total'] ?? 0);

    $linked_records = 0;
    $tables_to_check = [
        'appointments',
        'closed_days',
        'invitations',
        'patient_profiles',
        'patient_bonuses',
        'payment_attempts',
        'appointment_services',
        'appointment_service_options',
        'appointment_bonuses'
    ];
    foreach ($tables_to_check as $table) {
        $exists = $mysqli->query("SHOW TABLES LIKE '" . $mysqli->real_escape_string($table) . "'");
        if (!$exists || $exists->num_rows === 0) {
            continue;
        }
        $stmt = $mysqli->prepare("SELECT COUNT(*) AS total FROM `$table` WHERE tenant_id = ? AND professional_id = ?");
        $stmt->bind_param("ii", $tenant_id, $professional_id);
        $stmt->execute();
        $linked_records += (int) ($stmt->get_result()->fetch_assoc()['total'] ?? 0);
    }
    $stmt = $mysqli->prepare("SELECT COUNT(*) AS total FROM patient_professionals WHERE tenant_id = ? AND professional_id = ?");
    $stmt->bind_param("ii", $tenant_id, $professional_id);
    $stmt->execute();
    $linked_records += (int) ($stmt->get_result()->fetch_assoc()['total'] ?? 0);

    $targets = [];
    $stmt = $mysqli->prepare("
        SELECT p.id, p.display_name
        FROM professionals p
        LEFT JOIN users u ON u.id = p.user_id AND u.tenant_id = p.tenant_id
        WHERE p.tenant_id = ?
          AND p.id <> ?
          AND p.is_active = 1
          AND u.role IN ('superadmin', 'admin')
        ORDER BY p.sort_order ASC, p.display_name ASC
    ");
    $stmt->bind_param("ii", $tenant_id, $professional_id);
    $stmt->execute();
    $target_res = $stmt->get_result();
    while ($row = $target_res->fetch_assoc()) {
        $targets[] = ['id' => (int) $row['id'], 'display_name' => $row['display_name']];
    }

    echo json_encode([
        'success' => true,
        'professional' => [
            'id' => (int) $professional['id'],
            'display_name' => $professional['display_name']
        ],
        'usage' => [
            'pending_appointments' => $pending_appointments,
            'assigned_patients' => $assigned_patients,
            'linked_records' => $linked_records,
            'requires_transfer' => $linked_records > 0 ? 1 : 0
        ],
        'targets' => $targets
    ]);
} elseif ($action === 'delete_professional') {
    ensure_action_feature($mysqli, 'team.enabled', 'El equipo de trabajo no esta disponible en este plan.');
    if (!$is_superadmin) {
        echo json_encode(['success' => false, 'error' => 'Solo el superadmin puede gestionar el equipo.']);
        exit;
    }
    ensure_cabinet_schema($mysqli);

    $professional_id = (int) ($_POST['professional_id'] ?? 0);
    if ($professional_id <= 0) {
        echo json_encode(['success' => false, 'error' => 'Miembro invalido.']);
        exit;
    }

    $stmt = $mysqli->prepare("
        SELECT p.user_id, p.display_name, u.role AS user_role
        FROM professionals p
        LEFT JOIN users u ON u.id = p.user_id AND u.tenant_id = p.tenant_id
        WHERE p.tenant_id = ?
          AND p.id = ?
        LIMIT 1
    ");
    $stmt->bind_param("ii", $tenant_id, $professional_id);
    $stmt->execute();
    $professional = $stmt->get_result()->fetch_assoc();
    if (!$professional) {
        echo json_encode(['success' => false, 'error' => 'No se encontro el miembro del equipo.']);
        exit;
    }
    if ((int) ($professional['user_id'] ?? 0) === (int) ($_SESSION['user_id'] ?? 0)) {
        echo json_encode(['success' => false, 'error' => 'No puedes borrar tu propio usuario administrador.']);
        exit;
    }
    if (($professional['user_role'] ?? '') === 'superadmin') {
        echo json_encode(['success' => false, 'error' => 'No se puede borrar el usuario superadmin.']);
        exit;
    }

    $target_professional_id = (int) ($_POST['target_professional_id'] ?? 0);
    $tables_to_transfer = [
        'appointments',
        'closed_days',
        'invitations',
        'patient_profiles',
        'patient_bonuses',
        'payment_attempts',
        'appointment_services',
        'appointment_service_options',
        'appointment_bonuses'
    ];

    $usage_total = 0;
    foreach ($tables_to_transfer as $table) {
        $exists = $mysqli->query("SHOW TABLES LIKE '" . $mysqli->real_escape_string($table) . "'");
        if (!$exists || $exists->num_rows === 0) {
            continue;
        }
        $stmt = $mysqli->prepare("SELECT COUNT(*) AS total FROM `$table` WHERE tenant_id = ? AND professional_id = ?");
        $stmt->bind_param("ii", $tenant_id, $professional_id);
        $stmt->execute();
        $usage_total += (int) ($stmt->get_result()->fetch_assoc()['total'] ?? 0);
    }

    $stmt = $mysqli->prepare("SELECT COUNT(*) AS total FROM patient_professionals WHERE tenant_id = ? AND professional_id = ?");
    $stmt->bind_param("ii", $tenant_id, $professional_id);
    $stmt->execute();
    $usage_total += (int) ($stmt->get_result()->fetch_assoc()['total'] ?? 0);

    if ($usage_total > 0) {
        if ($target_professional_id <= 0 || $target_professional_id === $professional_id) {
            echo json_encode(['success' => false, 'error' => 'Elige otro profesional para traspasar citas y registros asignados antes de borrar.']);
            exit;
        }
        $stmt = $mysqli->prepare("
            SELECT p.id
            FROM professionals p
            LEFT JOIN users u ON u.id = p.user_id AND u.tenant_id = p.tenant_id
            WHERE p.tenant_id = ?
              AND p.id = ?
              AND p.is_active = 1
              AND u.role IN ('superadmin', 'admin')
            LIMIT 1
        ");
        $stmt->bind_param("ii", $tenant_id, $target_professional_id);
        $stmt->execute();
        if (!$stmt->get_result()->fetch_assoc()) {
            echo json_encode(['success' => false, 'error' => 'El profesional de destino no es valido.']);
            exit;
        }
    }

    $password_setup_users = [];
    $photo_index = (int) ($_POST['professional_photo_index'] ?? -1);
    $mysqli->begin_transaction();
    try {
        if ($usage_total > 0) {
            foreach ($tables_to_transfer as $table) {
                $exists = $mysqli->query("SHOW TABLES LIKE '" . $mysqli->real_escape_string($table) . "'");
                if (!$exists || $exists->num_rows === 0) {
                    continue;
                }
                $stmt = $mysqli->prepare("UPDATE `$table` SET professional_id = ? WHERE tenant_id = ? AND professional_id = ?");
                $stmt->bind_param("iii", $target_professional_id, $tenant_id, $professional_id);
                $stmt->execute();
            }

            $stmt = $mysqli->prepare("
                INSERT IGNORE INTO patient_professionals (tenant_id, patient_id, professional_id, is_primary, assigned_at, transferred_at, notes)
                SELECT tenant_id, patient_id, ?, is_primary, assigned_at, NOW(), notes
                FROM patient_professionals
                WHERE tenant_id = ? AND professional_id = ?
            ");
            $stmt->bind_param("iii", $target_professional_id, $tenant_id, $professional_id);
            $stmt->execute();

            $stmt = $mysqli->prepare("DELETE FROM patient_professionals WHERE tenant_id = ? AND professional_id = ?");
            $stmt->bind_param("ii", $tenant_id, $professional_id);
            $stmt->execute();
        }

        $stmt = $mysqli->prepare("DELETE FROM professionals WHERE tenant_id = ? AND id = ?");
        $stmt->bind_param("ii", $tenant_id, $professional_id);
        $stmt->execute();

        $stmt = $mysqli->prepare("DELETE FROM professional_settings WHERE tenant_id = ? AND professional_id = ?");
        $stmt->bind_param("ii", $tenant_id, $professional_id);
        $stmt->execute();

        $linked_user_id = (int) ($professional['user_id'] ?? 0);
        if ($linked_user_id > 0 && in_array($professional['user_role'] ?? '', ['admin', 'reception', 'administration', 'technical'], true)) {
            $password_resets_exists = $mysqli->query("SHOW TABLES LIKE 'password_resets'");
            if ($password_resets_exists && $password_resets_exists->num_rows > 0) {
                $stmt = $mysqli->prepare("DELETE FROM password_resets WHERE tenant_id = ? AND user_id = ?");
                $stmt->bind_param("ii", $tenant_id, $linked_user_id);
                $stmt->execute();
            }
            $stmt = $mysqli->prepare("DELETE FROM users WHERE tenant_id = ? AND id = ? AND role IN ('admin', 'reception', 'administration', 'technical')");
            $stmt->bind_param("ii", $tenant_id, $linked_user_id);
            $stmt->execute();
        }

        $mysqli->commit();
        echo json_encode(['success' => true, 'message' => $usage_total > 0 ? 'Traspaso realizado, miembro y cuenta de acceso borrados correctamente.' : 'Miembro y cuenta de acceso borrados correctamente.']);
    } catch (\Exception $e) {
        $mysqli->rollback();
        echo json_encode(['success' => false, 'error' => $e->getMessage()]);
    }
} elseif ($action === 'save_cabinet_settings') {
    ensure_action_feature($mysqli, 'team.enabled', 'El equipo de trabajo no esta disponible en este plan.');
    if (!$is_superadmin) {
        echo json_encode(['success' => false, 'error' => 'Solo el superadmin puede gestionar el equipo.']);
        exit;
    }
    ensure_payment_settings_table($mysqli);
    ensure_cabinet_schema($mysqli);
    admin_ensure_password_reset_table($mysqli);
    $cabinet_plan_config = plan_config_for_key(dashboard_config_plan_key_from_db($mysqli));
    $cabinet_plan_allows_livekit = plan_config_feature_enabled($cabinet_plan_config, 'videoCalls.integrated', plan_config_feature_enabled($cabinet_plan_config, 'livekit.enabled', false));
    $cabinet_plan_allows_livekit_recording = plan_config_feature_enabled($cabinet_plan_config, 'videoCalls.recordingAudio', plan_config_feature_enabled($cabinet_plan_config, 'livekit.recording', false));
    $cabinet_plan_allows_video_recording = plan_config_feature_enabled($cabinet_plan_config, 'videoCalls.recordingVideo', false);
    $cabinet_plan_allows_member_types = plan_config_feature_enabled($cabinet_plan_config, 'team.memberTypes', false);
    $cabinet_plan_allows_member_permissions = plan_config_feature_enabled($cabinet_plan_config, 'team.permissions', false);

    $show_team_public = isset($_POST['show_team_public']) && $_POST['show_team_public'] === '1' ? 1 : 0;
    $allow_patient_transfer = isset($_POST['allow_patient_transfer']) && $_POST['allow_patient_transfer'] === '1' ? 1 : 0;
    $new_patient_booking_mode = $_POST['new_patient_booking_mode'] ?? 'day_first';
    if (!in_array($new_patient_booking_mode, ['day_first', 'professional_first', 'fixed_professional'], true)) {
        $new_patient_booking_mode = 'day_first';
    }
    $new_patient_fixed_professional_id = (int) ($_POST['new_patient_fixed_professional_id'] ?? 0);
    if ($new_patient_booking_mode !== 'fixed_professional') {
        $new_patient_fixed_professional_id = 0;
    } elseif ($new_patient_fixed_professional_id <= 0) {
        $new_patient_fixed_professional_id = cabinet_superadmin_professional_id($mysqli);
        if ($new_patient_fixed_professional_id <= 0) {
            echo json_encode(['success' => false, 'error' => 'No se pudo localizar el profesional administrador para derivar nuevos registros.']);
            exit;
        }
    } else {
        $stmt = $mysqli->prepare("
            SELECT p.id
            FROM professionals p
            LEFT JOIN users u ON u.id = p.user_id AND u.tenant_id = p.tenant_id
            WHERE p.tenant_id = ?
              AND p.id = ?
              AND p.is_active = 1
              AND u.role IN ('superadmin', 'admin')
            LIMIT 1
        ");
        $stmt->bind_param("ii", $tenant_id, $new_patient_fixed_professional_id);
        $stmt->execute();
        if (!$stmt->get_result()->fetch_assoc()) {
            echo json_encode(['success' => false, 'error' => 'El profesional de derivacion no esta activo o no existe.']);
            exit;
        }
    }
    $professionals = json_decode($_POST['professionals_json'] ?? '[]', true);
    if (!is_array($professionals)) {
        echo json_encode(['success' => false, 'error' => 'Listado de profesionales invalido.']);
        exit;
    }
    $team_limit_config = plan_config_for_key(dashboard_config_plan_key_from_db($mysqli));
    $team_member_limit = plan_config_limit_value($team_limit_config, 'teamMembers', null);
    if ($team_member_limit !== null && (int) $team_member_limit > 0) {
        $team_member_limit = max(1, (int) $team_member_limit);
        $team_members = 0;
        foreach ($professionals as $professional) {
            $team_members++;
        }
        if ($team_members > $team_member_limit) {
            $limit_text = $team_member_limit === 0
                ? 'Este plan no tiene limite de miembros del equipo.'
                : 'Este plan permite un maximo de ' . $team_member_limit . ' miembro' . ($team_member_limit === 1 ? '' : 's') . ' del equipo.';
            echo json_encode(['success' => false, 'error' => $limit_text]);
            exit;
        }
    }

    $photo_index = (int) ($_POST['professional_photo_index'] ?? -1);
    $password_setup_users = [];
    $planning_cron_message = '';
    $mysqli->begin_transaction();
    try {
        $mysqli->query("INSERT IGNORE INTO payment_settings (id, tenant_id, primary_color) VALUES ($tenant_id, $tenant_id, '#4285f4')");
        $stmt = $mysqli->prepare("
            INSERT INTO payment_settings (id, tenant_id, show_team_public, allow_patient_transfer, new_patient_booking_mode, new_patient_fixed_professional_id)
            VALUES (?, ?, ?, ?, ?, ?)
            ON DUPLICATE KEY UPDATE
                show_team_public = VALUES(show_team_public),
                allow_patient_transfer = VALUES(allow_patient_transfer),
                new_patient_booking_mode = VALUES(new_patient_booking_mode),
                new_patient_fixed_professional_id = VALUES(new_patient_fixed_professional_id)
        ");
        $fixed_professional_db = $new_patient_fixed_professional_id > 0 ? $new_patient_fixed_professional_id : null;
        $stmt->bind_param("iiiisi", $tenant_id, $tenant_id, $show_team_public, $allow_patient_transfer, $new_patient_booking_mode, $fixed_professional_db);
        $stmt->execute();

        foreach ($professionals as $index => $professional) {
            $professional_id = (int) ($professional['id'] ?? 0);
            $user_id = (int) ($professional['user_id'] ?? 0);
            $display_name = trim((string) ($professional['display_name'] ?? ''));
            $title = trim((string) ($professional['professional_title'] ?? ''));
            $license_number = trim((string) ($professional['license_number'] ?? ''));
            $professional_college = trim((string) ($professional['professional_college'] ?? ''));
            $specialty = trim((string) ($professional['professional_specialty'] ?? ''));
            $public_bio = trim((string) ($professional['public_bio'] ?? ''));
            $current_photo_path = trim((string) ($professional['public_photo_path'] ?? ''));
            $email = trim((string) ($professional['email'] ?? ''));
            $public_phone = trim((string) ($professional['public_phone'] ?? ''));
            $instagram_url = normalize_optional_url($professional['instagram_url'] ?? '', 'Instagram');
            $facebook_url = normalize_optional_url($professional['facebook_url'] ?? '', 'Facebook');
            $tiktok_url = normalize_optional_url($professional['tiktok_url'] ?? '', 'TikTok');
            $summary_mode = (string) ($professional['appointment_summary_email_mode'] ?? 'on_booking');
            if (!in_array($summary_mode, ['disabled', 'tomorrow_evening', 'today_morning', 'on_booking'], true)) {
                $summary_mode = 'on_booking';
            }
            if (!plan_feature_enabled_from_db($mysqli, 'reminders.patient24h', false)) {
                $summary_mode = 'disabled';
            }
            $contract_hours_raw = trim((string) ($professional['contract_hours'] ?? ''));
            $contract_hours = $contract_hours_raw === '' ? null : round((float) $contract_hours_raw, 2);
            if ($contract_hours !== null && ($contract_hours <= 0 || $contract_hours > 168)) {
                throw new \Exception('El numero de horas de contrato debe ser mayor que cero y no superar 168 horas.');
            }
            $contract_hours_unit = ($professional['contract_hours_unit'] ?? 'daily') === 'weekly' ? 'weekly' : 'daily';
            $professional_session_types = normalize_available_session_types(explode(',', (string) ($professional['available_session_types'] ?? '')), $mysqli);
            $professional_session_durations = normalize_available_session_durations(explode(',', (string) ($professional['available_session_durations'] ?? '')), $mysqli);
            $default_appointment_location = trim((string) ($professional['default_appointment_location'] ?? ''));
            $default_location_id = normalize_location_id($mysqli, $professional['default_location_id'] ?? 0);
            $video_provider = strtolower(trim((string) ($professional['video_provider'] ?? (!empty($professional['livekit_enabled']) ? 'daily' : 'manual'))));
            if ($video_provider === 'livekit') $video_provider = 'daily';
            if (!$cabinet_plan_allows_livekit || !in_array($video_provider, ['daily', 'manual'], true)) {
                $video_provider = 'manual';
            }
            $livekit_enabled = $video_provider === 'manual' ? 0 : 1;
            $livekit_recording_enabled = ($cabinet_plan_allows_livekit && $cabinet_plan_allows_livekit_recording && $livekit_enabled && !empty($professional['livekit_recording_enabled'])) ? 1 : 0;
            $livekit_recording_mode = (string) ($professional['livekit_recording_mode'] ?? 'audio');
            if (!in_array($livekit_recording_mode, ['audio', 'audio_video'], true)) {
                $livekit_recording_mode = 'audio';
            }
            if (!$cabinet_plan_allows_video_recording) $livekit_recording_mode = 'audio';
            $knowledge_sector_mode = (string) ($professional['knowledge_sector_mode'] ?? 'own');
            if (!knowledge_multi_sector_enabled($mysqli) || !in_array($knowledge_sector_mode, ['own', 'tenant', 'related', 'custom'], true)) {
                $knowledge_sector_mode = 'own';
            }
            $knowledge_sector_keys = normalize_knowledge_sector_keys($professional['knowledge_sector_keys'] ?? []);
            $available_knowledge_keys = array_column(available_knowledge_sectors($mysqli), 'key');
            $main_knowledge_sector = current_knowledge_sector_key($mysqli);
            $knowledge_sector_keys = array_values(array_unique(array_filter(array_merge([$main_knowledge_sector], $knowledge_sector_keys), static function ($key) use ($available_knowledge_keys, $main_knowledge_sector) {
                return $key === $main_knowledge_sector || in_array($key, $available_knowledge_keys, true);
            })));
            $knowledge_sector_keys_json = $knowledge_sector_mode === 'custom' ? json_encode($knowledge_sector_keys, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) : null;
            $role = (string) ($professional['role'] ?? 'admin');
            if (!in_array($role, ['superadmin', 'admin', 'reception', 'administration', 'technical'], true)) {
                $role = 'admin';
            }
            if (!$cabinet_plan_allows_member_types && $role !== 'superadmin') {
                $role = 'admin';
            }
            $member_permissions_source = $cabinet_plan_allows_member_permissions
                ? ($professional['member_permissions'] ?? [])
                : cabinet_default_member_permissions_for_role($role);
            $member_permissions_json = cabinet_member_permissions_json($member_permissions_source, $role);
            $is_active = !empty($professional['is_active']) ? 1 : 0;

            if ($display_name === '') {
                throw new \Exception('Hay un miembro sin nombre.');
            }
            if ($email === '' || !filter_var($email, FILTER_VALIDATE_EMAIL)) {
                throw new \Exception('Hay un miembro sin email valido.');
            }

            $stmt = $mysqli->prepare("
                SELECT id, role, password_hash
                FROM users
                WHERE tenant_id = ? AND email = ?
                LIMIT 1
            ");
            $stmt->bind_param("is", $tenant_id, $email);
            $stmt->execute();
            $email_owner = $stmt->get_result()->fetch_assoc();
            $preserve_legacy_patient_account = $email_owner
                && ($email_owner['role'] ?? '') === 'patient'
                && $professional_id > 0
                && $user_id > 0
                && (int) $email_owner['id'] === $user_id;
            if ($email_owner && ($email_owner['role'] ?? '') === 'patient') {
                if (!$preserve_legacy_patient_account) {
                    throw new \Exception(
                        'Ese email ya pertenece a un paciente del centro. '
                        . 'No se puede convertir una cuenta de paciente en miembro del equipo.'
                    );
                }
            }
            if ($email_owner && (int) $email_owner['id'] !== $user_id) {
                if ($user_id > 0) {
                    throw new \Exception('Ese email ya pertenece a otro miembro del equipo.');
                }
            }

            if ($user_id <= 0) {
                $existing_user = $email_owner;
                if ($existing_user) {
                    $user_id = (int) $existing_user['id'];
                    if (empty($existing_user['password_hash'])) {
                        $password_setup_users[$user_id] = ['name' => $display_name, 'email' => $email];
                    }
                } else {
                    $stmt = $mysqli->prepare("INSERT INTO users (tenant_id, name, email, phone, password_hash, role) VALUES (?, ?, ?, NULL, NULL, ?)");
                    $stmt->bind_param("isss", $tenant_id, $display_name, $email, $role);
                    $stmt->execute();
                    $user_id = $mysqli->insert_id;
                    $password_setup_users[$user_id] = ['name' => $display_name, 'email' => $email];
                }
            }

            if ($user_id === (int) $_SESSION['user_id']) {
                $role = 'superadmin';
                $is_active = 1;
            }

            if (!$preserve_legacy_patient_account) {
                $stmt = $mysqli->prepare("UPDATE users SET name = ?, email = ?, role = ? WHERE tenant_id = ? AND id = ?");
                $stmt->bind_param("sssii", $display_name, $email, $role, $tenant_id, $user_id);
                $stmt->execute();
            }

            $slug = cabinet_slugify($display_name . '-' . $user_id);
            $sort_order = ($index + 1) * 10;
            if ($professional_id > 0) {
                $stmt = $mysqli->prepare("
                    UPDATE professionals
                    SET user_id = ?, display_name = ?, public_slug = ?, professional_title = ?, license_number = ?, professional_college = ?, professional_specialty = ?, public_bio = ?, public_photo_path = ?, public_email = ?, public_phone = ?, instagram_url = ?, facebook_url = ?, tiktok_url = ?, appointment_summary_email_mode = ?, is_active = ?, sort_order = ?
                    WHERE tenant_id = ? AND id = ?
                ");
                bind_params_dynamic($stmt, 'i' . str_repeat('s', 14) . 'iiii', [$user_id, $display_name, $slug, $title, $license_number, $professional_college, $specialty, $public_bio, $current_photo_path, $email, $public_phone, $instagram_url, $facebook_url, $tiktok_url, $summary_mode, $is_active, $sort_order, $tenant_id, $professional_id]);
            } else {
                $stmt = $mysqli->prepare("
                    INSERT INTO professionals (tenant_id, user_id, display_name, public_slug, professional_title, license_number, professional_college, professional_specialty, public_bio, public_photo_path, public_email, public_phone, instagram_url, facebook_url, tiktok_url, appointment_summary_email_mode, is_active, sort_order)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    ON DUPLICATE KEY UPDATE display_name = VALUES(display_name), professional_title = VALUES(professional_title), license_number = VALUES(license_number), professional_college = VALUES(professional_college), professional_specialty = VALUES(professional_specialty), public_bio = VALUES(public_bio), public_photo_path = VALUES(public_photo_path), public_email = VALUES(public_email), public_phone = VALUES(public_phone), instagram_url = VALUES(instagram_url), facebook_url = VALUES(facebook_url), tiktok_url = VALUES(tiktok_url), appointment_summary_email_mode = VALUES(appointment_summary_email_mode), is_active = VALUES(is_active), sort_order = VALUES(sort_order)
                ");
                bind_params_dynamic($stmt, 'ii' . str_repeat('s', 14) . 'ii', [$tenant_id, $user_id, $display_name, $slug, $title, $license_number, $professional_college, $specialty, $public_bio, $current_photo_path, $email, $public_phone, $instagram_url, $facebook_url, $tiktok_url, $summary_mode, $is_active, $sort_order]);
            }
            $stmt->execute();
            $saved_professional_id = $professional_id > 0 ? $professional_id : (int) $mysqli->insert_id;
            if ($saved_professional_id <= 0) {
                $stmt = $mysqli->prepare("SELECT id FROM professionals WHERE tenant_id = ? AND user_id = ? LIMIT 1");
                $stmt->bind_param("ii", $tenant_id, $user_id);
                $stmt->execute();
                $saved_row = $stmt->get_result()->fetch_assoc();
                $saved_professional_id = $saved_row ? (int) $saved_row['id'] : 0;
            }
            if ($saved_professional_id > 0) {
                cabinet_seed_professional_settings_from_superadmin($mysqli, $saved_professional_id);
                $stmt = $mysqli->prepare("
                    UPDATE professional_settings
                    SET available_session_types = ?, available_session_durations = ?, default_appointment_location = ?, default_location_id = ?, livekit_enabled = ?, video_provider = ?, livekit_recording_enabled = ?, livekit_recording_mode = ?, member_permissions_json = ?, contract_hours = ?, contract_hours_unit = ?
                    WHERE tenant_id = ? AND professional_id = ?
                ");
                $stmt->bind_param("sssiisissdsii", $professional_session_types, $professional_session_durations, $default_appointment_location, $default_location_id, $livekit_enabled, $video_provider, $livekit_recording_enabled, $livekit_recording_mode, $member_permissions_json, $contract_hours, $contract_hours_unit, $tenant_id, $saved_professional_id);
                $stmt->execute();
                if (!cabinet_save_professional_preferences($mysqli, $saved_professional_id, $professional)) {
                    throw new \Exception('No se pudieron guardar las preferencias personales del miembro.');
                }
                if (professional_knowledge_sector_columns_available($mysqli)) {
                    $stmt = $mysqli->prepare("
                        UPDATE professional_settings
                        SET knowledge_sector_mode = ?, knowledge_sector_keys_json = ?
                        WHERE tenant_id = ? AND professional_id = ?
                    ");
                    $stmt->bind_param("ssii", $knowledge_sector_mode, $knowledge_sector_keys_json, $tenant_id, $saved_professional_id);
                    $stmt->execute();
                }
            }

            if ($photo_index === $index && isset($_FILES['professional_photo']) && ($_FILES['professional_photo']['error'] ?? UPLOAD_ERR_NO_FILE) !== UPLOAD_ERR_NO_FILE) {
                if ($saved_professional_id <= 0) {
                    throw new \Exception('No se pudo localizar el profesional para guardar la foto.');
                }
                $uploaded_photo_path = save_uploaded_professional_photo($_FILES['professional_photo'], $saved_professional_id);
                $stmt = $mysqli->prepare("UPDATE professionals SET public_photo_path = ? WHERE tenant_id = ? AND id = ?");
                $stmt->bind_param("sii", $uploaded_photo_path, $tenant_id, $saved_professional_id);
                $stmt->execute();
            }
        }

        $password_setup_email_errors = [];
        foreach ($password_setup_users as $setup_user_id => $setup_user) {
            if (!send_professional_password_setup_email($mysqli, (int) $setup_user_id, $setup_user['name'], $setup_user['email'])) {
                $email_error = function_exists('get_app_email_last_error') ? get_app_email_last_error() : '';
                $password_setup_email_errors[] = $email_error ?: 'No se pudo enviar el email para crear la contraseña.';
                error_log('Alta de miembro ' . (int) $setup_user_id . ': ' . end($password_setup_email_errors));
            }
        }
        $app_name_res = $mysqli->query("SELECT app_name FROM payment_settings WHERE tenant_id = $tenant_id");
        $app_name_row = $app_name_res ? $app_name_res->fetch_assoc() : null;
        $planning_sync = fastcron_sync_professional_planning_cron($mysqli, $app_name_row['app_name'] ?? '');
        if (($planning_sync['action'] ?? '') === 'created') {
            $planning_cron_message = ' Cron de planning creado.';
        } elseif (($planning_sync['action'] ?? '') === 'linked_existing') {
            $planning_cron_message = ' Cron de planning vinculado.';
        } elseif (($planning_sync['action'] ?? '') === 'deleted') {
            $planning_cron_message = ' Cron de planning eliminado.';
        }
        $mysqli->commit();
        $settings_res = $mysqli->query("SELECT show_team_public, allow_patient_transfer, new_patient_booking_mode, new_patient_fixed_professional_id FROM payment_settings WHERE tenant_id = $tenant_id");
        $saved_settings = $settings_res ? $settings_res->fetch_assoc() : ['show_team_public' => $show_team_public, 'allow_patient_transfer' => $allow_patient_transfer, 'new_patient_booking_mode' => $new_patient_booking_mode, 'new_patient_fixed_professional_id' => $new_patient_fixed_professional_id];
        echo json_encode([
            'success' => true,
            'message' => trim('Equipo guardado correctamente.' . $planning_cron_message
                . ($password_setup_email_errors
                    ? ' El miembro se ha creado, pero no se pudo enviar el email para crear su contraseña. Motivo: ' . implode(' | ', array_unique($password_setup_email_errors))
                    : '')),
            'email_warning' => $password_setup_email_errors ? implode(' | ', array_unique($password_setup_email_errors)) : '',
            'settings' => [
                'show_team_public' => (int) ($saved_settings['show_team_public'] ?? 0),
                'allow_patient_transfer' => (int) ($saved_settings['allow_patient_transfer'] ?? 0),
                'new_patient_booking_mode' => $saved_settings['new_patient_booking_mode'] ?? 'day_first',
                'new_patient_fixed_professional_id' => (int) ($saved_settings['new_patient_fixed_professional_id'] ?? 0)
            ]
        ]);
    } catch (\Exception $e) {
        $mysqli->rollback();
        echo json_encode(['success' => false, 'error' => $e->getMessage()]);
    }
} elseif (in_array($action, [
    'subscription_overview', 'subscription_client_token', 'subscription_create',
    'subscription_change_plan', 'subscription_update_payment_method', 'subscription_cancel', 'subscription_invoices'
], true)) {
    if (!$is_superadmin) {
        echo json_encode(['success' => false, 'error' => 'Solo el superadmin puede gestionar la suscripción.']);
        exit;
    }

    try {
        $environment = praxis_braintree_environment();
        $subscription = praxis_subscription_find_current_for_tenant($mysqli, $tenant_id, $environment);
        $tenant = current_tenant();
        if (!is_array($tenant)) throw new RuntimeException('No se pudo cargar el tenant actual.');

        if ($action === 'subscription_overview') {
            $display_subscription = $subscription;
            if ($display_subscription) {
                $display_status = strtolower((string) ($display_subscription['status'] ?? ''));
                $display_period_end = strtotime((string) ($display_subscription['current_period_ends_at'] ?? ''));
                if ($display_status === 'expired'
                    || ($display_status === 'canceled' && $display_period_end && $display_period_end <= time())) {
                    $display_subscription = null;
                }
            }
            $trial = null;
            if ((int) ($tenant['registration_status'] ?? 0) === 0) {
                $trial_started_at = trim((string) ($tenant['installed_at'] ?? ''));
                if ($trial_started_at === '') $trial_started_at = trim((string) ($tenant['created_at'] ?? ''));
                $trial_started_ts = $trial_started_at !== '' ? strtotime($trial_started_at) : false;
                $trial_days = max(1, (int) ($tenant['trial_days'] ?? 15));
                $trial_ends_ts = $trial_started_ts ? strtotime('+' . $trial_days . ' days', $trial_started_ts) : false;
                if ($trial_ends_ts && $trial_ends_ts > time()) {
                    $trial = [
                        'days_remaining' => max(1, (int) ceil(($trial_ends_ts - time()) / 86400)),
                        'ends_at' => gmdate('Y-m-d H:i:s', $trial_ends_ts),
                    ];
                }
            }
            $granted_plan = (int) ($tenant['subscription_granted'] ?? 0) === 1
                ? ['until' => $tenant['subscription_granted_until'] ?? null]
                : null;
            $transactions = [];
            $stmt = $mysqli->prepare("SELECT provider_transaction_id, status, amount, currency, processed_at, invoice_id
                FROM subscription_transactions
                WHERE tenant_id = ? AND provider = 'braintree' AND environment = ?
                ORDER BY COALESCE(processed_at, created_at) DESC, id DESC LIMIT 100");
            $stmt->bind_param('is', $tenant_id, $environment);
            $stmt->execute();
            $result = $stmt->get_result();
            while ($row = $result->fetch_assoc()) $transactions[] = $row;

            echo json_encode([
                'success' => true,
                'environment' => $environment,
                'configured_plan_key' => (string) ($tenant['plan_key'] ?? 'initium'),
                'subscription' => $display_subscription,
                'trial' => $trial,
                'granted_plan' => $granted_plan,
                'transactions' => $transactions,
                'plans' => [
                    ['key' => 'novus', 'name' => 'Novus', 'price' => praxis_braintree_plan_price('novus'), 'tagline' => 'Para profesionales que necesitan una gestión sencilla y eficaz.', 'features' => ['Agenda y fichas de pacientes', 'Tareas y plantillas de trabajo', 'Documentos y adjuntos', 'Un profesional']],
                    ['key' => 'magister', 'name' => 'Magister', 'price' => praxis_braintree_plan_price('magister'), 'tagline' => 'Para centros que necesitan crecer y trabajar en equipo.', 'features' => ['Portal y reservas online', 'Hasta tres profesionales', 'Base de conocimiento y bonos', 'Calendarios y recordatorios']],
                    ['key' => 'summum', 'name' => 'Summum', 'price' => praxis_braintree_plan_price('summum'), 'tagline' => 'La experiencia completa, sin renunciar a ninguna herramienta.', 'features' => ['Pagos y facturación integrada', 'Equipo sin límite y permisos', 'Videollamadas y editores online', 'Personalización avanzada']],
                ],
                'invoices_pending_implementation' => false,
            ], JSON_UNESCAPED_UNICODE);
            exit;
        }

        if ($action === 'subscription_invoices') {
            $stmt = $mysqli->prepare("SELECT id, full_invoice_number, issued_at, plan_key, concept, taxable_base, tax_name, tax_rate, tax_amount, total, currency
                FROM sgpfacturas WHERE tenant_id = ? AND environment = 'production' ORDER BY issued_at DESC, id DESC LIMIT 250");
            $stmt->bind_param('i', $tenant_id); $stmt->execute();
            echo json_encode(['success' => true, 'invoices' => $stmt->get_result()->fetch_all(MYSQLI_ASSOC)], JSON_UNESCAPED_UNICODE);
            exit;
        }

        if ($action === 'subscription_client_token') {
            echo json_encode([
                'success' => true,
                'environment' => $environment,
                'client_token' => praxis_braintree_client_token($tenant, $environment),
            ]);
            exit;
        }

        if (($_SERVER['REQUEST_METHOD'] ?? '') !== 'POST') {
            http_response_code(405);
            echo json_encode(['success' => false, 'error' => 'Método no permitido.']);
            exit;
        }
        $csrf_token = (string) ($_POST['_subscription_csrf'] ?? '');
        $session_csrf_token = (string) ($_SESSION['subscription_csrf_token'] ?? '');
        if ($session_csrf_token === '' || !hash_equals($session_csrf_token, $csrf_token)) {
            http_response_code(403);
            echo json_encode(['success' => false, 'error' => 'La sesión ha caducado. Recarga la página antes de continuar.']);
            exit;
        }

        if ($action === 'subscription_create') {
            praxis_subscription_invoice_assert_recipient_ready($mysqli, $tenant_id);
            if ((int) ($tenant['subscription_granted'] ?? 0) === 1) {
                throw new RuntimeException('No necesitas contratar un plan mientras dispongas de una suscripción de cortesía.');
            }
            $plan_key = strtolower(trim((string) ($_POST['plan_key'] ?? '')));
            $nonce = trim((string) ($_POST['payment_method_nonce'] ?? ''));
            if (!in_array($plan_key, ['novus', 'magister', 'summum'], true)) {
                throw new InvalidArgumentException('Selecciona un plan válido.');
            }
            if ($nonce === '') throw new InvalidArgumentException('Indica una forma de pago válida.');

            $first_billing_date = null;
            if (praxis_subscription_has_access_until($subscription)) {
                if ((int) ($subscription['cancel_at_period_end'] ?? 0) !== 1) {
                    throw new RuntimeException('Ya existe una suscripción vigente en este entorno.');
                }
                $period_end = strtotime((string) ($subscription['current_period_ends_at'] ?? ''));
                if ($period_end && $period_end > time()) {
                    $first_billing_date = (new DateTimeImmutable('@' . $period_end))->setTimezone(new DateTimeZone('UTC'));
                }
            }
            $remote = praxis_braintree_create_subscription($mysqli, $tenant, $plan_key, $nonce, $first_billing_date);
            $created = praxis_subscription_find_by_provider_id($mysqli, (string) $remote->id, $environment);
            praxis_subscription_send_notification($mysqli, 'subscription_created', array_merge($created ?: [], [
                'tenant_id' => (int) $tenant['id'], 'environment' => $environment, 'plan_key' => $plan_key,
                'provider_subscription_id' => (string) $remote->id,
            ]), 'created|' . $environment . '|' . (string) $remote->id);
            echo json_encode(['success' => true, 'message' => $first_billing_date
                ? 'La nueva suscripción comenzará al finalizar el periodo ya pagado.'
                : 'Suscripción contratada correctamente.']);
            exit;
        }

        if (!$subscription) throw new RuntimeException('No existe una suscripción en este entorno.');
        if ($action === 'subscription_change_plan') {
            if ((int) ($subscription['cancel_at_period_end'] ?? 0) === 1 || !in_array((string) ($subscription['status'] ?? ''), ['active', 'past_due'], true)) {
                throw new RuntimeException('Esta suscripción ya no admite cambios de plan.');
            }
            $plan_key = strtolower(trim((string) ($_POST['plan_key'] ?? '')));
            $nonce = trim((string) ($_POST['payment_method_nonce'] ?? ''));
            if (!in_array($plan_key, ['novus', 'magister', 'summum'], true)) throw new InvalidArgumentException('Selecciona un plan válido.');
            if ($plan_key === (string) ($subscription['plan_key'] ?? '')) throw new InvalidArgumentException('Ya tienes contratado ese plan.');
            if ($nonce === '') throw new InvalidArgumentException('Confirma la forma de pago para aplicar el cambio.');
            praxis_subscription_invoice_assert_recipient_ready($mysqli, $tenant_id);
            praxis_braintree_change_plan_with_proration($mysqli, $subscription, $plan_key, $nonce);
            praxis_subscription_send_notification($mysqli, 'subscription_plan_changed', array_merge($subscription, ['plan_key' => $plan_key]),
                'plan|' . $environment . '|' . $subscription['provider_subscription_id'] . '|' . $plan_key . '|' . microtime(true));
            echo json_encode(['success' => true, 'message' => 'Plan actualizado correctamente. Se ha aplicado el prorrateo correspondiente.']);
            exit;
        }
        if ($action === 'subscription_update_payment_method') {
            if ((int) ($subscription['cancel_at_period_end'] ?? 0) === 1 || !in_array((string) ($subscription['status'] ?? ''), ['active', 'past_due', 'pending'], true)) {
                throw new RuntimeException('Esta suscripción ya no admite cambios en la forma de pago.');
            }
            $nonce = trim((string) ($_POST['payment_method_nonce'] ?? ''));
            if ($nonce === '') throw new InvalidArgumentException('Indica una forma de pago válida.');
            praxis_braintree_update_payment_method($mysqli, $subscription, $nonce);
            praxis_subscription_send_notification($mysqli, 'subscription_payment_method_updated', $subscription,
                'payment-method|' . $environment . '|' . $subscription['provider_subscription_id'] . '|' . microtime(true));
            echo json_encode(['success' => true, 'message' => 'Forma de pago actualizada correctamente.']);
            exit;
        }
        if ($action === 'subscription_cancel') {
            if ((int) ($subscription['cancel_at_period_end'] ?? 0) === 1) throw new RuntimeException('La suscripción ya está cancelada.');
            if (!in_array((string) ($subscription['status'] ?? ''), ['active', 'past_due'], true)) throw new RuntimeException('Esta suscripción no se puede cancelar.');
            praxis_braintree_cancel_subscription_at_period_end($mysqli, $subscription);
            praxis_subscription_send_notification($mysqli, 'subscription_canceled', $subscription,
                'canceled|' . $environment . '|' . $subscription['provider_subscription_id']);
            echo json_encode([
                'success' => true,
                'message' => 'La renovación se ha cancelado. Mantendrás el plan hasta el final del periodo actual.',
                'access_until' => $subscription['current_period_ends_at'] ?? null,
            ]);
            exit;
        }
    } catch (Throwable $exception) {
        error_log('Gestión de suscripción: ' . $exception->getMessage());
        echo json_encode(['success' => false, 'error' => $exception->getMessage()], JSON_UNESCAPED_UNICODE);
        exit;
    }
} elseif ($action === 'get_initial_onboarding') {
    if (!$is_superadmin) {
        echo json_encode(['success' => false, 'error' => 'Solo el superadmin puede completar el asistente inicial.']);
        exit;
    }
    ensure_payment_settings_table($mysqli);
    $tenant_res = $mysqli->query("
        SELECT tenant_name, sector_texts_key, timezone, onboarding_completed,
               onboarding_completed_at, onboarding_version, onboarding_current_step
        FROM tenants
        WHERE id = $tenant_id
        LIMIT 1
    ");
    $tenant_row = $tenant_res ? ($tenant_res->fetch_assoc() ?: []) : [];
    $settings_res = $mysqli->query("
        SELECT app_name, site_tagline, site_phone, primary_color, initial_calendar_view,
               online_booking_enabled, patient_registration_mode, appointment_delivery_mode,
               appointment_reminder_enabled, email_provider, smtp_from_email, google_connected_email,
               legal_owner_name, legal_nif, legal_address, legal_province, legal_city,
               legal_postal_code, legal_health_registry_number, legal_license_number,
               legal_professional_college, billing_country, billing_province,
               verifactu_taxpayer_type
        FROM payment_settings
        WHERE tenant_id = $tenant_id
        LIMIT 1
    ");
    $settings_row = $settings_res ? ($settings_res->fetch_assoc() ?: []) : [];
    $plan_key = plan_config_normalize_key(current_tenant()['plan_key'] ?? '', 'novus');
    $plan = plan_config_for_key($plan_key);
    $portal_plan_enabled = plan_config_feature_enabled($plan, 'patientPortal.enabled', false)
        && plan_config_feature_enabled($plan, 'onlineBooking.enabled', false);
    $reminders_plan_enabled = plan_config_feature_enabled($plan, 'reminders.patient24h', false);
    $user_id = (int) ($_SESSION['user_id'] ?? 0);
    $user_stmt = $mysqli->prepare("SELECT name FROM users WHERE tenant_id = ? AND id = ? LIMIT 1");
    $user_stmt->bind_param("ii", $tenant_id, $user_id);
    $user_stmt->execute();
    $contact_name = trim((string) ($user_stmt->get_result()->fetch_assoc()['name'] ?? ''));

    echo json_encode([
        'success' => true,
        'version' => 1,
        'completed' => (int) ($tenant_row['onboarding_completed'] ?? 0),
        'completed_version' => (int) ($tenant_row['onboarding_version'] ?? 0),
        'current_step' => max(1, min(5, (int) ($tenant_row['onboarding_current_step'] ?? 1))),
        'contact_name' => $contact_name,
        'portal_url' => tenant_public_base_url(),
        'portal_plan_enabled' => $portal_plan_enabled ? 1 : 0,
        'reminders_plan_enabled' => $reminders_plan_enabled ? 1 : 0,
        'email_configured' => (
            (($settings_row['email_provider'] ?? '') === 'google' && trim((string) ($settings_row['google_connected_email'] ?? '')) !== '')
            || (($settings_row['email_provider'] ?? '') !== 'google' && trim((string) ($settings_row['smtp_from_email'] ?? '')) !== '')
        ) ? 1 : 0,
        'sector_options' => sector_texts_available(),
        'values' => array_merge($tenant_row, $settings_row)
    ], JSON_UNESCAPED_UNICODE);
} elseif ($action === 'save_initial_onboarding_step') {
    if (!$is_superadmin) {
        echo json_encode(['success' => false, 'error' => 'Solo el superadmin puede completar el asistente inicial.']);
        exit;
    }
    ensure_payment_settings_table($mysqli);
    $step = max(1, min(5, (int) ($_POST['step'] ?? 1)));
    $next_step = min(5, $step + 1);

    try {
        $mysqli->begin_transaction();
        if ($step === 1) {
            $sector_key = trim((string) ($_POST['sector_texts_key'] ?? ''));
            $timezone = trim((string) ($_POST['timezone'] ?? 'Europe/Madrid'));
            $country = strtoupper(trim((string) ($_POST['country'] ?? 'ES'))) === 'ES' ? 'ES' : 'OT';
            $province = trim((string) ($_POST['province'] ?? ''));
            $address = trim((string) ($_POST['address'] ?? ''));
            $city = trim((string) ($_POST['city'] ?? ''));
            $postal_code = trim((string) ($_POST['postal_code'] ?? ''));
            if (!sector_texts_validate_key($sector_key) || !sector_texts_read_file($sector_key)) {
                throw new \Exception('Selecciona un sector válido.');
            }
            if (!app_valid_timezone($timezone)) {
                throw new \Exception('Selecciona una zona horaria válida.');
            }
            if ($country === 'ES' && $province === '') {
                throw new \Exception('Selecciona la provincia.');
            }
            $stmt = $mysqli->prepare("UPDATE tenants SET sector_texts_key = ?, timezone = ?, onboarding_current_step = ? WHERE id = ?");
            $stmt->bind_param("ssii", $sector_key, $timezone, $next_step, $tenant_id);
            $stmt->execute();

            $tax_system = in_array($province, ['Las Palmas', 'Santa Cruz de Tenerife'], true) ? 'igic' : 'iva';
            $tax_rate = $tax_system === 'igic' ? 7.0 : 21.0;
            $billing_province = $country === 'ES' ? $province : '';
            $stmt = $mysqli->prepare("
                UPDATE payment_settings
                SET sector_texts_key = ?, billing_country = ?, billing_province = ?,
                    legal_address = ?, legal_province = ?, legal_city = ?, legal_postal_code = ?,
                    billing_tax_system = ?, billing_default_tax_rate = ?
                WHERE tenant_id = ?
            ");
            $stmt->bind_param("ssssssssdi", $sector_key, $country, $billing_province, $address, $province, $city, $postal_code, $tax_system, $tax_rate, $tenant_id);
            $stmt->execute();
        } elseif ($step === 2) {
            $owner = trim((string) ($_POST['legal_owner_name'] ?? ''));
            $nif = strtoupper(trim((string) ($_POST['legal_nif'] ?? '')));
            $taxpayer_type = ($_POST['verifactu_taxpayer_type'] ?? '') === 'company' ? 'company' : 'self_employed';
            $health_registry = trim((string) ($_POST['legal_health_registry_number'] ?? ''));
            $license = trim((string) ($_POST['legal_license_number'] ?? ''));
            $college = trim((string) ($_POST['legal_professional_college'] ?? ''));
            $stmt = $mysqli->prepare("
                UPDATE payment_settings
                SET legal_owner_name = ?, legal_nif = ?, legal_health_registry_number = ?,
                    legal_license_number = ?, legal_professional_college = ?
                WHERE tenant_id = ?
            ");
            $stmt->bind_param("sssssi", $owner, $nif, $health_registry, $license, $college, $tenant_id);
            $stmt->execute();
            $official_date = verifactu_official_start_date($taxpayer_type);
            $stmt = $mysqli->prepare("
                UPDATE payment_settings
                SET verifactu_taxpayer_type = ?, verifactu_start_date = ?
                WHERE tenant_id = ?
                  AND COALESCE(verifactu_environment, 0) = 0
                  AND verifactu_activated_at IS NULL
            ");
            $stmt->bind_param("ssi", $taxpayer_type, $official_date, $tenant_id);
            $stmt->execute();
            $mysqli->query("UPDATE tenants SET onboarding_current_step = $next_step WHERE id = $tenant_id");
        } elseif ($step === 3) {
            $app_name = trim((string) ($_POST['app_name'] ?? ''));
            $tagline = trim((string) ($_POST['site_tagline'] ?? ''));
            $phone = trim((string) ($_POST['site_phone'] ?? ''));
            $color = strtolower(trim((string) ($_POST['primary_color'] ?? '#4285f4')));
            $initial_view = trim((string) ($_POST['initial_calendar_view'] ?? 'month'));
            if ($app_name === '') {
                throw new \Exception('Indica el título de tu espacio.');
            }
            if (!preg_match('/^#[0-9a-f]{6}$/', $color)) {
                throw new \Exception('Selecciona un color válido.');
            }
            if (!in_array($initial_view, ['dashboard', 'month', 'week', 'agenda', 'list', 'patients', 'upcoming', 'remember'], true)) {
                $initial_view = 'month';
            }
            $stmt = $mysqli->prepare("UPDATE payment_settings SET app_name = ?, site_tagline = ?, site_phone = ?, primary_color = ?, initial_calendar_view = ? WHERE tenant_id = ?");
            $stmt->bind_param("sssssi", $app_name, $tagline, $phone, $color, $initial_view, $tenant_id);
            $stmt->execute();
            $stmt = $mysqli->prepare("UPDATE tenants SET tenant_name = ?, app_name = ?, onboarding_current_step = ? WHERE id = ?");
            $stmt->bind_param("ssii", $app_name, $app_name, $next_step, $tenant_id);
            $stmt->execute();
        } elseif ($step === 4) {
            $plan_key = plan_config_normalize_key(current_tenant()['plan_key'] ?? '', 'novus');
            $plan = plan_config_for_key($plan_key);
            $portal_allowed = plan_config_feature_enabled($plan, 'patientPortal.enabled', false)
                && plan_config_feature_enabled($plan, 'onlineBooking.enabled', false);
            $portal_enabled = $portal_allowed && ($_POST['portal_enabled'] ?? '') === '1' ? 1 : 0;
            $registration_mode = ($_POST['patient_registration_mode'] ?? '') === 'open' ? 'open' : 'invite';
            $delivery = (string) ($_POST['appointment_delivery_mode'] ?? 'both');
            if (!in_array($delivery, ['both', 'presencial', 'online'], true)) {
                $delivery = 'both';
            }
            $stmt = $mysqli->prepare("
                UPDATE payment_settings
                SET online_booking_enabled = ?, patient_registration_mode = ?,
                    appointment_delivery_mode = ?
                WHERE tenant_id = ?
            ");
            $stmt->bind_param("issi", $portal_enabled, $registration_mode, $delivery, $tenant_id);
            $stmt->execute();
            $mysqli->query("UPDATE tenants SET onboarding_current_step = $next_step WHERE id = $tenant_id");
        } else {
            $stmt = $mysqli->prepare("
                UPDATE tenants
                SET onboarding_completed = 1, onboarding_completed_at = NOW(),
                    onboarding_version = 1, onboarding_current_step = 5
                WHERE id = ?
            ");
            $stmt->bind_param("i", $tenant_id);
            $stmt->execute();
        }
        $mysqli->commit();
        echo json_encode([
            'success' => true,
            'message' => $step === 5 ? 'Configuración inicial completada.' : 'Paso guardado.',
            'next_step' => $next_step,
            'completed' => $step === 5 ? 1 : 0
        ], JSON_UNESCAPED_UNICODE);
    } catch (\Throwable $exception) {
        $mysqli->rollback();
        echo json_encode(['success' => false, 'error' => $exception->getMessage()], JSON_UNESCAPED_UNICODE);
    }
} elseif ($action === 'get_payment_settings') {
    verifactu_sync_environment($mysqli, $tenant_id);
    ensure_payment_settings_table($mysqli);
    ensure_cabinet_schema($mysqli);
    dashboard_config_ensure_files();
    sector_texts_ensure_payment_column($mysqli);
    $sms_columns_available = column_exists($mysqli, 'payment_settings', 'sms_provider')
        && column_exists($mysqli, 'payment_settings', 'sms_reminder_hours');
    $sms_settings_select = $sms_columns_available
        ? "sms_provider, sms_sender, sms_username, sms_reminder_enabled, sms_reminder_hours"
        : "'none' AS sms_provider, '' AS sms_sender, '' AS sms_username, 0 AS sms_reminder_enabled, 24 AS sms_reminder_hours";
    $sms_secret_select = $sms_columns_available
        ? "sms_password IS NOT NULL AND sms_password != '' AS has_sms_password,
               sms_api_key IS NOT NULL AND sms_api_key != '' AS has_sms_api_key"
        : "0 AS has_sms_password,
               0 AS has_sms_api_key";

    $res = $mysqli->query("
        SELECT app_name, site_tagline, site_phone, profile_image_path, landing_image_path, primary_color, show_profile_image_public, show_prices_public, show_contact_public, discount_period_enabled, discount_period_start_date, discount_period_end_date, discount_show_public, online_booking_enabled, patient_registration_mode, patient_tasks_visible_default, work_plan_task_status_enabled, initial_calendar_view, bonuses_enabled, create_compensation_bonus_on_paid_cancel, online_payment_enabled, environment, merchant_code, terminal,
               appointment_price, online_appointment_price, couple_appointment_price, online_couple_appointment_price, admin_notification_email,
               appointment_delivery_mode, available_session_types, available_session_durations, display_effective_duration_enabled, display_duration_offset_minutes,
               appointment_reminder_enabled, appointment_second_reminder_enabled, appointment_second_reminder_hours,
               min_booking_notice_days, max_booking_notice_days, appointment_start_time, appointment_end_time, break_start_time, break_end_time,
               available_weekdays,
               email_provider, smtp_host, smtp_port, smtp_username, smtp_secure, smtp_from_email, smtp_from_name,
               $sms_settings_select,
               google_connected_email, google_redirect_uri, calendar_provider, google_calendar_enabled, google_calendar_id,
               icloud_calendar_email, icloud_calendar_url, microsoft_connected_email, microsoft_calendar_id, send_patient_calendar_link,
               fastcron_reminder_cron_id,
               legal_owner_name, legal_nif, legal_address, legal_province, legal_city, legal_postal_code,
               legal_email, legal_health_registry_number, legal_license_number, legal_professional_college, legal_uses_non_technical_cookies, legal_terms_notes,
               billing_enabled, billing_country, billing_province, billing_session_concept, billing_report_concept,
               billing_tax_system, billing_default_tax_mode, billing_default_tax_rate, billing_exemption_reason,
               verifactu_enabled, verifactu_environment, verifactu_taxpayer_type,
               verifactu_activation_mode, verifactu_start_date, verifactu_activated_at,
               allow_patient_transfer, dashboard_config_mode, sector_texts_key,
               merchant_key IS NOT NULL AND merchant_key != '' AS has_merchant_key,
               smtp_password IS NOT NULL AND smtp_password != '' AS has_smtp_password,
               $sms_secret_select,
               google_refresh_token IS NOT NULL AND google_refresh_token != '' AS has_google_refresh_token,
               microsoft_refresh_token IS NOT NULL AND microsoft_refresh_token != '' AS has_microsoft_refresh_token,
               icloud_calendar_app_password IS NOT NULL AND icloud_calendar_app_password != '' AS has_icloud_calendar_app_password,
               fastcron_api_key IS NOT NULL AND fastcron_api_key != '' AS has_fastcron_api_key
        FROM payment_settings
        WHERE tenant_id = $tenant_id
    ");
    $settings = $res->fetch_assoc();
    $current_professional_id = current_professional_id_for_user($mysqli, (int) ($_SESSION['user_id'] ?? 0));
    if ($current_professional_id > 0) {
        $professional_settings = cabinet_get_effective_professional_settings($mysqli, $current_professional_id);
        foreach ($professional_settings as $key => $value) {
            $settings[$key] = $value;
        }
    }
    $settings['current_professional_id'] = $current_professional_id;
    $settings['platform_email_configured'] = platform_email_is_configured() ? 1 : 0;
    $tenant = function_exists('current_tenant') ? current_tenant() : null;
    $settings['tenant_timezone'] = tenant_timezone(is_array($tenant) ? $tenant : null);
    $tenant_plan_key = plan_config_normalize_key(is_array($tenant) ? ($tenant['plan_key'] ?? '') : '', '');
    $settings['plan_key'] = $tenant_plan_key !== '' ? $tenant_plan_key : 'novus';
    $dashboard_config_mode = dashboard_config_effective_mode_from_db($mysqli, $settings['plan_key']);
    $settings['dashboard_config_mode'] = $dashboard_config_mode;
    $settings['dashboard_config'] = dashboard_config_for_mode($dashboard_config_mode);
    $settings['plan_config'] = plan_config_for_key($settings['plan_key']);
    $settings['verifactu_company_official_date'] = verifactu_official_start_date('company');
    $settings['verifactu_self_employed_official_date'] = verifactu_official_start_date('self_employed');
    if (!plan_config_feature_enabled($settings['plan_config'], 'billing.enabled', false)) {
        $settings['billing_enabled'] = 0;
    }
    $settings['livekit_plan_enabled'] = plan_config_feature_enabled($settings['plan_config'], 'videoCalls.integrated', plan_config_feature_enabled($settings['plan_config'], 'livekit.enabled', false)) ? 1 : 0;
    if (!$settings['livekit_plan_enabled']) {
        $settings['livekit_enabled'] = 0;
        $settings['video_provider'] = 'manual';
    }
    $settings['custom_domain_plan_enabled'] = plan_config_feature_enabled($settings['plan_config'], 'branding.customDomain', false) ? 1 : 0;
    $settings['custom_domain'] = '';
    if ($settings['custom_domain_plan_enabled']) {
        ensure_tenant_domains_runtime_table($mysqli);
        $stmt = $mysqli->prepare("SELECT domain FROM tenant_domains WHERE tenant_id = ? ORDER BY is_primary DESC, id ASC LIMIT 1");
        $stmt->bind_param("i", $tenant_id);
        $stmt->execute();
        $settings['custom_domain'] = tenant_domain_normalize($stmt->get_result()->fetch_assoc()['domain'] ?? '');
    }
    $settings['google_oauth_configured'] = google_oauth_credentials_configured() ? 1 : 0;
    $settings['microsoft_oauth_configured'] = microsoft_oauth_credentials_configured() ? 1 : 0;
    $sector_texts_key = sector_texts_validate_key($settings['sector_texts_key'] ?? '') ? $settings['sector_texts_key'] : sector_texts_default_key();
    $settings['sector_texts_key'] = sector_texts_read_file($sector_texts_key) ? $sector_texts_key : sector_texts_default_key();
    $settings['knowledge_base_has_sector_data'] = knowledge_base_sector_has_data($mysqli, $settings['sector_texts_key']) ? 1 : 0;
    $settings['sector_texts'] = sector_texts_for_key($settings['sector_texts_key'], $settings['dashboard_config'], $settings['plan_config']);
    $settings['sector_texts_options'] = sector_texts_available();

    echo json_encode([
        'success' => true,
        'settings' => $settings,
        'message_templates' => message_templates_get_all($mysqli),
        'message_template_variables' => message_template_available_variables(),
        'services' => fetch_appointment_services($mysqli),
        'locations' => fetch_appointment_locations($mysqli),
        'bonuses' => fetch_appointment_bonuses($mysqli)
    ]);
} elseif ($action === 'get_message_template') {
    ensure_message_templates_table($mysqli);
    $template_key = trim((string) ($_GET['template_key'] ?? ''));
    $template = message_template_get($mysqli, $template_key);
    if (!$template) {
        echo json_encode(['success' => false, 'error' => 'Plantilla no valida.']);
        exit;
    }
    echo json_encode([
        'success' => true,
        'template' => $template,
        'variables' => message_template_available_variables()
    ]);
} elseif ($action === 'save_message_template') {
    ensure_message_templates_table($mysqli);
    try {
        $template_key = trim((string) ($_POST['template_key'] ?? ''));
        $subject = trim((string) ($_POST['subject'] ?? ''));
        $body = trim((string) ($_POST['body'] ?? ''));
        if ($template_key === 'appointment_email_reminder' && $subject === '') {
            $subject = message_template_default_subject($template_key);
        }
        message_template_save($mysqli, $template_key, $subject, $body);
        echo json_encode([
            'success' => true,
            'message' => 'Plantilla guardada correctamente.',
            'template' => message_template_get($mysqli, $template_key)
        ]);
    } catch (\Exception $e) {
        echo json_encode(['success' => false, 'error' => $e->getMessage()]);
    }
} elseif ($action === 'get_dashboard_custom_config') {
    if (!$is_superadmin) {
        echo json_encode(['success' => false, 'error' => 'Solo el superadmin puede editar la configuracion personalizada.']);
        exit;
    }
    dashboard_config_ensure_files();
    $files = dashboard_config_files();
    $raw = file_get_contents($files['custom']);
    echo json_encode(['success' => true, 'json' => $raw === false ? '' : $raw]);
} elseif ($action === 'get_custom_domain') {
    if (!$is_superadmin) {
        echo json_encode(['success' => false, 'error' => 'Solo el superadmin puede configurar dominios personalizados.']);
        exit;
    }
    $enabled = app_feature_enabled_from_db($mysqli, 'branding.customDomain', false);
    ensure_tenant_domains_runtime_table($mysqli);
    $domain = '';
    if ($enabled) {
        $stmt = $mysqli->prepare("SELECT domain FROM tenant_domains WHERE tenant_id = ? ORDER BY is_primary DESC, id ASC LIMIT 1");
        $stmt->bind_param("i", $tenant_id);
        $stmt->execute();
        $domain = tenant_domain_normalize($stmt->get_result()->fetch_assoc()['domain'] ?? '');
    }
    echo json_encode([
        'success' => true,
        'enabled' => $enabled ? 1 : 0,
        'domain' => $domain
    ]);
} elseif ($action === 'save_custom_domain') {
    if (!$is_superadmin) {
        echo json_encode(['success' => false, 'error' => 'Solo el superadmin puede configurar dominios personalizados.']);
        exit;
    }
    if (!app_feature_enabled_from_db($mysqli, 'branding.customDomain', false)) {
        echo json_encode(['success' => false, 'error' => 'El dominio personalizado solo esta disponible en el plan Summum.']);
        exit;
    }

    ensure_tenant_domains_runtime_table($mysqli);
    $error = '';
    $domain = normalize_custom_domain_input($_POST['domain'] ?? '', $error);
    if ($error !== '') {
        echo json_encode(['success' => false, 'error' => $error]);
        exit;
    }

    $mysqli->begin_transaction();
    try {
        $stmt = $mysqli->prepare("DELETE FROM tenant_domains WHERE tenant_id = ?");
        $stmt->bind_param("i", $tenant_id);
        $stmt->execute();

        if ($domain !== '') {
            $stmt = $mysqli->prepare("INSERT INTO tenant_domains (tenant_id, domain, is_primary) VALUES (?, ?, 1)");
            $stmt->bind_param("is", $tenant_id, $domain);
            $stmt->execute();
        }

        $mysqli->commit();
        echo json_encode([
            'success' => true,
            'domain' => $domain,
            'message' => $domain !== '' ? 'Dominio personalizado guardado.' : 'Dominio personalizado eliminado.'
        ]);
    } catch (\mysqli_sql_exception $e) {
        $mysqli->rollback();
        $message = ((int) $e->getCode() === 1062)
            ? 'Ese dominio ya esta asignado a otro tenant.'
            : 'No se pudo guardar el dominio personalizado.';
        echo json_encode(['success' => false, 'error' => $message]);
    }
} elseif ($action === 'signature_settings') {
    if (!plan_feature_enabled_from_db($mysqli, 'digitalSignature.tenant', false)) {
        echo json_encode(['success' => false, 'error' => 'La firma digital no está disponible en este plan.']);
        exit;
    }
    echo json_encode(['success' => true, 'settings' => signature_settings_values($mysqli)]);
} elseif ($action === 'save_signature_settings') {
    if (!plan_feature_enabled_from_db($mysqli, 'digitalSignature.tenant', false)) {
        echo json_encode(['success' => false, 'error' => 'La firma digital no está disponible en este plan.']);
        exit;
    }
    $auto_invoices = !empty($_POST['signature_auto_invoices']) ? 1 : 0;
    $auto_reports = !empty($_POST['signature_auto_reports']) ? 1 : 0;
    $auto_documents = !empty($_POST['signature_auto_documents']) ? 1 : 0;
    $stmt = $mysqli->prepare("
        UPDATE payment_settings
        SET signature_auto_invoices = ?, signature_auto_reports = ?, signature_auto_documents = ?
        WHERE tenant_id = ?
    ");
    $stmt->bind_param("iiii", $auto_invoices, $auto_reports, $auto_documents, $tenant_id);
    $stmt->execute();
    echo json_encode(['success' => true, 'message' => 'Configuración de firma guardada.', 'settings' => signature_settings_values($mysqli)]);
} elseif ($action === 'signature_certificate_status') {
    try {
        $certificate_professional_id = signature_certificate_professional_id($mysqli);
        $certificate_status = stampbyme_certificate_status($tenant_id, $certificate_professional_id);
        $certificate_status['effective_available'] = stampbyme_signature_available($tenant_id, $certificate_professional_id);
        $certificate_status['using_tenant_fallback'] = $certificate_professional_id !== null
            && empty($certificate_status['available'])
            && stampbyme_signature_available($tenant_id, null);
        if ($certificate_professional_id === null && !empty($certificate_status['available'])) {
            $legal_nif_stmt = $mysqli->prepare("
                SELECT legal_nif
                FROM payment_settings
                WHERE tenant_id = ?
                LIMIT 1
            ");
            $legal_nif_stmt->bind_param('i', $tenant_id);
            $legal_nif_stmt->execute();
            $legal_nif = stampbyme_normalize_tax_id((string) (
                $legal_nif_stmt->get_result()->fetch_assoc()['legal_nif'] ?? ''
            ));
            $certificate_tax_ids = array_values(array_filter(array_map(
                'stampbyme_normalize_tax_id',
                (array) ($certificate_status['tax_ids'] ?? [])
            )));
            $certificate_status['legal_nif_mismatch'] = $legal_nif !== ''
                && $certificate_tax_ids
                && !in_array($legal_nif, $certificate_tax_ids, true);
        } else {
            $certificate_status['legal_nif_mismatch'] = false;
        }
        echo json_encode(['success' => true, 'certificate' => $certificate_status]);
    } catch (\Throwable $e) {
        echo json_encode(['success' => false, 'error' => $e->getMessage()]);
    }
} elseif ($action === 'save_signature_certificate') {
    try {
        $certificate_professional_id = signature_certificate_professional_id($mysqli);
        $status = stampbyme_import_pkcs12(
            $tenant_id,
            $_FILES['signature_certificate'] ?? [],
            (string) ($_POST['certificate_password'] ?? ''),
            $certificate_professional_id
        );
        app_log($mysqli, [
            'action' => 'signature_certificate_imported',
            'status' => 'ok',
            'target_type' => $certificate_professional_id ? 'professional' : 'tenant',
            'target_id' => $certificate_professional_id ?: $tenant_id,
            'title' => 'Certificado de firma importado',
            'message' => (string) ($status['subject'] ?? ''),
            'metadata' => [
                'fingerprint_sha256' => (string) ($status['fingerprint_sha256'] ?? ''),
                'valid_to' => (string) ($status['valid_to'] ?? '')
            ]
        ]);
        echo json_encode(['success' => true, 'message' => 'Certificado importado correctamente.', 'certificate' => $status]);
    } catch (\Throwable $e) {
        app_log($mysqli, [
            'action' => 'signature_certificate_import_failed',
            'status' => 'error',
            'target_type' => 'tenant',
            'target_id' => $tenant_id,
            'title' => 'Error al importar certificado de firma',
            'message' => $e->getMessage()
        ]);
        echo json_encode(['success' => false, 'error' => $e->getMessage()]);
    }
} elseif ($action === 'remove_signature_certificate') {
    $certificate_professional_id = signature_certificate_professional_id($mysqli);
    stampbyme_remove_certificate($tenant_id, $certificate_professional_id);
    app_log($mysqli, [
        'action' => 'signature_certificate_removed',
        'status' => 'ok',
        'target_type' => $certificate_professional_id ? 'professional' : 'tenant',
        'target_id' => $certificate_professional_id ?: $tenant_id,
        'title' => 'Certificado de firma eliminado'
    ]);
    echo json_encode(['success' => true, 'message' => 'Certificado eliminado correctamente.', 'certificate' => stampbyme_certificate_status($tenant_id, $certificate_professional_id)]);
} elseif ($action === 'sign_uploaded_pdf') {
    try {
        $upload = $_FILES['pdf'] ?? [];
        if (($upload['error'] ?? UPLOAD_ERR_NO_FILE) !== UPLOAD_ERR_OK || empty($upload['tmp_name'])) {
            throw new \RuntimeException('Selecciona un archivo PDF.');
        }
        if ((int) ($upload['size'] ?? 0) <= 0 || (int) ($upload['size'] ?? 0) > 25 * 1024 * 1024) {
            throw new \RuntimeException('El PDF no puede superar 25 MB.');
        }
        $header = file_get_contents((string) $upload['tmp_name'], false, null, 0, 5);
        if ($header !== '%PDF-') {
            throw new \RuntimeException('El archivo seleccionado no parece un PDF válido.');
        }
        $professional_id = signature_certificate_professional_id($mysqli);
        $signedPdf = stampbyme_sign_pdf_file(
            $tenant_id,
            (string) $upload['tmp_name'],
            $professional_id
        );
        $baseName = pathinfo((string) ($upload['name'] ?? 'documento.pdf'), PATHINFO_FILENAME);
        $filename = pdf_safe_filename($baseName . '-firmado.pdf');
        app_log($mysqli, [
            'action' => 'pdf_signed',
            'status' => 'ok',
            'target_type' => 'tenant',
            'target_id' => $tenant_id,
            'title' => 'PDF firmado digitalmente',
            'message' => (string) ($upload['name'] ?? $filename),
            'metadata' => ['sha256' => hash('sha256', $signedPdf), 'source' => 'manual_upload']
        ]);
        header_remove('Content-Type');
        header('Content-Type: application/pdf');
        header('Content-Length: ' . strlen($signedPdf));
        header('Content-Disposition: attachment; filename="' . $filename . '"');
        echo $signedPdf;
    } catch (\Throwable $e) {
        header_remove('Content-Type');
        http_response_code(422);
        header('Content-Type: text/plain; charset=UTF-8');
        echo 'No se pudo firmar el PDF: ' . $e->getMessage();
    }
    exit;
} elseif ($action === 'suggested_legal_documents') {
    $definitions = suggested_legal_document_definitions_for_current_sector($mysqli);
    $existing_keys = suggested_legal_document_existing_keys($mysqli, $definitions);
    $suggestions = [];
    foreach ($definitions as $key => $definition) {
        $suggestions[] = [
            'key' => $key,
            'title' => $definition['title'] ?? '',
            'category' => $definition['category'] ?? '',
            'version_label' => $definition['version_label'] ?? '',
            'is_required' => (int) ($definition['is_required'] ?? 0),
            'already_added' => !empty($existing_keys[$key]) && ($existing_keys[$key]['template_type'] ?? '') === 'generated' ? 1 : 0,
            'needs_upgrade' => !empty($existing_keys[$key]) && ($existing_keys[$key]['template_type'] ?? 'uploaded_pdf') !== 'generated' ? 1 : 0
        ];
    }
    echo json_encode(['success' => true, 'suggestions' => $suggestions]);
} elseif ($action === 'preview_suggested_legal_document') {
    $definitions = suggested_legal_document_definitions_for_current_sector($mysqli);
    $key = trim((string) ($_GET['key'] ?? ''));
    if ($key === '' || empty($definitions[$key])) {
        http_response_code(404);
        header_remove('Content-Type');
        header('Content-Type: text/plain; charset=UTF-8');
        echo 'Plantilla no encontrada';
        exit;
    }
    try {
        $definition = $definitions[$key];
        $document = [
            'title' => $definition['title'] ?? 'Consentimiento',
            'category' => $definition['category'] ?? '',
            'version_label' => $definition['version_label'] ?? '',
            'content_json' => json_encode(suggested_legal_document_content($definition), JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES),
        ];
        $temporary = tempnam(sys_get_temp_dir(), 'sgp_legal_preview_');
        legal_template_generate_pdf_file($mysqli, $document, $tenant_id, 0, $temporary, true);
        $filename = pdf_safe_filename($document['title']);
        header_remove('Content-Type');
        header('Content-Type: application/pdf');
        header('Content-Disposition: inline; filename="' . addslashes($filename) . '"');
        header('Content-Length: ' . filesize($temporary));
        readfile($temporary);
        @unlink($temporary);
    } catch (\Throwable $e) {
        http_response_code(500);
        header_remove('Content-Type');
        header('Content-Type: text/plain; charset=UTF-8');
        echo 'No se pudo generar la vista previa: ' . $e->getMessage();
    }
    exit;
} elseif ($action === 'create_suggested_legal_documents') {
    ensure_legal_document_tables($mysqli);
    $definitions = suggested_legal_document_definitions_for_current_sector($mysqli);
    $keys = $_POST['keys'] ?? [];
    if (is_string($keys)) {
        $keys = [$keys];
    }
    if (!is_array($keys)) {
        $keys = [];
    }
    $keys = array_values(array_unique(array_filter(array_map('strval', $keys))));
    if (!$keys) {
        echo json_encode(['success' => false, 'error' => 'Selecciona al menos una plantilla sugerida.']);
        exit;
    }

    $created = 0;
    $skipped = 0;
    $created_by = (int) ($_SESSION['user_id'] ?? 0);
    try {
        $existing_keys = suggested_legal_document_existing_keys($mysqli, $definitions);
        $duplicated_keys = array_values(array_filter($keys, static function ($key) use ($existing_keys) {
            return !empty($existing_keys[$key]) && ($existing_keys[$key]['template_type'] ?? '') === 'generated';
        }));
        if ($duplicated_keys) {
            echo json_encode([
                'success' => false,
                'error' => count($duplicated_keys) === 1
                    ? 'Este consentimiento ya está añadido.'
                    : 'Algunos de los consentimientos seleccionados ya están añadidos.'
            ], JSON_UNESCAPED_UNICODE);
            exit;
        }
        foreach ($keys as $key) {
            if (empty($definitions[$key])) {
                continue;
            }
            $definition = $definitions[$key];
            $title = (string) ($definition['title'] ?? 'Documento legal');
            $category = (string) ($definition['category'] ?? '');
            $version_label = (string) ($definition['version_label'] ?? 'Plantilla SGPraxis');
            $is_active = 1;
            $is_required = (int) ($definition['is_required'] ?? 0);
            $content_json = json_encode(suggested_legal_document_content($definition), JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
            $template_type = 'generated';
            $existing_id = 0;

            if (!empty($existing_keys[$key]['id'])) {
                $existing_id = (int) $existing_keys[$key]['id'];
                $stmt = $mysqli->prepare("
                    UPDATE legal_documents
                    SET title = ?, category = ?, version_label = ?, template_type = ?, content_json = ?, source_key = ?,
                        is_active = 1, is_required = ?, template_revision = template_revision + 1
                    WHERE tenant_id = ? AND id = ?
                ");
                $stmt->bind_param("ssssssiii", $title, $category, $version_label, $template_type, $content_json, $key, $is_required, $tenant_id, $existing_id);
            } else {
                $stmt = $mysqli->prepare("
                    INSERT INTO legal_documents
                        (tenant_id, title, category, version_label, template_type, content_json, source_key,
                         is_active, is_required, created_by)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                ");
                $stmt->bind_param("issssssiii", $tenant_id, $title, $category, $version_label, $template_type, $content_json, $key, $is_active, $is_required, $created_by);
            }
            $stmt->execute();
            $created++;
            $existing_keys[$key] = [
                'id' => !empty($existing_id) ? $existing_id : (int) $mysqli->insert_id,
                'template_type' => 'generated',
            ];
        }

        if ($created > 0) {
            app_log($mysqli, [
                'action' => 'suggested_legal_documents_created',
                'target_type' => 'legal_document',
                'target_id' => null,
                'status' => 'ok',
                'title' => 'Plantillas legales sugeridas anadidas',
                'message' => $created . ' plantilla(s)'
            ]);
        }

        $message = $created === 0
            ? 'Las plantillas seleccionadas ya estaban añadidas.'
            : ($created === 1 ? 'Plantilla sugerida anadida correctamente.' : 'Plantillas sugeridas anadidas correctamente.');
        echo json_encode([
            'success' => true,
            'message' => $message,
            'created' => $created,
            'skipped' => $skipped
        ]);
    } catch (\Throwable $e) {
        echo json_encode(['success' => false, 'error' => 'No se pudieron generar las plantillas sugeridas: ' . $e->getMessage()]);
    }
} elseif ($action === 'service_legal_document_mappings') {
    ensure_legal_document_tables($mysqli);
    ensure_appointment_services_tables($mysqli);

    $services = [];
    $stmt = $mysqli->prepare("
        SELECT id, name, is_active
        FROM appointment_services
        WHERE tenant_id = ?
        ORDER BY is_active DESC, sort_order ASC, id ASC
    ");
    $stmt->bind_param("i", $tenant_id);
    $stmt->execute();
    $res = $stmt->get_result();
    while ($row = $res->fetch_assoc()) {
        $services[] = [
            'id' => (int) $row['id'],
            'name' => (string) ($row['name'] ?? ''),
            'is_active' => (int) ($row['is_active'] ?? 0)
        ];
    }

    $documents = [];
    $stmt = $mysqli->prepare("
        SELECT id, title, category, is_required
        FROM legal_documents
        WHERE tenant_id = ? AND is_active = 1
        ORDER BY title ASC, id ASC
    ");
    $stmt->bind_param("i", $tenant_id);
    $stmt->execute();
    $res = $stmt->get_result();
    while ($row = $res->fetch_assoc()) {
        $documents[] = [
            'id' => (int) $row['id'],
            'title' => (string) ($row['title'] ?? ''),
            'category' => (string) ($row['category'] ?? ''),
            'is_required' => (int) ($row['is_required'] ?? 0)
        ];
    }

    $mappings = [];
    $stmt = $mysqli->prepare("
        SELECT service_id, legal_document_id
        FROM service_legal_documents
        WHERE tenant_id = ?
        ORDER BY service_id, legal_document_id
    ");
    $stmt->bind_param("i", $tenant_id);
    $stmt->execute();
    $res = $stmt->get_result();
    while ($row = $res->fetch_assoc()) {
        $service_id = (int) $row['service_id'];
        if (!isset($mappings[$service_id])) {
            $mappings[$service_id] = [];
        }
        $mappings[$service_id][] = (int) $row['legal_document_id'];
    }

    echo json_encode([
        'success' => true,
        'services' => $services,
        'documents' => $documents,
        'mappings' => $mappings
    ]);
} elseif ($action === 'save_service_legal_document_mappings') {
    ensure_legal_document_tables($mysqli);
    ensure_appointment_services_tables($mysqli);

    $decoded = json_decode((string) ($_POST['mappings'] ?? '{}'), true);
    if (!is_array($decoded)) {
        echo json_encode(['success' => false, 'error' => 'El mapeo enviado no es válido.']);
        exit;
    }

    $valid_services = [];
    $stmt = $mysqli->prepare("SELECT id FROM appointment_services WHERE tenant_id = ?");
    $stmt->bind_param("i", $tenant_id);
    $stmt->execute();
    $res = $stmt->get_result();
    while ($row = $res->fetch_assoc()) {
        $valid_services[(int) $row['id']] = true;
    }

    $valid_documents = [];
    $stmt = $mysqli->prepare("SELECT id FROM legal_documents WHERE tenant_id = ? AND is_active = 1");
    $stmt->bind_param("i", $tenant_id);
    $stmt->execute();
    $res = $stmt->get_result();
    while ($row = $res->fetch_assoc()) {
        $valid_documents[(int) $row['id']] = true;
    }

    $pairs = [];
    foreach ($decoded as $service_id_raw => $document_ids) {
        $service_id = (int) $service_id_raw;
        if (empty($valid_services[$service_id]) || !is_array($document_ids)) {
            continue;
        }
        foreach (array_unique(array_map('intval', $document_ids)) as $document_id) {
            if (!empty($valid_documents[$document_id])) {
                $pairs[] = [$service_id, $document_id];
            }
        }
    }

    $created_by = (int) ($_SESSION['user_id'] ?? 0);
    try {
        $mysqli->begin_transaction();
        $stmt = $mysqli->prepare("DELETE FROM service_legal_documents WHERE tenant_id = ?");
        $stmt->bind_param("i", $tenant_id);
        $stmt->execute();

        if ($pairs) {
            $stmt = $mysqli->prepare("
                INSERT INTO service_legal_documents
                    (tenant_id, service_id, legal_document_id, created_by)
                VALUES (?, ?, ?, ?)
            ");
            foreach ($pairs as [$service_id, $document_id]) {
                $stmt->bind_param("iiii", $tenant_id, $service_id, $document_id, $created_by);
                $stmt->execute();
            }
        }
        $mysqli->commit();

        app_log($mysqli, [
            'action' => 'service_legal_documents_updated',
            'target_type' => 'legal_document',
            'status' => 'ok',
            'title' => 'Consentimientos asignados a servicios',
            'message' => count($pairs) . ' asignación(es) guardada(s)'
        ]);
        echo json_encode([
            'success' => true,
            'message' => 'Asignaciones de consentimientos guardadas correctamente.',
            'mapping_count' => count($pairs)
        ]);
    } catch (\Throwable $e) {
        $mysqli->rollback();
        echo json_encode(['success' => false, 'error' => 'No se pudieron guardar las asignaciones: ' . $e->getMessage()]);
